export default ") -> bool:\\n    try:\\n        docling_document = _get_docling_document_class()\\n    except DoclingDependencyError:\\n        return all(hasattr(value, method) for method in (\\\"export_to_markdown\\\", \\\"export_to_html\\\", \\\"export_to_text\\\"))\\n    return isinstance(value, docling_document)\\n\\n\\ndef coerce_docling_document(doc: Any) -> Any:\\n    if all(hasattr(doc, method) for method in (\\\"export_to_markdown\\\", \\\"export_to_html\\\", \\\"export_to_text\\\")):\\n        return doc\\n    if isinstance(doc, dict):\\n        return _get_docling_document_class().model_validate(doc)\\n    if _is_docling_document(doc):\\n        return doc\\n\\n    msg = f\\\"Expected a DoclingDocument, got {type(doc).__name__}.\\\"\\n    raise TypeError(msg)\\n\\n\\ndef extract_docling_documents(\\n    data_inputs: Data | list[Data] | DataFrame, doc_key: str\\n) -> tuple[list[DoclingDocument], str | None]:\\n    \\\"\\\"\\\"Extract DoclingDocument objects from data inputs.\\n\\n    Args:\\n        data_inputs: The data inputs containing DoclingDocument objects\\n        doc_key: The key/column name to look for DoclingDocument objects\\n\\n    Returns:\\n        A tuple of (documents, warning_message) where warning_message is None if no warning\\n\\n    Raises:\\n        TypeError: If the data cannot be extracted or is invalid\\n    \\\"\\\"\\\"\\n    documents: list[DoclingDocument] = []\\n    warning_message: str | None = None\\n\\n    if isinstance(data_inputs, DataFrame):\\n        if not len(data_inputs):\\n            msg = \\\"DataFrame is empty\\\"\\n            raise TypeError(msg)\\n\\n        # Primary: Check for exact column name match\\n        if doc_key in data_inputs.columns:\\n            try:\\n                documents = data_inputs[doc_key].tolist()\\n            except Exception as e:\\n                msg = f\\\"Error extracting DoclingDocument from DataFrame column '{doc_key}': {e}\\\"\\n                raise TypeError(msg) from e\\n        else:\\n            # Fallback: Search all columns for DoclingDocument objects\\n            found_column = None\\n            for col in data_inputs.columns:\\n                try:\\n                    # Check if this column contains DoclingDocument objects\\n                    sample = data_inputs[col].dropna().iloc[0] if len(data_inputs[col].dropna()) > 0 else None\\n                    if sample is not None and _is_docling_document(sample):\\n                        found_column = col\\n                        break\\n                except (IndexError, AttributeError):\\n                    continue\\n\\n            if found_column:\\n                warning_message = (\\n                    f\\\"Column '{doc_key}' not found, but found DoclingDocument objects in column '{found_column}'. \\\"\\n                    f\\\"Using '{found_column}' instead. Consider updating the 'Doc Key' parameter.\\\"\\n                )\\n                logger.warning(warning_message)\\n                try:\\n                    documents = data_inputs[found_column].tolist()\\n                except Exception as e:\\n                    msg = f\\\"Error extracting DoclingDocument from DataFrame column '{found_column}': {e}\\\"\\n                    raise TypeError(msg) from e\\n            else:\\n                # Provide helpful error message\\n                available_columns = list(data_inputs.columns)\\n                msg = (\\n                    f\\\"Column '{doc_key}' not found in DataFrame. \\\"\\n                    f\\\"Available columns: {available_columns}. \\\"\\n                    f\\\"\\\\n\\\\nPossible solutions:\\\\n\\\"\\n                    f\\\"1. Use the 'Data' output from Docling component instead of 'DataFrame' output\\\\n\\\"\\n                    f\\\"2. Update the 'Doc Key' parameter to match one of the available columns\\\\n\\\"\\n                    f\\\"3. If using VLM pipeline, try using the standard pipeline\\\"\\n                )\\n                raise TypeError(msg)\\n    else:\\n        if not data_inputs:\\n            msg = \\\"No data inputs provided\\\"\\n            raise TypeError(msg)\\n\\n        if isinstance(data_inputs, Data):\\n            if doc_key not in data_inputs.data:\\n                msg = (\\n                    f\\\"'{doc_key}' field not available in the input Data. \\\"\\n                    \\\"Check that your input is a DoclingDocument. \\\"\\n                    \\\"You can use the Docling component to convert your input to a DoclingDocument.\\\"\\n                )\\n                raise TypeError(msg)\\n            documents = [data_inputs.data[doc_key]]\\n        else:\\n            try:\\n                documents = [\\n                    input_.data[doc_key]\\n                    for input_ in data_inputs\\n                    if (\\n                        isinstance(input_, Data)\\n                        and doc_key in input_.data\\n                        and _is_docling_document(input_.data[doc_key])\\n                    )\\n                ]\\n                if not documents:\\n                    msg = f\\\"No valid Data inputs found in {type(data_inputs)}\\\"\\n                    raise TypeError(msg)\\n            except AttributeError as e:\\n                msg = f\\\"Invalid input type in collection: {e}\\\"\\n                raise TypeError(msg) from e\\n    return documents, warning_message\\n\\n\\ndef _unwrap_secrets(obj):\\n    if isinstance(obj, SecretStr):\\n        return obj.get_secret_value()\\n    if isinstance(obj, dict):\\n        return {k: _unwrap_secrets(v) for k, v in obj.items()}\\n    if isinstance(obj, list):\\n        return [_unwrap_secrets(v) for v in obj]\\n    return obj\\n\\n\\ndef _dump_with_secrets(model: BaseModel):\\n    return _unwrap_secrets(model.model_dump(mode=\\\"python\\\", round_trip=True))\\n\\n\\ndef _serialize_pydantic_model(model: BaseModel):\\n    return {\\n        \\\"__class_path__\\\": f\\\"{model.__class__.__module__}.{model.__class__.__name__}\\\",\\n        \\\"config\\\": _dump_with_secrets(model),\\n    }\\n\\n\\ndef _deserialize_pydantic_model(data: dict):\\n    module_name, class_name = data[\\\"__class_path__\\\"].rsplit(\\\".\\\", 1)\\n    module = importlib.import_module(module_name)\\n    cls = getattr(module, class_name)\\n    adapter = TypeAdapter(cls)\\n    return adapter.validate_python(data[\\\"config\\\"])\\n\\n\\n# Global cache for DocumentConverter instances\\n# This cache persists across multiple runs and thread invocations\\n@lru_cache(maxsize=4)\\ndef _get_cached_converter(\\n    pipeline: str,\\n    ocr_engine: str,\\n    *,\\n    do_picture_classification: bool,\\n    pic_desc_config_hash: str | None,\\n):\\n    \\\"\\\"\\\"Create and cache a DocumentConverter instance based on configuration.\\n\\n    This function uses LRU caching to maintain DocumentConverter instances in memory,\\n    eliminating the 15-20 minute model loading time on subsequent runs.\\n\\n    Args:\\n        pipeline: The pipeline type (\\\"standard\\\" or \\\"vlm\\\")\\n        ocr_engine: The OCR engine to use\\n        do_picture_classification: Whether to enable picture classification\\n        pic_desc_config_hash: Hash of the picture description config (for cache key)\\n\\n    Returns:\\n        A cached or newly created DocumentConverter instance\\n    \\\"\\\"\\\"\\n    from docling.datamodel.base_models import InputFormat\\n    from docling.datamodel.pipeline_options import OcrOptions, PdfPipelineOptions, VlmPipelineOptions\\n    from docling.document_converter import DocumentConverter, FormatOption, PdfFormatOption\\n    from docling.models.factories import get_ocr_factory\\n    from docling.pipeline.vlm_pipeline import VlmPipeline\\n\\n    logger.info(f\\\"Creating DocumentConverter for pipeline={pipeline}, ocr_engine={ocr_engine}\\\")\\n\\n    # Configure the standard PDF pipeline\\n    def _get_standard_opts() -> PdfPipelineOptions:\\n        pipeline_options = PdfPipelineOptions()\\n        pipeline_options.do_ocr = ocr_engine not in {\\\"\\\", \\\"None\\\"}\\n        if pipeline_options.do_ocr:\\n            ocr_factory = get_ocr_factory(\\n                allow_external_plugins=False,\\n            )\\n            ocr_options: OcrOptions = ocr_factory.create_options(\\n                kind=ocr_engine,\\n            )\\n            pipeline_options.ocr_options = ocr_options\\n\\n        pipeline_options.do_picture_classification = do_picture_classification\\n\\n        # Note: pic_desc_config_hash is for cache key only\\n        # Actual picture description is handled separately (non-cached path)\\n        _ = pic_desc_config_hash  # Mark as intentionally unused\\n\\n        return pipeline_options\\n\\n    # Configure the VLM pipeline\\n    def _get_vlm_opts() -> VlmPipelineOptions:\\n        return VlmPipelineOptions()\\n\\n    if pipeline == \\\"standard\\\":\\n        pdf_format_option = PdfFormatOption(\\n            pipeline_options=_get_standard_opts(),\\n        )\\n    elif pipeline == \\\"vlm\\\":\\n        pdf_format_option = PdfFormatOption(pipeline_cls=VlmPipeline, pipeline_options=_get_vlm_opts())\\n    else:\\n        msg = f\\\"Unknown pipeline: {pipeline!r}\\\"\\n        raise ValueError(msg)\\n\\n    format_options: dict[InputFormat, FormatOption] = {\\n        InputFormat.PDF: pdf_format_option,\\n        InputFormat.IMAGE: pdf_format_option,\\n    }\\n\\n    return DocumentConverter(format_options=format_options)\\n\\n\\nclass _ShutdownRequestedError(Exception):\\n    \\\"\\\"\\\"Raised by check_shutdown() to unwind the docling_worker call stack.\\\"\\\"\\\"\\n\\n\\ndef docling_worker(\\n    *,\\n    file_paths: list[str],\\n    queue,\\n    pipeline: str,\\n    ocr_engine: str,\\n    do_picture_classification: bool,\\n    pic_desc_config: dict | None,\\n    pic_desc_prompt: str,\\n):\\n    \\\"\\\"\\\"Worker function for processing files with Docling using threading.\\n\\n    This function now uses a globally cached DocumentConverter instance,\\n    significantly reducing processing time on subsequent runs from 15-20 minutes\\n    to just seconds.\\n    \\\"\\\"\\\"\\n    # Signal handling for graceful shutdown\\n    shutdown_requested = False\\n\\n    def signal_handler(signum: int, frame) -> None:  # noqa: ARG001\\n        \\\"\\\"\\\"Handle shutdown signals gracefully.\\\"\\\"\\\"\\n        nonlocal shutdown_requested\\n        signal_names: dict[int, str] = {signal.SIGTERM: \\\"SIGTERM\\\", signal.SIGINT: \\\"SIGINT\\\"}\\n        signal_name = signal_names.get(signum, f\\\"signal {signum}\\\")\\n\\n        logger.debug(f\\\"Docling worker received {signal_name}, initiating graceful shutdown...\\\")\\n        shutdown_requested = True\\n\\n        # Send shutdown notification to parent thread\\n        with suppress(Exception):\\n            queue.put({\\\"error\\\": f\\\"Worker interrupted by {signal_name}\\\", \\\"shutdown\\\": True})\\n\\n        # NOTE: Do NOT call sys.exit() here. This function runs in a thread\\n        # (not a subprocess), so sys.exit() would raise SystemExit which can\\n        # crash the host process in single-worker setups. Instead, just set\\n        # the flag and let check_shutdown() terminate the worker loop.\\n\\n    def check_shutdown() -> None:\\n        \\\"\\\"\\\"Check if shutdown was requested and raise to unwind if so.\\\"\\\"\\\"\\n        if shutdown_requested:\\n            logger.info(\\\"Shutdown requested, exiting worker...\\\")\\n\\n            with suppress(Exception):\\n                queue.put({\\\"error\\\": \\\"Worker shutdown requested\\\", \\\"shutdown\\\": True})\\n\\n            raise _ShutdownRequestedError\\n\\n    # Register signal handlers early\\n    try:\\n        signal.signal(signal.SIGTERM, signal_handler)\\n        signal.signal(signal.SIGINT, signal_handler)\\n        logger.debug(\\\"Signal handlers registered for graceful shutdown\\\")\\n    except (OSError, ValueError) as e:\\n        # Some signals might not be available on all platforms\\n        logger.warning(f\\\"Warning: Could not register signal handlers: {e}\\\")\\n\\n    # Check for shutdown before heavy imports\\n    check_shutdown()\\n\\n    try:\\n        from docling.datamodel.base_models import ConversionStatus\\n\\n        importlib.import_module(\\\"docling.datamodel.pipeline_options\\\")\\n        importlib.import_module(\\\"docling.document_converter\\\")\\n        importlib.import_module(\\\"docling.models.factories\\\")\\n        importlib.import_module(\\\"docling.pipeline.vlm_pipeline\\\")\\n\\n        # Check for shutdown after imports\\n        check_shutdown()\\n        logger.debug(\\\"Docling dependencies loaded successfully\\\")\\n\\n    except ModuleNotFoundError:\\n        msg = (\\n            \\\"Docling is an optional dependency of Langflow. \\\"\\n            \\\"Install with `uv pip install 'langflow[docling]'` \\\"\\n            \\\"or refer to the documentation\\\"\\n        )\\n        queue.put({\\\"error\\\": msg})\\n        return\\n    except ImportError as e:\\n        # A different import failed (e.g., a transitive dependency); preserve details.\\n        queue.put({\\\"error\\\": f\\\"Failed to import a Docling dependency: {e}\\\"})\\n        return\\n    except KeyboardInterrupt:\\n        logger.warning(\\\"KeyboardInterrupt during imports, exiting...\\\")\\n        queue.put({\\\"error\\\": \\\"Worker interrupted during imports\\\", \\\"shutdown\\\": True})\\n        return\\n\\n    # Use cached converter instead of creating new one each time\\n    # This is the key optimization that eliminates 15-20 minute model load times\\n    def _get_converter() -> DocumentConverter:\\n        check_shutdown()  # Check before heavy operations\\n\\n        # For now, we don't support pic_desc_config caching due to serialization complexity\\n        # This is a known limitation that can be addressed in a future enhancement\\n        if pic_desc_config:\\n            logger.warning(\\n                \\\"Picture description with LLM is not yet supported with cached converters. \\\"\\n                \\\"Using non-cached converter for this request.\\\"\\n            )\\n            # Fall back to creating a new converter (old behavior)\\n            from docling.datamodel.base_models import InputFormat\\n            from docling.datamodel.pipeline_options import PdfPipelineOptions\\n            from docling.document_converter import DocumentConverter, FormatOption, PdfFormatOption\\n            from docling.models.factories import get_ocr_factory\\n\\n            try:\\n                from langchain_docling.picture_description import PictureDescriptionLangChainOptions\\n            except ImportError as e:\\n                msg = (\\n                    \\\"langchain-docling is not installed. Install it with \\\"\\n                    \\\"`uv pip install 'langflow[docling-image-description]'` or \\\"\\n                    \\\"`uv pip install 'lfx-docling[image-description]'`.\\\"\\n                )\\n                raise ImportError(msg) from e\\n\\n            pipeline_options = PdfPipelineOptions()\\n            pipeline_options.do_ocr = ocr_engine not in {\\\"\\\", \\\"None\\\"}\\n            if pipeline_options.do_ocr:\\n                ocr_factory = get_ocr_factory(allow_external_plugins=False)\\n                ocr_options = ocr_factory.create_options(kind=ocr_engine)\\n                pipeline_options.ocr_options = ocr_options\\n\\n            pipeline_options.do_picture_classification = do_picture_classification\\n            pic_desc_llm = _deserialize_pydantic_model(pic_desc_config)\\n            logger.info(\\\"Docling enabling the picture description stage.\\\")\\n            pipeline_options.do_picture_description = True\\n            pipeline_options.allow_external_plugins = True\\n            pipeline_options.picture_description_options = PictureDescriptionLangChainOptions(\\n                llm=pic_desc_llm,\\n                prompt=pic_desc_prompt,\\n            )\\n\\n            pdf_format_option = PdfFormatOption(pipeline_options=pipeline_options)\\n            format_options: dict[InputFormat, FormatOption] = {\\n                InputFormat.PDF: pdf_format_option,\\n                InputFormat.IMAGE: pdf_format_option,\\n            }\\n            return DocumentConverter(format_options=format_options)\\n\\n        # Use cached converter - this is where the magic happens!\\n        # First run: creates and caches converter (15-20 min)\\n        # Subsequent runs: reuses cached converter (seconds)\\n        pic_desc_config_hash = None  # Will be None since we checked above\\n        return _get_cached_converter(\\n            pipeline=pipeline,\\n            ocr_engine=ocr_engine,\\n            do_picture_classification=do_picture_classification,\\n            pic_desc_config_hash=pic_desc_config_hash,\\n        )\\n\\n    try:\\n        # Check for shutdown before creating converter (can be slow)\\n        check_shutdown()\\n        logger.info(f\\\"Initializing {pipeline} pipeline with OCR: {ocr_engine or 'disabled'}\\\")\\n\\n        converter = _get_converter()\\n\\n        # Check for shutdown before processing files\\n        check_shutdown()\\n        logger.info(f\\\"Starting to process {len(file_paths)} files...\\\")\\n\\n        # Process files with periodic shutdown checks\\n        results = []\\n        for i, file_path in enumerate(file_paths):\\n            # Check for shutdown before processing each file\\n            check_shutdown()\\n\\n            logger.debug(f\\\"Processing file {i + 1}/{len(file_paths)}: {file_path}\\\")\\n\\n            try:\\n                single_result = converter.convert_all([file_path])\\n                results.extend(single_result)\\n                check_shutdown()\\n\\n            except ImportError as import_error:\\n                # Simply pass ImportError to main process for handling\\n                queue.put(\\n                    {\\\"error\\\": str(import_error), \\\"error_type\\\": \\\"import_error\\\", \\\"original_exception\\\": \\\"ImportError\\\"}\\n                )\\n                return\\n\\n            except (OSError, ValueError, RuntimeError) as file_error:\\n                error_msg = str(file_error)\\n\\n                # Check for specific dependency errors and identify the dependency name\\n                dependency_name = None\\n                if \\\"ocrmac is not correctly installed\\\" in error_msg:\\n                    dependency_name = \\\"ocrmac\\\"\\n                elif \\\"easyocr\\\" in error_msg and \\\"not installed\\\" in error_msg:\\n                    dependency_name = \\\"easyocr\\\"\\n                elif \\\"tesserocr\\\" in error_msg and \\\"not installed\\\" in error_msg:\\n                    dependency_name = \\\"tesserocr\\\"\\n                elif \\\"rapidocr\\\" in error_msg and \\\"not installed\\\" in error_msg:\\n                    dependency_name = \\\"rapidocr\\\"\\n\\n                if dependency_name:\\n                    queue.put(\\n                        {\\n                            \\\"error\\\": error_msg,\\n                            \\\"error_type\\\": \\\"dependency_error\\\",\\n                            \\\"dependency_name\\\": dependency_name,\\n                            \\\"original_exception\\\": type(file_error).__name__,\\n                        }\\n                    )\\n                    return\\n\\n                # If not a dependency error, log and continue with other files\\n                logger.error(f\\\"Error processing file {file_path}: {file_error}\\\")\\n                check_shutdown()\\n\\n            except Exception as file_error:  # noqa: BLE001\\n                logger.error(f\\\"Unexpected error processing file {file_path}: {file_error}\\\")\\n                check_shutdown()\\n\\n        # Final shutdown check before sending results\\n        check_shutdown()\\n\\n        # Process the results while maintaining the original structure\\n        processed_data = [\\n            {\\\"document\\\": res.document, \\\"file_path\\\": str(res.input.file), \\\"status\\\": res.status.name}\\n            if res.status == ConversionStatus.SUCCESS\\n            else None\\n            for res in results\\n        ]\\n\\n        logger.info(f\\\"Successfully processed {len([d for d in processed_data if d])} files\\\")\\n        queue.put(processed_data)\\n\\n    except _ShutdownRequestedError:\\n        logger.info(\\\"Docling worker stopped by shutdown request\\\")\\n        return\\n    except KeyboardInterrupt:\\n        logger.warning(\\\"KeyboardInterrupt during processing, exiting gracefully...\\\")\\n        queue.put({\\\"error\\\": \\\"Worker interrupted during processing\\\", \\\"shutdown\\\": True})\\n        return\\n    except Exception as e:  # noqa: BLE001\\n        if shutdown_requested:\\n            logger.exception(\\\"Exception occurred during shutdown, exiting...\\\")\\n            return\\n\\n        # Send any processing error to the main process with traceback\\n        error_info = {\\\"error\\\": str(e), \\\"traceback\\\": traceback.format_exc()}\\n        logger.error(f\\\"Error in worker: {error_info}\\\")\\n        queue.put(error_info)\\n    finally:\\n        logger.info(\\\"Docling worker finishing...\\\")\\n        # Ensure we don't leave any hanging processes\\n        if shutdown_requested:\\n            logger.debug(\\\"Worker shutdown completed\\\")\\n        else:\\n            logger.debug(\\\"Worker completed normally\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/data/storage_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d74d870e40ad39f76fd9ddffab055ef9e7ead61c3d6df6b592d9503c53f326a\",\"content\":\"\\\"\\\"\\\"Storage-aware file utilities for components.\\n\\nThis module provides utilities that work with both local files and remote files\\nstored in the storage service.\\n\\nTODO: Can abstract these into the storage service interface and update\\nimplementations.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.deps import get_settings_service, get_storage_service\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.file_path_security import enforce_local_file_access\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\n    from lfx.services.storage.service import StorageService\\n\\n# Constants for path parsing\\nEXPECTED_PATH_PARTS = 2  # Path format: \\\"flow_id/filename\\\"\\n\\n\\ndef _is_existing_local_file(file_path: str) -> bool:\\n    \\\"\\\"\\\"Return True when file_path is an absolute path to a real local file.\\n\\n    Under S3 storage some callers still hand us genuine local paths (e.g. the\\n    Langflow Assistant injects the installed lfx components dir into a Directory\\n    node). A real local file is never an S3 key, so it must be read from disk\\n    instead of being parsed as \\\"flow_id/filename\\\". See issue #13798.\\n\\n    The check is restricted to ABSOLUTE paths on purpose: S3 keys are always\\n    relative (\\\"flow_id/filename\\\"), so requiring an absolute path makes it\\n    impossible to mistake a relative S3 key for a same-named file that happens\\n    to exist relative to the process CWD.\\n    \\\"\\\"\\\"\\n    try:\\n        path_obj = Path(file_path)\\n        return path_obj.is_absolute() and path_obj.is_file()\\n    except OSError:\\n        return False\\n\\n\\ndef _confine_local_read(file_path: str, resolve_path: Callable[[str], str] | None = None) -> str:\\n    \\\"\\\"\\\"Apply local-file containment to the S3 branch's real-local-file short-circuit.\\n\\n    ``_is_existing_local_file`` is a deliberate escape hatch (#13798), but it must not become a\\n    way to read server files that ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` blocks on local\\n    storage. The restriction is documented as a property of the built-in file-reading\\n    components, not of the storage backend, so it has to hold on both branches.\\n\\n    When the caller supplies ``resolve_path`` (components pass a closure that runs\\n    ``enforce_local_file_access`` with the authenticated user/flow scope) that resolver is\\n    authoritative and full tenant isolation applies. Callers with no scope to offer fall back to\\n    the storage-root floor: the path must stay under ``config_dir`` and must not be one of the\\n    server-managed secret/key/DB files. Both are no-ops when the restriction is disabled, so the\\n    default (unrestricted) #13798 behavior is unchanged.\\n    \\\"\\\"\\\"\\n    if resolve_path is not None:\\n        return resolve_path(file_path)\\n    return str(enforce_local_file_access(file_path, allow_storage_root=True))\\n\\n\\ndef parse_storage_path(path: str) -> tuple[str, str] | None:\\n    \\\"\\\"\\\"Parse a storage service path into flow_id and filename.\\n\\n    Storage service paths follow the format: flow_id/filename\\n    This should only be called when storage_type == \\\"s3\\\".\\n\\n    Args:\\n        path: The storage service path in format \\\"flow_id/filename\\\"\\n\\n    Returns:\\n        tuple[str, str] | None: (flow_id, filename) or None if invalid format\\n    \\\"\\\"\\\"\\n    if not path or \\\"/\\\" not in path:\\n        return None\\n\\n    parts = path.split(\\\"/\\\", 1)\\n    if len(parts) != EXPECTED_PATH_PARTS or not parts[0] or not parts[1]:\\n        return None\\n\\n    return parts[0], parts[1]\\n\\n\\nasync def read_file_bytes(\\n    file_path: str,\\n    storage_service: StorageService | None = None,\\n    resolve_path: Callable[[str], str] | None = None,\\n) -> bytes:\\n    \\\"\\\"\\\"Read file bytes from either storage service or local filesystem.\\n\\n    Args:\\n        file_path: Path to the file (S3 key format \\\"flow_id/filename\\\" or local path)\\n        storage_service: Optional storage service instance (will get from deps if not provided)\\n        resolve_path: Optional function that resolves and confines a local path (components\\n                     pass a closure around ``enforce_local_file_access``). Used for local\\n                     storage, and for the S3 branch's real-local-file short-circuit.\\n\\n    Returns:\\n        bytes: The file content\\n\\n    Raises:\\n        FileNotFoundError: If the file doesn't exist\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n\\n    if settings.storage_type == \\\"s3\\\":\\n        if _is_existing_local_file(file_path):\\n            return Path(_confine_local_read(file_path, resolve_path)).read_bytes()\\n\\n        parsed = parse_storage_path(file_path)\\n        if not parsed:\\n            msg = f\\\"Invalid S3 path format: {file_path}. Expected 'flow_id/filename'\\\"\\n            raise ValueError(msg)\\n\\n        if storage_service is None:\\n            storage_service = get_storage_service()\\n\\n        flow_id, filename = parsed\\n        return await storage_service.get_file(flow_id, filename)\\n\\n    # For local storage, resolve path if resolver provided\\n    if resolve_path:\\n        file_path = resolve_path(file_path)\\n\\n    path_obj = Path(file_path)\\n    if not path_obj.exists():\\n        msg = f\\\"File not found: {file_path}\\\"\\n        raise FileNotFoundError(msg)\\n\\n    return path_obj.read_bytes()\\n\\n\\nasync def read_file_text(\\n    file_path: str,\\n    encoding: str = \\\"utf-8\\\",\\n    storage_service: StorageService | None = None,\\n    resolve_path: Callable[[str], str] | None = None,\\n    newline: str | None = None,\\n) -> str:\\n    r\\\"\\\"\\\"Read file text from either storage service or local filesystem.\\n\\n    Args:\\n        file_path: Path to the file (storage service path or local path)\\n        encoding: Text encoding to use\\n        storage_service: Optional storage service instance\\n        resolve_path: Optional function that resolves and confines a local path (components\\n                     pass a closure around ``enforce_local_file_access``). Used for local\\n                     storage, and for the S3 branch's real-local-file short-circuit.\\n        newline: Newline mode (None for default, \\\"\\\" for universal newlines like CSV).\\n                 When set to \\\"\\\", normalizes all line endings to \\\\\\\\n for consistency.\\n\\n    Returns:\\n        str: The file content as text\\n\\n    Raises:\\n        FileNotFoundError: If the file doesn't exist\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n\\n    if settings.storage_type == \\\"s3\\\":\\n        content = await read_file_bytes(file_path, storage_service, resolve_path)\\n        text = content.decode(encoding)\\n        # Normalize newlines for S3 when newline=\\\"\\\" is specified (universal newline mode)\\n        if newline == \\\"\\\":\\n            # Convert all line endings to \\\\n (matches Python's universal newline mode)\\n            text = text.replace(\\\"\\\\r\\\\n\\\", \\\"\\\\n\\\").replace(\\\"\\\\r\\\", \\\"\\\\n\\\")\\n        return text\\n    # For local storage, resolve path if resolver provided\\n    if resolve_path:\\n        file_path = resolve_path(file_path)\\n\\n    path_obj = Path(file_path)\\n    if newline is not None:\\n        with path_obj.open(newline=newline, encoding=encoding) as f:  # noqa: ASYNC230\\n            return f.read()\\n    return path_obj.read_text(encoding=encoding)\\n\\n\\ndef get_file_size(file_path: str, storage_service: StorageService | None = None) -> int:\\n    \\\"\\\"\\\"Get file size from either storage service or local filesystem.\\n\\n    Note: This is a sync wrapper - for async code, use the storage service directly.\\n\\n    Args:\\n        file_path: Path to the file (S3 key format \\\"flow_id/filename\\\" or absolute local path)\\n        storage_service: Optional storage service instance\\n\\n    Returns:\\n        int: File size in bytes\\n\\n    Raises:\\n        FileNotFoundError: If the file doesn't exist\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n\\n    if settings.storage_type == \\\"s3\\\":\\n        if _is_existing_local_file(file_path):\\n            # Same containment floor as ``read_file_bytes``: without it this is a size/existence\\n            # oracle (via ``file_exists``) for any server file under restriction.\\n            return Path(_confine_local_read(file_path)).stat().st_size\\n\\n        parsed = parse_storage_path(file_path)\\n        if not parsed:\\n            msg = f\\\"Invalid S3 path format: {file_path}. Expected 'flow_id/filename'\\\"\\n            raise ValueError(msg)\\n\\n        if storage_service is None:\\n            storage_service = get_storage_service()\\n\\n        flow_id, filename = parsed\\n        return run_until_complete(storage_service.get_file_size(flow_id, filename))\\n\\n    # Local file system\\n    path_obj = Path(file_path)\\n    if not path_obj.exists():\\n        msg = f\\\"File not found: {file_path}\\\"\\n        raise FileNotFoundError(msg)\\n\\n    return path_obj.stat().st_size\\n\\n\\ndef file_exists(file_path: str, storage_service: StorageService | None = None) -> bool:\\n    \\\"\\\"\\\"Check if a file exists in either storage service or local filesystem.\\n\\n    Args:\\n        file_path: Path to the file (S3 key format \\\"flow_id/filename\\\" or absolute local path)\\n        storage_service: Optional storage service instance\\n\\n    Returns:\\n        bool: True if the file exists\\n    \\\"\\\"\\\"\\n    try:\\n        get_file_size(file_path, storage_service)\\n    except (FileNotFoundError, ValueError):\\n        return False\\n    else:\\n        return True\\n\\n\\n# Magic bytes signatures for common image formats\\nMIN_IMAGE_HEADER_SIZE = 12  # Minimum bytes needed to detect image type\\n\\nIMAGE_SIGNATURES: dict[str, list[tuple[bytes, int]]] = {\\n    \\\"jpeg\\\": [(b\\\"\\\\xff\\\\xd8\\\\xff\\\", 0)],\\n    \\\"jpg\\\": [(b\\\"\\\\xff\\\\xd8\\\\xff\\\", 0)],\\n    \\\"png\\\": [(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\", 0)],\\n    \\\"gif\\\": [(b\\\"GIF87a\\\", 0), (b\\\"GIF89a\\\", 0)],\\n    \\\"webp\\\": [(b\\\"RIFF\\\", 0)],  # WebP starts with RIFF, then has WEBP at offset 8\\n    \\\"bmp\\\": [(b\\\"BM\\\", 0)],\\n    \\\"tiff\\\": [(b\\\"II*\\\\x00\\\", 0), (b\\\"MM\\\\x00*\\\", 0)],  # Little-endian and big-endian TIFF\\n}\\n\\n\\ndef detect_image_type_from_bytes(content: bytes) -> str | None:\\n    \\\"\\\"\\\"Detect the actual image type from file content using magic bytes.\\n\\n    Args:\\n        content: The file content bytes (at least first 12 bytes needed)\\n\\n    Returns:\\n        str | None: The detected image type (e.g., \\\"jpeg\\\", \\\"png\\\") or None if not recognized\\n    \\\"\\\"\\\"\\n    if len(content) < MIN_IMAGE_HEADER_SIZE:\\n        return None\\n\\n    # Check WebP specifically (needs to check both RIFF and WEBP)\\n    if content[:4] == b\\\"RIFF\\\" and content[8:12] == b\\\"WEBP\\\":\\n        return \\\"webp\\\"\\n\\n    # Check other image signatures\\n    for image_type, signatures in IMAGE_SIGNATURES.items():\\n        if image_type == \\\"webp\\\":\\n            continue  # Already handled above\\n        for signature, offset in signatures:\\n            if content[offset : offset + len(signature)] == signature:\\n                return image_type\\n\\n    return None\\n\\n\\ndef validate_image_content_type(\\n    file_path: str,\\n    content: bytes | None = None,\\n    storage_service: StorageService | None = None,\\n    resolve_path: Callable[[str], str] | None = None,\\n) -> tuple[bool, str | None]:\\n    \\\"\\\"\\\"Validate that an image file's content matches its declared extension.\\n\\n    This prevents errors like \\\"Image does not match the provided media type image/png\\\"\\n    when a JPEG file is saved with a .png extension.\\n\\n    Only rejects files when we can definitively detect a mismatch. Files with\\n    unrecognized content are allowed through (they may fail later, but that's\\n    better than false positives blocking valid files).\\n\\n    Args:\\n        file_path: Path to the image file\\n        content: Optional pre-read file content bytes. If not provided, will read from file.\\n        storage_service: Optional storage service instance for S3 files\\n        resolve_path: Optional function to resolve relative paths\\n\\n    Returns:\\n        tuple[bool, str | None]: (is_valid, error_message)\\n            - (True, None) if the content matches the extension, is unrecognized, or file is not an image\\n            - (False, error_message) if there's a definite mismatch\\n    \\\"\\\"\\\"\\n    # Get the file extension\\n    path_obj = Path(file_path)\\n    extension = path_obj.suffix[1:].lower() if path_obj.suffix else \\\"\\\"\\n\\n    # Only validate image files\\n    image_extensions = {\\\"jpeg\\\", \\\"jpg\\\", \\\"png\\\", \\\"gif\\\", \\\"webp\\\", \\\"bmp\\\", \\\"tiff\\\"}\\n    if extension not in image_extensions:\\n        return True, None\\n\\n    # Read content if not provided\\n    if content is None:\\n        try:\\n            content = run_until_complete(read_file_bytes(file_path, storage_service, resolve_path))\\n        except (FileNotFoundError, ValueError):\\n            # Can't read file - let it pass, will fail later with better error\\n            return True, None\\n\\n    # Detect actual image type\\n    detected_type = detect_image_type_from_bytes(content)\\n\\n    # If we can't detect the type, the file is not a valid image\\n    if detected_type is None:\\n        return False, (\\n            f\\\"File '{path_obj.name}' has extension '.{extension}' but its content \\\"\\n            f\\\"is not a valid image format. The file may be corrupted, empty, or not a real image.\\\"\\n        )\\n\\n    # Normalize extensions for comparison (jpg == jpeg, tif == tiff)\\n    extension_normalized = \\\"jpeg\\\" if extension == \\\"jpg\\\" else extension\\n    detected_normalized = \\\"jpeg\\\" if detected_type == \\\"jpg\\\" else detected_type\\n\\n    if extension_normalized != detected_normalized:\\n        return False, (\\n            f\\\"File '{path_obj.name}' has extension '.{extension}' but contains \\\"\\n            f\\\"'{detected_type.upper()}' image data. This mismatch will cause API errors. \\\"\\n            f\\\"Please rename the file with the correct extension '.{detected_type}' or \\\"\\n            f\\\"re-save it in the correct format.\\\"\\n        )\\n\\n    return True, None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/data/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e862e0651f9624e484f5e58b80f174ee89a015fec677de0ad7ec22bf2349a8f6\",\"content\":\"import contextlib\\nimport logging\\nimport tempfile\\nimport unicodedata\\nfrom collections.abc import Callable\\nfrom concurrent import futures\\nfrom contextvars import copy_context\\nfrom io import BytesIO\\nfrom pathlib import Path\\n\\nimport chardet\\nimport orjson\\nimport yaml\\nfrom defusedxml import ElementTree\\nfrom pypdf import PdfReader\\n\\nfrom lfx.base.data.storage_utils import read_file_bytes\\nfrom lfx.schema.data import Data\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.async_helpers import run_until_complete\\n\\nlogger = logging.getLogger(__name__)\\n\\n# Max bytes to feed to chardet for encoding detection.\\n# Scanning the first 100 KB is sufficient for reliable detection\\n# and avoids O(n) overhead on large files (e.g. 800s for 1.5 GB).\\n_CHARDET_SAMPLE_BYTES = 102400\\n\\n# Types of files that can be read simply by file.read()\\n# and have 100% to be completely readable\\nTEXT_FILE_TYPES = [\\n    \\\"csv\\\",\\n    \\\"json\\\",\\n    \\\"pdf\\\",\\n    \\\"txt\\\",\\n    \\\"md\\\",\\n    \\\"mdx\\\",\\n    \\\"yaml\\\",\\n    \\\"yml\\\",\\n    \\\"xml\\\",\\n    \\\"html\\\",\\n    \\\"htm\\\",\\n    \\\"docx\\\",\\n    \\\"py\\\",\\n    \\\"sh\\\",\\n    \\\"sql\\\",\\n    \\\"js\\\",\\n    \\\"ts\\\",\\n    \\\"tsx\\\",\\n]\\n\\nIMG_FILE_TYPES = [\\\"jpg\\\", \\\"jpeg\\\", \\\"png\\\", \\\"bmp\\\", \\\"image\\\"]\\n\\n\\ndef parse_structured_text(text: str, file_path: str) -> str | dict | list:\\n    \\\"\\\"\\\"Parse structured text formats (JSON, YAML, XML) and normalize text.\\n\\n    Args:\\n        text: The text content to parse\\n        file_path: The file path (used to determine format)\\n\\n    Returns:\\n        Parsed content (dict/list for JSON, dict for YAML, str for XML)\\n    \\\"\\\"\\\"\\n    if file_path.endswith(\\\".json\\\"):\\n        loaded_json = orjson.loads(text)\\n        if isinstance(loaded_json, dict):\\n            loaded_json = {k: normalize_text(v) if isinstance(v, str) else v for k, v in loaded_json.items()}\\n        elif isinstance(loaded_json, list):\\n            loaded_json = [normalize_text(item) if isinstance(item, str) else item for item in loaded_json]\\n        return orjson.dumps(loaded_json).decode(\\\"utf-8\\\")\\n\\n    if file_path.endswith((\\\".yaml\\\", \\\".yml\\\")):\\n        return yaml.safe_load(text)\\n\\n    if file_path.endswith(\\\".xml\\\"):\\n        xml_element = ElementTree.fromstring(text)\\n        return ElementTree.tostring(xml_element, encoding=\\\"unicode\\\")\\n\\n    return text\\n\\n\\ndef normalize_text(text):\\n    return unicodedata.normalize(\\\"NFKD\\\", text)\\n\\n\\ndef is_hidden(path: Path) -> bool:\\n    return path.name.startswith(\\\".\\\")\\n\\n\\ndef format_directory_path(path: str) -> str:\\n    \\\"\\\"\\\"Format a directory path to ensure it's properly escaped and valid.\\n\\n    Args:\\n    path (str): The input path string.\\n\\n    Returns:\\n    str: A properly formatted path string.\\n    \\\"\\\"\\\"\\n    return path.replace(\\\"\\\\n\\\", \\\"\\\\\\\\n\\\")\\n\\n\\n# Ignoring FBT001 because the DirectoryComponent in 1.0.19\\n# calls this function without keyword arguments\\ndef retrieve_file_paths(\\n    path: str,\\n    load_hidden: bool,  # noqa: FBT001\\n    recursive: bool,  # noqa: FBT001\\n    depth: int,\\n    types: list[str] = TEXT_FILE_TYPES,\\n) -> list[str]:\\n    path = format_directory_path(path)\\n    path_obj = Path(path).resolve()\\n    if not path_obj.exists() or not path_obj.is_dir():\\n        msg = f\\\"Path {path} must exist and be a directory.\\\"\\n        raise ValueError(msg)\\n\\n    def match_types(p: Path) -> bool:\\n        return any(p.suffix == f\\\".{t}\\\" for t in types) if types else True\\n\\n    def is_not_hidden(p: Path) -> bool:\\n        return not is_hidden(p) or load_hidden\\n\\n    def is_within_directory(p: Path) -> bool:\\n        return p.resolve().is_relative_to(path_obj)\\n\\n    def walk_level(directory: Path, max_depth: int):\\n        prefix_length = len(directory.parts)\\n        for p in directory.rglob(\\\"*\\\" if recursive else \\\"[!.]*\\\"):\\n            if len(p.parts) - prefix_length <= max_depth:\\n                yield p\\n\\n    glob = \\\"**/*\\\" if recursive else \\\"*\\\"\\n    paths = walk_level(path_obj, depth) if depth else path_obj.glob(glob)\\n    return [str(p) for p in paths if p.is_file() and match_types(p) and is_not_hidden(p) and is_within_directory(p)]\\n\\n\\ndef partition_file_to_data(file_path: str, *, silent_errors: bool) -> Data | None:\\n    # Use the partition function to load the file\\n    from unstructured.partition.auto import partition\\n\\n    try:\\n        elements = partition(file_path)\\n    except Exception as e:\\n        if not silent_errors:\\n            msg = f\\\"Error loading file {file_path}: {e}\\\"\\n            raise ValueError(msg) from e\\n        return None\\n\\n    # Create a Data\\n    text = \\\"\\\\n\\\\n\\\".join([str(el) for el in elements])\\n    metadata = elements.metadata if hasattr(elements, \\\"metadata\\\") else {}\\n    metadata[\\\"file_path\\\"] = file_path\\n    return Data(text=text, data=metadata)\\n\\n\\ndef _detect_encoding_with_fallbacks(raw_data: bytes) -> list[str]:\\n    \\\"\\\"\\\"Detect encoding and build a fallback chain for decoding.\\n\\n    Returns a list of encodings to try in order, ending with latin-1\\n    which always succeeds as it maps all 256 byte values.\\n    \\\"\\\"\\\"\\n    result = chardet.detect(raw_data[:_CHARDET_SAMPLE_BYTES])\\n    detected_encoding = result.get(\\\"encoding\\\") if result else None\\n\\n    if detected_encoding in {\\\"Windows-1252\\\", \\\"Windows-1254\\\", \\\"MacRoman\\\"}:\\n        detected_encoding = \\\"utf-8\\\"\\n\\n    encodings: list[str] = []\\n    if detected_encoding:\\n        encodings.append(detected_encoding)\\n    for fallback in (\\\"utf-8\\\", \\\"gb18030\\\"):\\n        if fallback not in encodings:\\n            encodings.append(fallback)\\n    encodings.append(\\\"latin-1\\\")\\n    return encodings\\n\\n\\ndef read_text_file(file_path: str) -> str:\\n    \\\"\\\"\\\"Read a text file with automatic encoding detection.\\n\\n    Args:\\n        file_path: Path to the file (local path only, not storage service path)\\n\\n    Returns:\\n        str: The file content as text\\n    \\\"\\\"\\\"\\n    file_path_ = Path(file_path)\\n    raw_data = file_path_.read_bytes()\\n\\n    for enc in _detect_encoding_with_fallbacks(raw_data):\\n        try:\\n            return file_path_.read_text(encoding=enc)\\n        except (UnicodeDecodeError, LookupError):\\n            logger.debug(\\\"Encoding '%s' failed for %s, trying next fallback\\\", enc, file_path)\\n\\n    # Unreachable: latin-1 in the fallback chain always succeeds\\n    return raw_data.decode(\\\"latin-1\\\")\\n\\n\\nasync def read_text_file_async(file_path: str) -> str:\\n    \\\"\\\"\\\"Read a text file with automatic encoding detection (async, storage-aware).\\n\\n    Args:\\n        file_path: Path to the file (S3 key format \\\"flow_id/filename\\\" or local path)\\n\\n    Returns:\\n        str: The file content as text\\n    \\\"\\\"\\\"\\n    from .storage_utils import read_file_bytes\\n\\n    # Use storage-aware read to get bytes\\n    raw_data = await read_file_bytes(file_path)\\n\\n    for enc in _detect_encoding_with_fallbacks(raw_data):\\n        try:\\n            return raw_data.decode(enc)\\n        except (UnicodeDecodeError, LookupError):\\n            logger.debug(\\\"Encoding '%s' failed for %s, trying next fallback\\\", enc, file_path)\\n\\n    # Unreachable: latin-1 in the fallback chain always succeeds\\n    return raw_data.decode(\\\"latin-1\\\")\\n\\n\\ndef read_docx_file(file_path: str) -> str:\\n    \\\"\\\"\\\"Read a DOCX file and extract text.\\n\\n    ote: python-docx requires a file path, so this only works with local files.\\n    For storage service files, use read_docx_file_async which downloads to temp.\\n\\n    Args:\\n        file_path: Path to the DOCX file (local path only)\\n\\n    Returns:\\n        str: Extracted text from the document\\n    \\\"\\\"\\\"\\n    from docx import Document\\n\\n    doc = Document(file_path)\\n    return \\\"\\\\n\\\\n\\\".join([p.text for p in doc.paragraphs])\\n\\n\\nasync def read_docx_file_async(file_path: str) -> str:\\n    \\\"\\\"\\\"Read a DOCX file and extract text (async, storage-aware).\\n\\n    For S3 storage, downloads to temp file (python-docx requires file path).\\n    For local storage, reads directly.\\n\\n    Args:\\n        file_path: Path to the DOCX file (S3 key format \\\"flow_id/filename\\\" or local path)\\n\\n    Returns:\\n        str: Extracted text from the document\\n    \\\"\\\"\\\"\\n    from docx import Document\\n\\n    from .storage_utils import read_file_bytes\\n\\n    settings = get_settings_service().settings\\n\\n    if settings.storage_type == \\\"local\\\":\\n        # Local storage - read directly\\n        doc = Document(file_path)\\n        return \\\"\\\\n\\\\n\\\".join([p.text for p in doc.paragraphs])\\n\\n    # S3 storage - need temp file for python-docx (doesn't support BytesIO)\\n    content = await read_file_bytes(file_path)\\n\\n    # Create temp file with .docx extension\\n    # Extract filename from path for suffix\\n    suffix = Path(file_path.split(\\\"/\\\")[-1]).suffix\\n    with tempfile.NamedTemporaryFile(mode=\\\"wb\\\", suffix=suffix, delete=False) as tmp_file:\\n        tmp_file.write(content)\\n        temp_path = tmp_file.name\\n\\n    try:\\n        doc = Document(temp_path)\\n        return \\\"\\\\n\\\\n\\\".join([p.text for p in doc.paragraphs])\\n    finally:\\n        with contextlib.suppress(Exception):\\n            Path(temp_path).unlink()\\n\\n\\ndef extract_text_from_bytes(file_name: str, file_content: bytes) -> str:\\n    \\\"\\\"\\\"Extract text from binary file content based on file extension.\\n\\n    Supports PDF (via pypdf), DOCX (via python-docx), and plain text files.\\n\\n    Raises:\\n        ValueError: If the file content is corrupted or cannot be parsed.\\n    \\\"\\\"\\\"\\n    lower_name = file_name.lower()\\n    if lower_name.endswith(\\\".pdf\\\"):\\n        try:\\n            with BytesIO(file_content) as f, PdfReader(f) as reader:\\n                return \\\"\\\\n\\\\n\\\".join(page.extract_text() or \\\"\\\" for page in reader.pages)\\n        except Exception as e:\\n            msg = f\\\"Failed to parse PDF file '{file_name}': {e}\\\"\\n            raise ValueError(msg) from e\\n    if lower_name.endswith(\\\".docx\\\"):\\n        try:\\n            from docx import Document\\n\\n            doc = Document(BytesIO(file_content))\\n            return \\\"\\\\n\\\\n\\\".join(p.text for p in doc.paragraphs)\\n        except Exception as e:\\n            msg = f\\\"Failed to parse DOCX file '{file_name}': {e}\\\"\\n            raise ValueError(msg) from e\\n    return file_content.decode(\\\"utf-8\\\", errors=\\\"ignore\\\")\\n\\n\\ndef parse_pdf_to_text(file_path: str) -> str:\\n    with Path(file_path).open(\\\"rb\\\") as f, PdfReader(f) as reader:\\n        return \\\"\\\\n\\\\n\\\".join([page.extract_text() for page in reader.pages])\\n\\n\\nasync def parse_pdf_to_text_async(file_path: str) -> str:\\n    \\\"\\\"\\\"Parse a PDF file to extract text (async, storage-aware).\\n\\n    Uses storage-aware file reading to support both local and S3 storage.\\n\\n    Args:\\n        file_path: Path to the PDF file (S3 key format \\\"flow_id/filename\\\" or local path)\\n\\n    Returns:\\n        str: Extracted text from all pages\\n    \\\"\\\"\\\"\\n    content = await read_file_bytes(file_path)\\n    with BytesIO(content) as f, PdfReader(f) as reader:\\n        return \\\"\\\\n\\\\n\\\".join([page.extract_text() for page in reader.pages])\\n\\n\\ndef parse_text_file_to_data(file_path: str, *, silent_errors: bool) -> Data | None:\\n    \\\"\\\"\\\"Parse a text file to Data (sync version).\\n\\n    For S3 storage, this will use async operations to fetch the file.\\n    For local storage, reads directly from filesystem.\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n\\n    # If using S3 storage, we need to use async operations\\n    if settings.storage_type == \\\"s3\\\":\\n        # Run the async version safely (handles existing event loops)\\n        return run_until_complete(parse_text_file_to_data_async(file_path, silent_errors=silent_errors))\\n\\n    try:\\n        if file_path.endswith(\\\".pdf\\\"):\\n            text = parse_pdf_to_text(file_path)\\n        elif file_path.endswith(\\\".docx\\\"):\\n            text = read_docx_file(file_path)\\n        else:\\n            text = read_text_file(file_path)\\n\\n        text = parse_structured_text(text, file_path)\\n    except Exception as e:\\n        if not silent_errors:\\n            msg = f\\\"Error loading file {file_path}: {e}\\\"\\n            raise ValueError(msg) from e\\n        return None\\n\\n    return Data(data={\\\"file_path\\\": file_path, \\\"text\\\": text})\\n\\n\\nasync def parse_text_file_to_data_async(file_path: str, *, silent_errors: bool) -> Data | None:\\n    \\\"\\\"\\\"Parse a text file to Data (async version, supports storage service).\\n\\n    This version properly handles storage service files:\\n    - For text/JSON/YAML/XML: reads bytes directly (no temp file)\\n    - For PDF: reads bytes directly via BytesIO (no temp file)\\n    - For DOCX: downloads to temp file (python-docx requires file path)\\n    \\\"\\\"\\\"\\n    try:\\n        if file_path.endswith(\\\".pdf\\\"):\\n            text = await parse_pdf_to_text_async(file_path)\\n        elif file_path.endswith(\\\".docx\\\"):\\n            text = await read_docx_file_async(file_path)\\n        else:\\n            # Text files - read directly, no temp file needed\\n            text = await read_text_file_async(file_path)\\n\\n        # Parse structured formats (JSON, YAML, XML)\\n        text = parse_structured_text(text, file_path)\\n\\n        return Data(data={\\\"file_path\\\": file_path, \\\"text\\\": text})\\n\\n    except Exception as e:\\n        if not silent_errors:\\n            msg = f\\\"Error loading file {file_path}: {e}\\\"\\n            raise ValueError(msg) from e\\n        return None\\n\\n\\n# ! Removing unstructured dependency until\\n# ! 3.12 is supported\\n# def get_elements(\\n#     file_paths: List[str],\\n#     silent_errors: bool,\\n#     max_concurrency: int,\\n#     use_multithreading: bool,\\n# ) -> List[Optional[Data]]:\\n#     if use_multithreading:\\n#         data = parallel_load_data(file_paths, silent_errors, max_concurrency)\\n#     else:\\n#         data = [partition_file_to_data(file_path, silent_errors) for file_path in file_paths]\\n#     data = list(filter(None, data))\\n#     return data\\n\\n\\ndef parallel_load_data(\\n    file_paths: list[str],\\n    *,\\n    silent_errors: bool,\\n    max_concurrency: int,\\n    load_function: Callable = parse_text_file_to_data,\\n) -> list[Data | None]:\\n    # Each thread gets its own context copy so ContextVars (e.g. component_context_var)\\n    # are available in thread pool workers across all Python versions.\\n    def _run_in_context(file_path: str) -> Data | None:\\n        ctx = copy_context()\\n        return ctx.run(load_function, file_path, silent_errors=silent_errors)\\n\\n    with futures.ThreadPoolExecutor(max_workers=max_concurrency) as executor:\\n        loaded_files = executor.map(_run_in_context, file_paths)\\n    # loaded_files is an iterator, so we need to convert it to a list\\n    return list(loaded_files)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/datastax/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f6dd33384a348ff5d8c4daf76b9a62fd4851a3f418a823d0a919aae2f692b870\",\"content\":\"# lfx-bundles-shim\\n\\\"\\\"\\\"Compatibility shim: lfx.base.datastax moved to the lfx-datastax bundle.\\n\\nThis module re-points to ``lfx_datastax.base`` in the installed bundle\\ndistribution. It exists because component code stored inside saved flows\\n(and the starter-project templates) imports\\n``lfx.base.datastax.astradb_base`` directly, and that stored source is\\nre-executed verbatim at flow build time -- so the legacy path must keep\\nresolving. It contains no implementations and no third-party\\ndependencies, and is removed once the deprecation window closes (M4).\\n\\\"\\\"\\\"\\n\\nimport importlib\\nimport sys\\n\\ntry:\\n    sys.modules[__name__] = importlib.import_module(\\\"lfx_datastax.base\\\")\\nexcept ModuleNotFoundError as exc:\\n    if exc.name is not None and (exc.name == \\\"lfx_datastax\\\" or exc.name.startswith(\\\"lfx_datastax.\\\")):\\n        msg = (\\n            \\\"The 'datastax' base utilities moved to the 'lfx-datastax' distribution. \\\"\\n            \\\"Install it with:  pip install lfx-datastax   \\\"\\n            \\\"(or 'pip install langflow', which bundles it).\\\"\\n        )\\n        raise ModuleNotFoundError(msg, name=\\\"lfx_datastax\\\") from exc\\n    raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/document_transformers/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/document_transformers/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bfd7918dc16becb968b71adcc56d9f49958a72398cf57e853969b71dc21f820e\",\"content\":\"from abc import abstractmethod\\nfrom typing import Any\\n\\nfrom langchain_core.documents import BaseDocumentTransformer\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import Output\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.util import build_loader_repr_from_data\\n\\n\\nclass LCDocumentTransformerComponent(Component):\\n    trace_type = \\\"document_transformer\\\"\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"transform_data\\\"),\\n    ]\\n\\n    def transform_data(self) -> list[Data]:\\n        data_input = self.get_data_input()\\n        documents = []\\n\\n        if not isinstance(data_input, list):\\n            data_input = [data_input]\\n\\n        for _input in data_input:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        transformer = self.build_document_transformer()\\n        docs = transformer.transform_documents(documents)\\n        data = self.to_data(docs)\\n        self.repr_value = build_loader_repr_from_data(data)\\n        return data\\n\\n    @abstractmethod\\n    def get_data_input(self) -> Any:\\n        \\\"\\\"\\\"Get the data input.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def build_document_transformer(self) -> BaseDocumentTransformer:\\n        \\\"\\\"\\\"Build the text splitter.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/embeddings/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/embeddings/aiml_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"083e39005db35fd9c959af67d4b4e15282a1fa82bbe4ba33c1f3c7daee0912f1\",\"content\":\"import concurrent.futures\\nimport json\\n\\nimport httpx\\nfrom pydantic import BaseModel, SecretStr\\n\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.log.logger import logger\\n\\n\\nclass AIMLEmbeddingsImpl(BaseModel, Embeddings):\\n    embeddings_completion_url: str = \\\"https://api.aimlapi.com/v1/embeddings\\\"\\n\\n    api_key: SecretStr\\n    model: str\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        embeddings = [None] * len(texts)\\n        headers = {\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n            \\\"Authorization\\\": f\\\"Bearer {self.api_key.get_secret_value()}\\\",\\n        }\\n\\n        with httpx.Client() as client, concurrent.futures.ThreadPoolExecutor() as executor:\\n            futures = []\\n            for i, text in enumerate(texts):\\n                futures.append((i, executor.submit(self._embed_text, client, headers, text)))\\n\\n            for index, future in futures:\\n                try:\\n                    result_data = future.result()\\n                    if len(result_data[\\\"data\\\"]) != 1:\\n                        msg = f\\\"Expected one embedding, got {len(result_data['data'])}\\\"\\n                        raise ValueError(msg)\\n                    embeddings[index] = result_data[\\\"data\\\"][0][\\\"embedding\\\"]\\n                except (\\n                    httpx.HTTPStatusError,\\n                    httpx.RequestError,\\n                    json.JSONDecodeError,\\n                    KeyError,\\n                    ValueError,\\n                ):\\n                    logger.exception(\\\"Error occurred\\\")\\n                    raise\\n\\n        return embeddings  # type: ignore[return-value]\\n\\n    def _embed_text(self, client: httpx.Client, headers: dict, text: str) -> dict:\\n        payload = {\\n            \\\"model\\\": self.model,\\n            \\\"input\\\": text,\\n        }\\n        response = client.post(\\n            self.embeddings_completion_url,\\n            headers=headers,\\n            json=payload,\\n        )\\n        response.raise_for_status()\\n        return response.json()\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        return self.embed_documents([text])[0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/embeddings/embeddings_class.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"04c22c0a6b5776c3bb51545a9eeb54b1a0cbf4062d991a2c2c9137f69dae1e66\",\"content\":\"\\\"\\\"\\\"Extended embeddings class with available models metadata.\\\"\\\"\\\"\\n\\nfrom langchain_core.embeddings import Embeddings\\n\\n\\nclass EmbeddingsWithModels(Embeddings):\\n    \\\"\\\"\\\"Extended Embeddings class that includes available models with dedicated instances.\\n\\n    This class inherits from LangChain Embeddings and provides a mapping of model names\\n    to their dedicated embedding instances, enabling multi-model support without the need\\n    for dynamic model switching.\\n\\n    Attributes:\\n        embeddings: The primary LangChain Embeddings instance (used as fallback).\\n        available_models: Dict mapping embedding model names to dedicated Embeddings instances\\n                         across every configured provider in Model Providers settings.\\n                         Each model has its own pre-configured instance with specific parameters.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        embeddings: Embeddings,\\n        available_models: dict[str, Embeddings] | None = None,\\n    ):\\n        \\\"\\\"\\\"Initialize the EmbeddingsWithModels wrapper.\\n\\n        Args:\\n            embeddings: The primary LangChain Embeddings instance (used as default/fallback).\\n            available_models: Dict mapping embedding model names to dedicated Embeddings instances\\n                            from all configured providers. Each value should be a fully configured\\n                            Embeddings object ready to use. Defaults to empty dict if not provided.\\n        \\\"\\\"\\\"\\n        super().__init__()\\n        self.embeddings = embeddings\\n        self.available_models = available_models if available_models is not None else {}\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        \\\"\\\"\\\"Embed search docs by delegating to the underlying embeddings instance.\\n\\n        Args:\\n            texts: List of text to embed.\\n\\n        Returns:\\n            List of embeddings.\\n        \\\"\\\"\\\"\\n        return self.embeddings.embed_documents(texts)\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        \\\"\\\"\\\"Embed query text by delegating to the underlying embeddings instance.\\n\\n        Args:\\n            text: Text to embed.\\n\\n        Returns:\\n            Embedding.\\n        \\\"\\\"\\\"\\n        return self.embeddings.embed_query(text)\\n\\n    async def aembed_documents(self, texts: list[str]) -> list[list[float]]:\\n        \\\"\\\"\\\"Asynchronously embed search docs.\\n\\n        Args:\\n            texts: List of text to embed.\\n\\n        Returns:\\n            List of embeddings.\\n        \\\"\\\"\\\"\\n        return await self.embeddings.aembed_documents(texts)\\n\\n    async def aembed_query(self, text: str) -> list[float]:\\n        \\\"\\\"\\\"Asynchronously embed query text.\\n\\n        Args:\\n            text: Text to embed.\\n\\n        Returns:\\n            Embedding.\\n        \\\"\\\"\\\"\\n        return await self.embeddings.aembed_query(text)\\n\\n    def __call__(self, *args, **kwargs):\\n        \\\"\\\"\\\"Make the class callable by delegating to the underlying embeddings instance.\\n\\n        This handles cases where the embeddings object is used as a callable.\\n\\n        Args:\\n            *args: Positional arguments to pass to the underlying embeddings instance.\\n            **kwargs: Keyword arguments to pass to the underlying embeddings instance.\\n\\n        Returns:\\n            The result of calling the underlying embeddings instance.\\n        \\\"\\\"\\\"\\n        if callable(self.embeddings):\\n            return self.embeddings(*args, **kwargs)\\n        msg = f\\\"'{type(self.embeddings).__name__}' object is not callable\\\"\\n        raise TypeError(msg)\\n\\n    def __getattr__(self, name: str):\\n        \\\"\\\"\\\"Delegate attribute access to the underlying embeddings instance.\\n\\n        This ensures full compatibility with any additional methods or attributes\\n        that the underlying embeddings instance might have.\\n\\n        Args:\\n            name: The attribute name to access.\\n\\n        Returns:\\n            The attribute from the underlying embeddings instance.\\n        \\\"\\\"\\\"\\n        return getattr(self.embeddings, name)\\n\\n    def __repr__(self) -> str:\\n        \\\"\\\"\\\"Return string representation of the wrapper.\\\"\\\"\\\"\\n        return f\\\"EmbeddingsWithModels(embeddings={self.embeddings!r}, available_models={self.available_models!r})\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/embeddings/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"41f59452793229c5852a00d06fdb5781767c519bfd0dba5cd217473e2bc65673\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import Output\\n\\n\\nclass LCEmbeddingsModel(Component):\\n    model_provider_policy_mode: str = \\\"standalone\\\"\\n    # Optional explicit override for policy identity. Most subclasses are\\n    # classified systemically from their provider package/module.\\n    model_provider_id: str | None = None\\n    trace_type = \\\"embedding\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Embedding Model\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def _validate_outputs(self) -> None:\\n        required_output_methods = [\\\"build_embeddings\\\"]\\n        output_names = [output.name for output in self.outputs]\\n        for method_name in required_output_methods:\\n            if method_name not in output_names:\\n                msg = f\\\"Output with name '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n            if not hasattr(self, method_name):\\n                msg = f\\\"Method '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n\\n    def build_embeddings(self) -> Embeddings:\\n        msg = \\\"You must implement the build_embeddings method in your class.\\\"\\n        raise NotImplementedError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/huggingface/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/huggingface/model_bridge.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a4e6c472eef4cd1752648b65f4fe527f1769c53409784f52a7bf4849b19ca32d\",\"content\":\"# Import LangChain base\\nfrom langchain_core.language_models.chat_models import BaseChatModel\\nfrom langchain_core.messages import AIMessage, HumanMessage, SystemMessage, ToolCall\\nfrom langchain_core.tools import BaseTool\\n\\n# Import Hugging Face Model base\\nfrom smolagents import Model, Tool\\nfrom smolagents.models import ChatMessage, ChatMessageToolCall, ChatMessageToolCallDefinition\\n\\n\\ndef _lc_tool_call_to_hf_tool_call(tool_call: ToolCall) -> ChatMessageToolCall:\\n    \\\"\\\"\\\"Convert a LangChain ToolCall to a Hugging Face ChatMessageToolCall.\\n\\n    Args:\\n        tool_call (ToolCall): LangChain tool call to convert\\n\\n    Returns:\\n        ChatMessageToolCall: Equivalent Hugging Face tool call\\n    \\\"\\\"\\\"\\n    return ChatMessageToolCall(\\n        function=ChatMessageToolCallDefinition(name=tool_call.name, arguments=tool_call.args),\\n        id=tool_call.id,\\n    )\\n\\n\\ndef _hf_tool_to_lc_tool(tool) -> BaseTool:\\n    \\\"\\\"\\\"Convert a Hugging Face Tool to a LangChain BaseTool.\\n\\n    Args:\\n        tool (Tool): Hugging Face tool to convert\\n\\n    Returns:\\n        BaseTool: Equivalent LangChain tool\\n    \\\"\\\"\\\"\\n    if not hasattr(tool, \\\"langchain_tool\\\"):\\n        msg = \\\"Hugging Face Tool does not have a langchain_tool attribute\\\"\\n        raise ValueError(msg)\\n    return tool.langchain_tool\\n\\n\\nclass LangChainHFModel(Model):\\n    \\\"\\\"\\\"A class bridging Hugging Face's `Model` interface with a LangChain `BaseChatModel`.\\n\\n    This adapter allows using any LangChain chat model with the Hugging Face interface.\\n    It handles conversion of message formats and tool calls between the two frameworks.\\n\\n    Usage:\\n       >>> lc_model = LangChainChatModel(...)  # any BaseChatModel\\n       >>> hf_model = LangChainHFModel(lc_model)\\n       >>> hf_model(messages=[{\\\"role\\\": \\\"user\\\", \\\"content\\\": \\\"Hello!\\\"}])\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, chat_model: BaseChatModel, **kwargs):\\n        \\\"\\\"\\\"Initialize the bridge model.\\n\\n        Args:\\n            chat_model (BaseChatModel): LangChain chat model to wrap\\n            **kwargs: Additional arguments passed to Model.__init__\\n        \\\"\\\"\\\"\\n        super().__init__(**kwargs)\\n        self.chat_model = chat_model\\n\\n    def __call__(\\n        self,\\n        messages: list[dict[str, str]],\\n        stop_sequences: list[str] | None = None,\\n        grammar: str | None = None,\\n        tools_to_call_from: list[Tool] | None = None,\\n        **kwargs,\\n    ) -> ChatMessage:\\n        \\\"\\\"\\\"Process messages through the LangChain model and return Hugging Face format.\\n\\n        Args:\\n            messages: List of message dictionaries with 'role' and 'content' keys\\n            stop_sequences: Optional list of strings to stop generation\\n            grammar: Optional grammar specification (not used)\\n            tools_to_call_from: Optional list of available tools (not used)\\n            **kwargs: Additional arguments passed to the LangChain model\\n\\n        Returns:\\n            ChatMessage: Response in Hugging Face format\\n        \\\"\\\"\\\"\\n        if grammar:\\n            msg = \\\"Grammar is not yet supported.\\\"\\n            raise ValueError(msg)\\n\\n        # Convert HF messages to LangChain messages\\n        lc_messages = []\\n        for m in messages:\\n            role = m[\\\"role\\\"]\\n            content = m[\\\"content\\\"]\\n            if role == \\\"system\\\":\\n                lc_messages.append(SystemMessage(content=content))\\n            elif role == \\\"assistant\\\":\\n                lc_messages.append(AIMessage(content=content))\\n            else:\\n                # Default any unknown role to \\\"user\\\"\\n                lc_messages.append(HumanMessage(content=content))\\n\\n        # Convert tools to LangChain tools\\n        if tools_to_call_from:\\n            tools_to_call_from = [_hf_tool_to_lc_tool(tool) for tool in tools_to_call_from]\\n\\n        model = self.chat_model.bind_tools(tools_to_call_from) if tools_to_call_from else self.chat_model\\n\\n        # Call the LangChain model\\n        result_msg: AIMessage = model.invoke(lc_messages, stop=stop_sequences, **kwargs)\\n\\n        # Convert the AIMessage into an HF ChatMessage\\n        return ChatMessage(\\n            role=\\\"assistant\\\",\\n            content=result_msg.content or \\\"\\\",\\n            tool_calls=[_lc_tool_call_to_hf_tool_call(tool_call) for tool_call in result_msg.tool_calls],\\n        )\\n\\n\\n# How to use\\n# if __name__ == \\\"__main__\\\":\\n#     from langchain_community.tools import DuckDuckGoSearchRun\\n#     from langchain_openai import ChatOpenAI\\n#     from rich import rprint\\n#     from smolagents import CodeAgent\\n\\n#     # Example usage\\n#     model = LangChainHFModel(chat_model=ChatOpenAI(model=\\\"gpt-4o-mini\\\"))\\n#     search_tool = DuckDuckGoSearchRun()\\n#     hf_tool = Tool.from_langchain(search_tool)\\n\\n#     code_agent = CodeAgent(\\n#         model=model,\\n#         tools=[hf_tool],\\n#     )\\n#     rprint(code_agent.run(\\\"Search for Langflow on DuckDuckGo and return the first result\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/io/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/io/chat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"48492a2df797a42413862dedde0a3e157362fdaed1846b70ff9a2833be4609e7\",\"content\":\"from lfx.custom.custom_component.component import Component\\n\\n\\ndef _extract_model_name(value):\\n    \\\"\\\"\\\"Extract model name from ModelInput format (list of dicts with 'name' key).\\\"\\\"\\\"\\n    if isinstance(value, str):\\n        return value\\n    if isinstance(value, list) and value and isinstance(value[0], dict):\\n        return value[0].get(\\\"name\\\")\\n    if isinstance(value, dict):\\n        return value.get(\\\"name\\\")\\n    return None\\n\\n\\nclass ChatComponent(Component):\\n    display_name = \\\"Chat Component\\\"\\n    description = \\\"Use as base for chat components.\\\"\\n\\n    def get_properties_from_source_component(self):\\n        vertex = self.get_vertex()\\n        if vertex and hasattr(vertex, \\\"incoming_edges\\\") and vertex.incoming_edges:\\n            source_id = vertex.incoming_edges[0].source_id\\n            source_vertex = self.graph.get_vertex(source_id)\\n            component = source_vertex.custom_component\\n            source = component.display_name\\n            icon = component.icon\\n            possible_attributes = [\\\"model_name\\\", \\\"model_id\\\", \\\"model\\\"]\\n            for attribute in possible_attributes:\\n                if hasattr(component, attribute):\\n                    attr_value = getattr(component, attribute)\\n                    if attr_value:\\n                        model_name = _extract_model_name(attr_value)\\n                        if model_name:\\n                            return model_name, icon, source, component.get_id()\\n            return source, icon, component.display_name, component.get_id()\\n        return None, None, None, None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/io/text.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b96daf74d21c719533bf415455a7e8e16fa53a19bc60524e315daacad1981cf9\",\"content\":\"from lfx.custom.custom_component.component import Component\\n\\n\\nclass TextComponent(Component):\\n    display_name = \\\"Text Component\\\"\\n    description = \\\"Used to pass text to the next component.\\\"\\n\\n    def build_config(self):\\n        return {\\n            \\\"input_value\\\": {\\n                \\\"display_name\\\": \\\"Value\\\",\\n                \\\"input_types\\\": [\\\"Message\\\", \\\"Data\\\"],\\n                \\\"info\\\": \\\"Text or Data to be passed.\\\",\\n            },\\n            \\\"data_template\\\": {\\n                \\\"display_name\\\": \\\"Data Template\\\",\\n                \\\"multiline\\\": True,\\n                \\\"info\\\": \\\"Template to convert Data to Text. \\\"\\n                \\\"If left empty, it will be dynamically set to the Data's text key.\\\",\\n                \\\"advanced\\\": True,\\n            },\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/langchain_utilities/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/langchain_utilities/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b5c138888e92d227eb38ff3519d48721aef9802785f91f9db23dba8614f6681\",\"content\":\"from abc import abstractmethod\\nfrom collections.abc import Sequence\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.field_typing import Tool\\nfrom lfx.io import Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\nclass LCToolComponent(Component):\\n    trace_type = \\\"tool\\\"\\n    outputs = [\\n        Output(name=\\\"api_run_model\\\", display_name=\\\"JSON\\\", method=\\\"run_model\\\"),\\n        Output(name=\\\"api_build_tool\\\", display_name=\\\"Tool\\\", method=\\\"build_tool\\\"),\\n    ]\\n\\n    def _validate_outputs(self) -> None:\\n        required_output_methods = [\\\"run_model\\\", \\\"build_tool\\\"]\\n        output_names = [output.name for output in self.outputs]\\n        for method_name in required_output_methods:\\n            if method_name not in output_names:\\n                msg = f\\\"Output with name '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n            if not hasattr(self, method_name):\\n                msg = f\\\"Method '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n\\n    @abstractmethod\\n    def run_model(self) -> Data | list[Data] | DataFrame:\\n        \\\"\\\"\\\"Run model and return the output.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def build_tool(self) -> Tool | Sequence[Tool]:\\n        \\\"\\\"\\\"Build the tool.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/langchain_utilities/spider_constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8d937552bc06040dbbe0ea8c3d956fdb702b61c3555856936bdb908a369bf08c\",\"content\":\"MODES = [\\\"scrape\\\", \\\"crawl\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/langwatch/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/langwatch/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37bac7dec470826350cc6d292a38f8c2bfda9ecfddaf0b6f931e0142df81d160\",\"content\":\"from functools import lru_cache\\nfrom typing import Any\\n\\nimport httpx\\n\\nfrom lfx.log.logger import logger\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_cached_evaluators(url: str) -> dict[str, Any]:\\n    try:\\n        response = httpx.get(url, timeout=10)\\n        response.raise_for_status()\\n        data = response.json()\\n        return data.get(\\\"evaluators\\\", {})\\n    except httpx.RequestError as e:\\n        logger.error(f\\\"Error fetching evaluators: {e}\\\")\\n        return {}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb55e72717a396a9bdcecd51f75a86b4e797fbf175669747573088a940af8601\",\"content\":\"MAX_MCP_SERVER_NAME_LENGTH = 30\\nMAX_MCP_TOOL_NAME_LENGTH = 30\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/preset.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1c4661d6e6b184e0d669c6dc6203fe75cd6d2a0cc9c9e1a85f7f66cf1bb928ee\",\"content\":\"\\\"\\\"\\\"Base class for \\\"preset\\\" MCP tool components.\\n\\nA preset component wraps a *known* remote MCP server -- one whose endpoint\\nshape and auth scheme are fixed by the vendor -- so the flow author fills in\\na handful of IDs and a credential instead of hand-assembling an MCP server\\nentry.  It reuses Langflow's MCP client engine (``lfx.base.mcp.util``) rather\\nthan the ``MCP Tools`` picker UI:\\n\\n* ``update_tools`` connects over Streamable HTTP (with the engine's SSE\\n  fallback), SSRF-validates the endpoint, and returns ready ``StructuredTool``\\n  objects that carry the correct argument schema.\\n* ``add_tool_output = True`` + ``_get_tools()`` gives the component a\\n  ``Toolset`` output that plugs straight into an Agent's *Tools* handle\\n  (the same pattern as the in-tree File System tool).\\n* A direct ``Response`` output runs one selected tool for non-agent flows.\\n\\nSubclasses declare their own inputs and implement\\n:meth:`_mcp_server_config`.  They must include the shared inputs returned by\\n:func:`preset_control_inputs` so the base class can find the selected tool,\\nits JSON arguments, the timeout, and the SSL toggle.\\n\\nThe class lives in ``lfx.base`` (like ``LCModelComponent`` /\\n``LCVectorStoreComponent``) rather than inside a bundle because the\\nextension loader registers every ``*Component`` class it finds in a bundle\\nmodule -- a base class shipped inside a bundle would surface in the palette\\nas a broken node.  Consumers: ``lfx-confluent`` (Real-Time Context Engine)\\nand ``lfx-ibm`` (watsonx.data remote MCP server).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport inspect\\nimport json\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.base.mcp.util import MCPStreamableHttpClient, update_tools\\nfrom lfx.custom.custom_component.component_with_cache import ComponentWithCache\\nfrom lfx.io import BoolInput, DropdownInput, FloatInput, MultilineInput, Output, StrInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.dataframe import DataFrame\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Awaitable\\n\\n    from langchain_core.tools import StructuredTool, Tool\\n\\n# Name of the hidden input that makes the \\\"Tool Mode\\\" toggle appear on the\\n# node header without hiding any real, user-editable input in tool mode.\\nTOOL_MODE_TRIGGER = \\\"tool_mode_trigger\\\"\\n\\n\\ndef preset_control_inputs(tool_options: list[str], *, tool_info: str) -> list:\\n    \\\"\\\"\\\"Return the shared control inputs every MCP preset component declares.\\n\\n    ``tool_options`` seeds the *Tool* dropdown with the vendor-documented tool\\n    names so the component is usable before the first live connection; the\\n    dropdown's refresh button re-reads the list from the server.\\n    \\\"\\\"\\\"\\n    return [\\n        DropdownInput(\\n            name=\\\"tool\\\",\\n            display_name=\\\"Tool\\\",\\n            options=list(tool_options),\\n            value=\\\"\\\",\\n            info=tool_info,\\n            real_time_refresh=True,\\n            refresh_button=True,\\n        ),\\n        MultilineInput(\\n            name=\\\"tool_arguments\\\",\\n            display_name=\\\"Tool Arguments (JSON)\\\",\\n            info=(\\n                \\\"JSON object passed as the arguments of the selected tool when the Response \\\"\\n                'output is used directly (for example {\\\"topic\\\": \\\"orders\\\"}). Ignored in Tool '\\n                \\\"Mode, where the Agent supplies the arguments.\\\"\\n            ),\\n            value=\\\"{}\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"tool_execution_timeout\\\",\\n            display_name=\\\"Tool Execution Timeout (seconds)\\\",\\n            info=\\\"Maximum time to wait for a tool call. Set to 0 to use the system-configured MCP timeout.\\\",\\n            value=0.0,\\n            range_spec={\\\"min\\\": 0.0, \\\"max\\\": 3600.0, \\\"step\\\": 0.5},\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"verify_ssl\\\",\\n            display_name=\\\"Verify SSL Certificate\\\",\\n            info=\\\"Disable only for development against a self-signed endpoint.\\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        # Synthetic hidden input: exists ONLY so the \\\"Tool Mode\\\" toggle appears on\\n        # the node header (toggle visibility = any(input.tool_mode)). ``show=False``\\n        # keeps it out of the config UI; putting ``tool_mode=True`` on a real input\\n        # would hide that input in tool mode instead.\\n        StrInput(\\n            name=TOOL_MODE_TRIGGER,\\n            display_name=\\\"\\\",\\n            show=False,\\n            tool_mode=True,\\n            required=False,\\n        ),\\n    ]\\n\\n\\nclass MCPPresetComponent(ComponentWithCache):\\n    \\\"\\\"\\\"Component base wrapping a fixed remote MCP server as an Agent toolset.\\\"\\\"\\\"\\n\\n    # Enables the \\\"Tool Mode\\\" toggle; when ON the framework calls ``_get_tools()``\\n    # and emits a Toolset output that connects to an Agent's \\\"Tools\\\" handle.\\n    add_tool_output = True\\n\\n    outputs = [\\n        Output(display_name=\\\"Response\\\", name=\\\"response\\\", method=\\\"run_tool\\\", types=[\\\"DataFrame\\\"]),\\n    ]\\n\\n    def __init__(self, **data) -> None:\\n        super().__init__(**data)\\n        # One HTTP client per component so concurrent tool loads share a session.\\n        self._streamable_http_client: MCPStreamableHttpClient = MCPStreamableHttpClient(\\n            component_cache=self._shared_component_cache\\n        )\\n\\n    # ------------------------------------------------------------------ hooks\\n    def _mcp_server_config(self) -> tuple[str, dict[str, Any]] | Awaitable[tuple[str, dict[str, Any]]]:\\n        \\\"\\\"\\\"Return ``(server_name, server_config)`` for ``update_tools``.\\n\\n        ``server_config`` must contain ``url`` (already SSRF-validated by the\\n        engine, but subclasses should build it from validated tokens) and may\\n        contain ``headers`` and ``verify_ssl``.  May be declared ``async`` when\\n        building the config needs I/O (for example a token exchange).\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    # --------------------------------------------------------------- helpers\\n    def _resolved_timeout(self) -> float | None:\\n        raw = getattr(self, \\\"tool_execution_timeout\\\", 0) or 0\\n        try:\\n            value = float(raw)\\n        except (TypeError, ValueError):\\n            return None\\n        return value if value > 0 else None\\n\\n    async def _load_tools(self) -> tuple[list[StructuredTool], dict[str, StructuredTool]]:\\n        config = self._mcp_server_config()\\n        if inspect.isawaitable(config):\\n            config = await config\\n        server_name, server_config = config\\n        _, tools, tool_cache = await update_tools(\\n            server_name,\\n            server_config,\\n            mcp_streamable_http_client=self._streamable_http_client,\\n            tool_execution_timeout=self._resolved_timeout(),\\n        )\\n        if not tools:\\n            msg = f\\\"No tools were returned by {server_name}. Check the endpoint, IDs, and credentials.\\\"\\n            raise ValueError(msg)\\n        return tools, tool_cache\\n\\n    def _parse_tool_arguments(self) -> dict[str, Any]:\\n        raw = getattr(self, \\\"tool_arguments\\\", None)\\n        if raw is None or raw == \\\"\\\":\\n            return {}\\n        if isinstance(raw, dict):\\n            return raw\\n        try:\\n            parsed = json.loads(str(raw))\\n        except json.JSONDecodeError as exc:\\n            msg = f\\\"Tool Arguments must be a JSON object: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        if not isinstance(parsed, dict):\\n            msg = 'Tool Arguments must be a JSON object (for example {\\\"topic\\\": \\\"orders\\\"}).'\\n            raise TypeError(msg)\\n        return parsed\\n\\n    @staticmethod\\n    def _result_rows(result: Any) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Flatten an MCP ``CallToolResult`` into DataFrame rows.\\n\\n        Text blocks that parse as a JSON object become one row; a JSON array of\\n        objects becomes one row per element; anything else is kept as a\\n        ``{\\\"type\\\": ..., \\\"text\\\": ...}`` row so no content is dropped.\\n        \\\"\\\"\\\"\\n        content = getattr(result, \\\"content\\\", None) or []\\n        rows: list[dict[str, Any]] = []\\n        for item in content:\\n            if hasattr(item, \\\"model_dump\\\"):\\n                item_dict = item.model_dump()\\n            elif isinstance(item, dict):\\n                item_dict = dict(item)\\n            elif hasattr(item, \\\"type\\\"):\\n                item_dict = {\\\"type\\\": getattr(item, \\\"type\\\", \\\"text\\\"), \\\"text\\\": getattr(item, \\\"text\\\", None)}\\n            else:\\n                item_dict = {\\\"type\\\": \\\"text\\\", \\\"text\\\": str(item)}\\n            if item_dict.get(\\\"type\\\") != \\\"text\\\":\\n                rows.append(item_dict)\\n                continue\\n            text = item_dict.get(\\\"text\\\")\\n            try:\\n                parsed = json.loads(text) if isinstance(text, str) else None\\n            except json.JSONDecodeError:\\n                parsed = None\\n            if isinstance(parsed, dict):\\n                rows.append(parsed)\\n            elif isinstance(parsed, list) and parsed and all(isinstance(x, dict) for x in parsed):\\n                rows.extend(parsed)\\n            elif parsed is not None:\\n                rows.append({\\\"type\\\": \\\"text\\\", \\\"text\\\": text, \\\"parsed_value\\\": parsed})\\n            else:\\n                rows.append(item_dict)\\n        return rows\\n\\n    # -------------------------------------------------------- tool-mode hook\\n    async def _get_tools(self) -> list[Tool]:\\n        \\\"\\\"\\\"Tool Mode entrypoint. Called by ``Component.to_toolkit()``.\\\"\\\"\\\"\\n        tools, _ = await self._load_tools()\\n        return list(tools)\\n\\n    # ------------------------------------------------------- direct output\\n    async def run_tool(self) -> DataFrame:\\n        \\\"\\\"\\\"Run the selected tool once and return its content as a table.\\\"\\\"\\\"\\n        tool_name = (getattr(self, \\\"tool\\\", \\\"\\\") or \\\"\\\").strip()\\n        if not tool_name:\\n            msg = \\\"Select a tool to run, or turn on Tool Mode and connect the Toolset output to an Agent.\\\"\\n            raise ValueError(msg)\\n        _, tool_cache = await self._load_tools()\\n        tool = tool_cache.get(tool_name)\\n        if tool is None:\\n            available = \\\", \\\".join(sorted(tool_cache)) or \\\"none\\\"\\n            msg = f\\\"Tool {tool_name!r} is not available on this server. Available tools: {available}.\\\"\\n            raise ValueError(msg)\\n        arguments = self._parse_tool_arguments()\\n        result = await tool.coroutine(**arguments)\\n        rows = self._result_rows(result)\\n        frame = DataFrame(rows)\\n        self.status = frame\\n        return frame\\n\\n    # ------------------------------------------------ dropdown live refresh\\n    async def update_build_config(\\n        self,\\n        build_config: dict,\\n        field_value: Any,  # noqa: ARG002 - framework signature; the refresh does not depend on the value\\n        field_name: str | None = None,\\n    ) -> dict:\\n        \\\"\\\"\\\"Refresh the *Tool* dropdown from the live server (best effort).\\\"\\\"\\\"\\n        if field_name == \\\"tool\\\":\\n            try:\\n                tools, _ = await self._load_tools()\\n            except Exception as exc:  # noqa: BLE001 -- keep the documented defaults on any failure\\n                await logger.adebug(f\\\"MCP preset tool refresh failed; keeping default options: {exc}\\\")\\n            else:\\n                names = [t.name for t in tools if getattr(t, \\\"name\\\", None)]\\n                if names:\\n                    build_config[\\\"tool\\\"][\\\"options\\\"] = names\\n                    current = build_config[\\\"tool\\\"].get(\\\"value\\\")\\n                    if current not in names:\\n                        build_config[\\\"tool\\\"][\\\"value\\\"] = \\\"\\\"\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/pydantic_compat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0c61843dff1473f89b6676739444ef20baa15b9a4acc9a7482be10166593ac6\",\"content\":\"\\\"\\\"\\\"Compatibility guards for Pydantic models shipped by the MCP SDK.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\n\\ndef _ensure_fastmcp_settings_model_ready(settings_model: Any, fastmcp_type: type[Any]) -> None:\\n    \\\"\\\"\\\"Rebuild an unresolved FastMCP Settings model with its local forward reference.\\\"\\\"\\\"\\n    if getattr(settings_model, \\\"__pydantic_complete__\\\", True):\\n        return\\n    settings_model.model_rebuild(_types_namespace={\\\"FastMCP\\\": fastmcp_type})\\n\\n\\ndef ensure_fastmcp_settings_ready() -> None:\\n    \\\"\\\"\\\"Make the installed MCP SDK's Settings model safe to instantiate.\\n\\n    Some supported MCP/Pydantic combinations leave the ``FastMCP`` forward\\n    reference unresolved. FastMCP constructs ``Settings`` in ``__init__``, so\\n    rebuild only when Pydantic reports that the model is incomplete.\\n    \\\"\\\"\\\"\\n    from mcp.server.fastmcp import FastMCP\\n    from mcp.server.fastmcp.server import Settings\\n\\n    _ensure_fastmcp_settings_model_ready(Settings, FastMCP)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"870f8f04b6d8565cd37cb4108b799b69c25ad82499e2d6824c7344ec95594b34\",\"content\":\"\\\"\\\"\\\"Security validation for MCP (Model Context Protocol) stdio server configs.\\n\\nBackground\\n----------\\nA tenant-built flow can embed an MCP server config directly in the ``MCPTools`` component\\nvalue (``{\\\"name\\\": ..., \\\"config\\\": {\\\"command\\\": ..., \\\"args\\\": [...], \\\"env\\\": {...}}}``). When the\\nflow runs, that config is handed straight to a stdio transport that executes\\n``bash -c \\\"exec <command> <args>\\\"`` on the server. The pydantic ``MCPServerConfig`` validators\\n(command allowlist, shell-metacharacter block, env blocklist, docker-arg block) only run at\\nthe REST ``/api/v2/mcp/servers`` layer, so the flow-execution path was completely unguarded \u2014\\nany authenticated tenant could embed an arbitrary command and get RCE on the host.\\n\\nThis module is the single source of truth for the allowlist/blocklist data and provides\\n``validate_mcp_stdio_config`` so the same checks can be enforced at the execution sink (in\\n``lfx.base.mcp.util.update_tools``), independent of how the config arrived. The langflow\\n``MCPServerConfig`` pydantic validators import the constants/helper from here so the two\\nenforcement points can never drift.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport shlex\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.base.mcp.source_policy import (\\n    has_leading_cmd_exec_flag,\\n    is_cmd_exec_flag,\\n    parse_mcp_shell_wrapper,\\n    validate_mcp_stdio_source_policy,\\n)\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Collection\\n\\n# Env var through which Langflow binds the agentic MCP server to an authenticated user's id.\\n# Langflow injects it at spawn time from the request identity; it is in DANGEROUS_ENV_VARS so a\\n# tenant-authored stdio config cannot set it. The agentic MCP tools read it and fail closed when\\n# it is absent. Single source of truth for both the injector (lfx.base.mcp.util.update_tools) and\\n# the reader (langflow.agentic.mcp.server).\\nAGENTIC_USER_ID_ENV_VAR = \\\"LANGFLOW_AGENTIC_USER_ID\\\"\\n\\n# Substring identifying the agentic MCP server module in a stdio command, so update_tools knows\\n# when to inject AGENTIC_USER_ID_ENV_VAR.\\nAGENTIC_MCP_MODULE = \\\"langflow.agentic.mcp\\\"\\n\\n# SECURITY: Allowlist of approved MCP stdio commands. Shell wrappers (cmd/sh/bash) are\\n# allowed ONLY to wrap another allowed command (validated below).\\nALLOWED_MCP_COMMANDS = frozenset(\\n    {\\n        \\\"node\\\",\\n        \\\"python\\\",\\n        \\\"python3\\\",\\n        \\\"npx\\\",\\n        \\\"uvx\\\",\\n        \\\"docker\\\",\\n        \\\"cmd\\\",  # Windows command processor (used in starter projects: cmd /c uvx ...)\\n        \\\"sh\\\",  # Unix shell (used in starter projects: sh -c uvx ...)\\n        \\\"bash\\\",  # Bash shell (alternative to sh on Unix/Linux)\\n    }\\n)\\n\\n# SECURITY: Shell metacharacters that enable command injection.\\nDANGEROUS_SHELL_CHARS = frozenset({\\\";\\\", \\\"|\\\", \\\"&\\\", \\\"$\\\", \\\"`\\\", \\\"<\\\", \\\">\\\", \\\"(\\\", \\\")\\\", \\\"\\\\n\\\", \\\"\\\\r\\\"})\\n\\n# SECURITY: Keywords that enable code execution or package installation.\\n# These are blocked by default unless explicitly allowed via COMMAND_SAFE_FLAGS.\\nDANGEROUS_KEYWORDS = frozenset(\\n    {\\n        \\\"-c\\\",\\n        \\\"-e\\\",\\n        \\\"-y\\\",\\n        \\\"--yes\\\",\\n        \\\"pip\\\",\\n        \\\"install\\\",\\n        \\\"npm\\\",\\n        \\\"yarn\\\",\\n        \\\"pnpm\\\",\\n        \\\"eval\\\",\\n        \\\"exec\\\",\\n    }\\n)\\n\\n# SECURITY: Per-command allowlist of flags that would otherwise be considered dangerous.\\n# This enables fine-grained control over which flags are safe for specific commands.\\n# For example, -y/--yes are in DANGEROUS_KEYWORDS but are safe for package managers\\n# like npx/uvx (non-interactive mode), so they're explicitly allowed here.\\nCOMMAND_SAFE_FLAGS: dict[str, frozenset[str]] = {\\n    \\\"npx\\\": frozenset({\\\"-y\\\", \\\"--yes\\\"}),\\n    \\\"uvx\\\": frozenset({\\\"-y\\\", \\\"--yes\\\"}),\\n}\\n\\n# SECURITY: Environment variables that enable code injection via approved commands.\\n# All comparisons are case-insensitive.\\nDANGEROUS_ENV_VARS = frozenset(\\n    {\\n        # -- Shared-object / dylib injection (arbitrary native code execution) --\\n        \\\"ld_preload\\\",\\n        \\\"ld_library_path\\\",\\n        \\\"ld_audit\\\",\\n        \\\"dyld_insert_libraries\\\",\\n        \\\"dyld_library_path\\\",\\n        # -- glibc iconv module injection --\\n        \\\"gconv_path\\\",\\n        # -- Command resolution override --\\n        \\\"path\\\",\\n        # -- Shell startup-script injection --\\n        \\\"bash_env\\\",\\n        \\\"env\\\",\\n        \\\"bash_func_\\\",  # Shellshock-style function export prefix\\n        \\\"shellopts\\\",\\n        \\\"bashopts\\\",\\n        \\\"ps4\\\",\\n        # -- Shell word-splitting / globbing manipulation --\\n        \\\"ifs\\\",\\n        \\\"cdpath\\\",\\n        # -- Node.js code injection --\\n        \\\"node_options\\\",\\n        \\\"node_extra_ca_certs\\\",\\n        # -- Python code injection --\\n        \\\"pythonstartup\\\",\\n        \\\"pythonpath\\\",\\n        # -- Home / config directory redirection --\\n        \\\"home\\\",\\n        \\\"xdg_config_home\\\",\\n        \\\"xdg_data_home\\\",\\n        # -- Temp directory redirection --\\n        \\\"tmpdir\\\",\\n        \\\"tmp\\\",\\n        \\\"temp\\\",\\n        # -- DNS / network manipulation --\\n        \\\"hostaliases\\\",\\n        \\\"localdomain\\\",\\n        \\\"res_options\\\",\\n        # -- Locale / message-catalog loading (glibc reads these as file/format paths) --\\n        \\\"getconf_dir\\\",\\n        \\\"nlspath\\\",\\n        \\\"locpath\\\",\\n        \\\"localedir\\\",\\n        \\\"termcap\\\",\\n        \\\"terminfo\\\",\\n        \\\"terminfo_dirs\\\",\\n        # -- Commands other tools shell out to. ``git``, ``less``, ``man`` and friends execute\\n        #    the value of these as a command line, so an approved runner that invokes any of\\n        #    them turns a tenant string into a spawned process.\\n        \\\"lessopen\\\",\\n        \\\"lessclose\\\",\\n        \\\"lessecho\\\",\\n        \\\"less\\\",\\n        \\\"pager\\\",\\n        \\\"manpager\\\",\\n        \\\"systemd_less\\\",\\n        \\\"editor\\\",\\n        \\\"visual\\\",\\n        \\\"browser\\\",\\n        # -- TLS trust-anchor replacement. Substituting the trust store lets a tenant MITM the\\n        #    package download that an allowlisted uvx/npx runner then executes, so these are a\\n        #    supply-chain code-execution vector, not merely a confidentiality issue.\\n        \\\"requests_ca_bundle\\\",\\n        \\\"ssl_cert_file\\\",\\n        \\\"ssl_cert_dir\\\",\\n        # -- Proxy overrides redirect that same fetch to attacker-controlled infrastructure.\\n        #    ``no_proxy`` only narrows proxy use and is deliberately NOT blocked.\\n        \\\"http_proxy\\\",\\n        \\\"https_proxy\\\",\\n        \\\"all_proxy\\\",\\n        \\\"ftp_proxy\\\",\\n        \\\"rsync_proxy\\\",\\n        # -- Go toolchain (no safe common prefix: ``GO`` also prefixes GOOGLE_* credentials) --\\n        \\\"goflags\\\",\\n        \\\"gopath\\\",\\n        \\\"goroot\\\",\\n        \\\"gobin\\\",\\n        \\\"goproxy\\\",\\n        \\\"goprivate\\\",\\n        # -- JVM class/agent loading --\\n        \\\"classpath\\\",\\n        # -- Windows: ``cmd`` is an allowed wrapper, and these redirect what it resolves --\\n        \\\"comspec\\\",\\n        \\\"psmodulepath\\\",\\n        # -- Langflow-internal trust binding: the agentic MCP server reads the owning user's id\\n        #    from this env var. It must be injected by Langflow at spawn time from the\\n        #    authenticated identity, never supplied through a tenant-authored stdio config\\n        #    (which would let a tenant read/write another tenant's flows). Block it here so a\\n        #    tenant config that tries to set it is rejected before the server is spawned.\\n        \\\"langflow_agentic_user_id\\\",\\n    }\\n)\\n\\n# SECURITY: whole environment-variable FAMILIES that a runtime interprets as code-loading,\\n# option-injection, or package-source directives.\\n#\\n# These are prefixes, not exact names, and that is the point. An exact-name blocklist can only\\n# ever contain the variables somebody thought to enumerate: the original list covered\\n# ``PYTHONPATH`` and ``NODE_OPTIONS`` but not ``OPENSSL_CONF``, which points libcrypto at a\\n# config file whose engine/provider sections name a shared object for OpenSSL to ``dlopen`` --\\n# native code execution inside whatever process the allowlisted runner starts. Denying the\\n# family instead means a variable nobody has enumerated yet (a new ``OPENSSL_*``, a new\\n# ``PYTHON*``) is refused by default rather than forwarded.\\n#\\n# Only families whose members are interpreted by the *runtime* belong here. Application\\n# credentials and configuration use arbitrary vendor-chosen names (``GITHUB_TOKEN``,\\n# ``BRAVE_API_KEY``, ``API_URL``) and must keep working -- see ``SAFE_ENV_VARS`` for the\\n# benign members that live inside an otherwise-denied family.\\nDANGEROUS_ENV_VAR_PREFIXES = (\\n    # -- Dynamic linker / loader (arbitrary native code) --\\n    \\\"ld_\\\",\\n    \\\"dyld_\\\",\\n    # -- glibc module loading --\\n    \\\"gconv_\\\",\\n    # -- OpenSSL config, engine and provider loading (OPENSSL_CONF et al.) --\\n    \\\"openssl_\\\",\\n    # -- Shell startup / function-export injection --\\n    \\\"bash_\\\",\\n    \\\"zsh_\\\",\\n    # -- Package runners: these redirect an allowlisted package name to attacker-controlled\\n    #    code by changing the index, config file, or cache the runner resolves through.\\n    \\\"npm_config_\\\",\\n    \\\"pip_\\\",\\n    \\\"uv_\\\",\\n    \\\"yarn_\\\",\\n    \\\"pnpm_\\\",\\n    \\\"bun_\\\",\\n    \\\"poetry_\\\",\\n    \\\"cargo_\\\",\\n    \\\"rustup_\\\",\\n    \\\"deno_\\\",\\n    \\\"gem_\\\",\\n    # -- Interpreter option / module-path injection --\\n    \\\"python\\\",\\n    \\\"node_\\\",\\n    \\\"perl\\\",\\n    \\\"ruby\\\",\\n    \\\"lua_\\\",\\n    \\\"julia_\\\",\\n    \\\"php_\\\",\\n    \\\"java_\\\",\\n    \\\"jdk_\\\",\\n    \\\"_java_\\\",\\n    \\\"dotnet_\\\",\\n    \\\"coreclr_\\\",\\n    \\\"mono_\\\",\\n    # -- git executes several of these as helper command lines (GIT_SSH_COMMAND, GIT_ASKPASS,\\n    #    GIT_PROXY_COMMAND, GIT_EXTERNAL_DIFF) and resolves its config from others.\\n    \\\"git_\\\",\\n    # -- TLS trust anchors and curl configuration --\\n    \\\"ssl_cert_\\\",\\n    \\\"curl_\\\",\\n    # -- Native plugin/module search paths honored by common shared libraries --\\n    \\\"gtk_\\\",\\n    \\\"qt_\\\",\\n    \\\"gio_\\\",\\n    \\\"gst_\\\",\\n    # -- Config/data directory redirection --\\n    \\\"xdg_\\\",\\n)\\n\\n# Benign members of an otherwise-denied family. Each of these is read by the runtime as plain\\n# behavior configuration -- it names no file to load, no module to import, and no command to\\n# run -- so denying it would break ordinary MCP server configs for no security gain.\\nSAFE_ENV_VARS = frozenset(\\n    {\\n        # CPython output/encoding behavior; none of these load code.\\n        \\\"pythonunbuffered\\\",\\n        \\\"pythonioencoding\\\",\\n        \\\"pythondontwritebytecode\\\",\\n        \\\"pythonhashseed\\\",\\n        \\\"pythonutf8\\\",\\n        \\\"pythonfaulthandler\\\",\\n        # Node's own conventional mode switch (not a loader directive).\\n        \\\"node_env\\\",\\n        # git commit attribution and its non-interactive switch.\\n        \\\"git_author_name\\\",\\n        \\\"git_author_email\\\",\\n        \\\"git_author_date\\\",\\n        \\\"git_committer_name\\\",\\n        \\\"git_committer_email\\\",\\n        \\\"git_committer_date\\\",\\n        \\\"git_terminal_prompt\\\",\\n        # Headless Qt selection; picks a built-in platform plugin, not a path to load from.\\n        \\\"qt_qpa_platform\\\",\\n    }\\n)\\n\\n# Backward-compatible name previously exported by ``lfx.base.mcp.util``.\\nDANGEROUS_MCP_ENV_VARS = DANGEROUS_ENV_VARS\\n\\n# SECURITY: docker-flag policy for MCP stdio servers. ``docker`` is allowlisted but several flags\\n# turn a container run into host access. Two modes, selected by LANGFLOW_MCP_SERVER_DOCKER_HARDENING\\n# (default off = lenient/previous behavior, on = strict multi-tenant policy) -- the\\n# mcp_server_docker_hardening setting docstring has the operator-facing description; the per-set\\n# comments below cover what each blocks. Both modes handle the inline (``--volume=/:/host``) and\\n# space-separated (``--volume /:/host``) forms.\\n\\n# -- Default (lenient / previous behavior) --\\nDOCKER_DANGEROUS_ARGS = frozenset({\\\"--privileged\\\", \\\"--cap-add\\\"})\\nDOCKER_DANGEROUS_ARG_PREFIXES = (\\\"--net=\\\", \\\"--network=\\\", \\\"--pid=\\\", \\\"--cap-add=\\\", \\\"--privileged=\\\")\\n\\n# -- Hardened (opt-in) --\\n# Flags with no safe value for an MCP stdio transport: host filesystem / device access,\\n# Docker API access, host port exposure, persistence, and privilege escalation.\\nDOCKER_HARDENED_BLOCKED_FLAGS = frozenset(\\n    {\\n        \\\"--privileged\\\",\\n        \\\"--cap-add\\\",\\n        \\\"-v\\\",\\n        \\\"--volume\\\",\\n        \\\"--volumes-from\\\",\\n        \\\"--mount\\\",\\n        \\\"--device\\\",\\n        \\\"--device-cgroup-rule\\\",\\n        \\\"--env-file\\\",\\n        \\\"--label-file\\\",\\n        \\\"--cidfile\\\",\\n        \\\"--gpus\\\",\\n        \\\"--use-api-socket\\\",\\n        \\\"--link\\\",\\n        \\\"--runtime\\\",\\n        \\\"-p\\\",\\n        \\\"-P\\\",\\n        \\\"--publish\\\",\\n        \\\"--publish-all\\\",\\n        \\\"--restart\\\",\\n    }\\n)\\n# Namespace flags: dangerous only when sharing the host's or another container's namespace.\\nDOCKER_HARDENED_NAMESPACE_FLAGS = frozenset({\\\"--pid\\\", \\\"--ipc\\\", \\\"--uts\\\", \\\"--cgroupns\\\", \\\"--userns\\\"})\\n# Network flags: only the default-isolated values are safe. ``host`` / ``container:*`` break\\n# isolation, and a *named* network can be the operator's internal bridge (lateral movement), so\\n# anything outside this allowlist is rejected.\\nDOCKER_HARDENED_NETWORK_FLAGS = frozenset({\\\"--net\\\", \\\"--network\\\"})\\nDOCKER_SAFE_NETWORK_VALUES = frozenset({\\\"none\\\", \\\"bridge\\\", \\\"default\\\"})\\n# ``--security-opt`` values that downgrade the sandbox (seccomp=unconfined, apparmor=unconfined,\\n# systempaths=unconfined, label:disable). The hardening value ``no-new-privileges`` is allowed.\\nDOCKER_DANGEROUS_SECURITY_OPT_SUBSTRINGS = (\\\"unconfined\\\", \\\"disable\\\")\\n\\n# SECURITY: Shell wrapper commands that can execute other commands.\\nSHELL_WRAPPERS = frozenset({\\\"cmd\\\", \\\"sh\\\", \\\"bash\\\"})\\n\\n# SECURITY: Shell command flags that execute code. cmd.exe accepts more spellings than ``/c``\\n# (``/k``, ``/r``, and clustered forms such as ``/q/k``); those are recognized by\\n# ``is_cmd_exec_flag`` rather than listed here, because a bare ``/k`` token is a legitimate\\n# path operand for the non-cmd commands that also consult this set.\\nSHELL_EXEC_FLAGS = frozenset({\\\"-c\\\", \\\"/c\\\"})\\nMAX_SHELL_WRAPPER_DEPTH = 4\\n\\n# Python modules owned by Langflow whose server identity is rebound from the authenticated\\n# request in ``update_tools``. No tenant-selected script/module is allowed in interpreter-\\n# hardened mode.\\nHARDENED_ALLOWED_PYTHON_MODULES = frozenset({\\\"langflow.agentic.mcp\\\", \\\"langflow.agentic.mcp.server\\\"})\\nPYTHON_MODULE_MIN_ARGS = 2\\n\\n\\ndef _is_shell_exec_flag(arg: str, base_command: str = \\\"\\\") -> bool:\\n    \\\"\\\"\\\"Return whether *arg* makes the shell wrapper execute the tokens that follow it.\\n\\n    ``base_command`` selects the cmd.exe switch grammar (``/c``, ``/k``, ``/r``, and clustered\\n    forms such as ``/q/k``). It is opt-in because a ``/``-prefixed token is an ordinary path\\n    operand for every other command that consults this helper.\\n    \\\"\\\"\\\"\\n    arg_lower = arg.lower()\\n    if arg_lower in SHELL_EXEC_FLAGS:\\n        return True\\n    if base_command == \\\"cmd\\\" and is_cmd_exec_flag(arg_lower):\\n        return True\\n    return arg_lower.startswith(\\\"-\\\") and not arg_lower.startswith(\\\"--\\\") and \\\"c\\\" in arg_lower[1:]\\n\\n\\ndef _has_leading_shell_exec_flag(args: list[str], base_command: str = \\\"\\\") -> bool:\\n    \\\"\\\"\\\"Return whether a shell execution flag appears before every script operand.\\\"\\\"\\\"\\n    if not args:\\n        return False\\n    if extract_base_command(base_command) == \\\"cmd\\\":\\n        return has_leading_cmd_exec_flag(args)\\n    return _is_shell_exec_flag(args[0], base_command)\\n\\n\\nclass MCPStdioSecurityError(ValueError):\\n    \\\"\\\"\\\"Raised when an MCP stdio server config fails security validation.\\n\\n    Subclasses ``ValueError`` so existing ``except ValueError`` handlers in the MCP\\n    connection path still catch it.\\n    \\\"\\\"\\\"\\n\\n\\ndef is_dangerous_mcp_env_var(key: str) -> bool:\\n    \\\"\\\"\\\"Return whether an environment variable can alter MCP process execution.\\n\\n    Deny-by-default across the runtime families in ``DANGEROUS_ENV_VAR_PREFIXES``, so an\\n    unenumerated member of a dangerous family (a newly added ``OPENSSL_*`` or ``PYTHON*``)\\n    is refused without a code change. ``SAFE_ENV_VARS`` carves out the specific members of\\n    those families that configure behavior rather than load code.\\n\\n    This predicate is independent of the opt-in ``mcp_server_env_allowlist``; the allowlist\\n    is applied by :func:`validate_mcp_stdio_config`.\\n    \\\"\\\"\\\"\\n    lower_key = key.lower()\\n    if lower_key in SAFE_ENV_VARS:\\n        return False\\n    return lower_key in DANGEROUS_ENV_VARS or lower_key.startswith(DANGEROUS_ENV_VAR_PREFIXES)\\n\\n\\ndef _configured_env_allowlist() -> frozenset[str] | None:\\n    \\\"\\\"\\\"Resolve the opt-in strict env allowlist, or ``None`` when the operator has not set one.\\n\\n    ``None`` (the default) keeps the family policy above as the only env control, preserving\\n    existing configs. An explicitly empty value means \\\"no tenant-supplied environment at all\\\",\\n    which is the strictest setting -- it is deliberately distinguishable from unset.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        configured = getattr(get_settings_service().settings, \\\"mcp_server_env_allowlist\\\", None)\\n    except Exception:  # noqa: BLE001 - settings may be unavailable (e.g. early import)\\n        return None\\n    if not isinstance(configured, str):\\n        return None\\n    return frozenset(item.strip().lower() for item in configured.split(\\\",\\\") if item.strip())\\n\\n\\ndef _is_file_path(command: str) -> bool:\\n    \\\"\\\"\\\"Whether command looks like a filesystem path (Unix/relative/Windows) vs a bare command name.\\\"\\\"\\\"\\n    drive_letter_len = 3\\n    return (\\n        command.startswith((\\\"/\\\", \\\"./\\\", \\\"../\\\"))\\n        or \\\"\\\\\\\\\\\" in command\\n        or (len(command) >= drive_letter_len and command[1:3] in {\\\":\\\\\\\\\\\", \\\":/\\\"})  # Windows drive letter\\n    )\\n\\n\\ndef extract_base_command(command: str) -> str:\\n    r\\\"\\\"\\\"Extract the base command name from a possibly fully-qualified path.\\n\\n    Handles Unix paths (``/usr/bin/node``), Windows paths\\n    (``C:\\\\\\\\Program Files\\\\\\\\nodejs\\\\\\\\node.exe``), and bare names (``node``). Also handles\\n    commands with arguments (e.g. ``uvx mcp-server-fetch``) by taking the first token,\\n    unless the value is an actual file path.\\n    \\\"\\\"\\\"\\n    command_only = command.split()[0] if not _is_file_path(command) and command.strip() else command\\n\\n    normalized_path = command_only.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n    base_command = Path(normalized_path).name\\n\\n    if base_command.lower().endswith(\\\".exe\\\"):\\n        base_command = base_command[:-4]\\n\\n    return base_command\\n\\n\\ndef _docker_hardening_enabled() -> bool:\\n    \\\"\\\"\\\"Whether the opt-in MCP docker-arg hardening policy is active.\\n\\n    Reads ``LANGFLOW_MCP_SERVER_DOCKER_HARDENING`` (default False). Fails safe to False if the\\n    settings service is unavailable -- the hardening is an opt-in multi-tenant control, not a\\n    default, so an unreadable setting must not start rejecting previously-valid docker configs.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        return bool(get_settings_service().settings.mcp_server_docker_hardening)\\n    except Exception:  # noqa: BLE001 - settings may be unavailable (e.g. early import); default off\\n        return False\\n\\n\\ndef _interpreter_hardening_enabled() -> bool:\\n    \\\"\\\"\\\"Whether direct Python/Node MCP entrypoints are restricted for multi-tenant use.\\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        return bool(get_settings_service().settings.mcp_server_interpreter_hardening)\\n    except Exception:  # noqa: BLE001 - settings may be unavailable; preserve the legacy default\\n        return False\\n\\n\\ndef _normalize_package_name(package_spec: str) -> str:\\n    \\\"\\\"\\\"Normalize npm/Python package specs to the package identity used by the allowlist.\\\"\\\"\\\"\\n    package = package_spec.strip().lower()\\n    if package.startswith(\\\"@\\\"):\\n        slash_index = package.find(\\\"/\\\")\\n        version_index = package.rfind(\\\"@\\\")\\n        if slash_index >= 0 and version_index > slash_index:\\n            package = package[:version_index]\\n    else:\\n        package = package.split(\\\"@\\\", 1)[0]\\n\\n    for separator in (\\\"==\\\", \\\"~=\\\", \\\">=\\\", \\\"<=\\\", \\\"!=\\\", \\\">\\\", \\\"<\\\", \\\"[\\\"):\\n        package = package.split(separator, 1)[0]\\n    return package.strip()\\n\\n\\ndef _validate_interpreter_invocation(base_command: str, args: list[str], *, hardened: bool) -> None:\\n    \\\"\\\"\\\"Reject tenant-selected interpreter code while preserving validated wrappers/internal code.\\\"\\\"\\\"\\n    if not hardened:\\n        return\\n    if base_command in SHELL_WRAPPERS:\\n        if _has_leading_shell_exec_flag(args, base_command):\\n            return\\n        msg = (\\n            f\\\"Shell command '{base_command}' must wrap an approved MCP command when \\\"\\n            \\\"LANGFLOW_MCP_SERVER_INTERPRETER_HARDENING=true. Direct shell scripts are not allowed.\\\"\\n        )\\n        raise MCPStdioSecurityError(msg)\\n    if base_command not in {\\\"node\\\", \\\"python\\\", \\\"python3\\\"}:\\n        return\\n    if (\\n        base_command in {\\\"python\\\", \\\"python3\\\"}\\n        and len(args) >= PYTHON_MODULE_MIN_ARGS\\n        and args[0] == \\\"-m\\\"\\n        and args[1] in HARDENED_ALLOWED_PYTHON_MODULES\\n    ):\\n        return\\n    msg = (\\n        f\\\"Interpreter command '{base_command}' is not allowed when \\\"\\n        \\\"LANGFLOW_MCP_SERVER_INTERPRETER_HARDENING=true. Use an operator-approved package runner instead.\\\"\\n    )\\n    raise MCPStdioSecurityError(msg)\\n\\n\\ndef _docker_arg_value(arg: str, args: list[str], index: int) -> str:\\n    \\\"\\\"\\\"Return the lowercased value bound to a docker flag token.\\n\\n    Handles both the inline ``--flag=value`` form and the space-separated ``--flag value`` form\\n    (where the value is the following token).\\n    \\\"\\\"\\\"\\n    _, sep, inline = arg.partition(\\\"=\\\")\\n    if sep:\\n        return inline.lower()\\n    return args[index + 1].lower() if index + 1 < len(args) else \\\"\\\"\\n\\n\\ndef _raise_docker_arg(arg: str) -> None:\\n    msg = f\\\"Docker argument '{arg}' is not allowed for security reasons\\\"\\n    raise MCPStdioSecurityError(msg)\\n\\n\\ndef _is_docker_short_volume_flag(arg: str) -> bool:\\n    \\\"\\\"\\\"Return whether a Docker short-option token contains the ``-v`` volume flag.\\n\\n    Docker accepts the volume value attached to the shorthand (``-v/:/host``) and accepts\\n    ``-v`` after bundled boolean flags (``-itv /:/host``). Exact-token matching misses both.\\n    \\\"\\\"\\\"\\n    if not arg.startswith(\\\"-\\\") or arg.startswith(\\\"--\\\"):\\n        return False\\n    short_flags = arg[1:].split(\\\"=\\\", 1)[0]\\n    if short_flags.startswith(\\\"v\\\"):\\n        return True\\n    volume_index = short_flags.find(\\\"v\\\")\\n    return volume_index > 0 and all(flag in {\\\"d\\\", \\\"i\\\", \\\"P\\\", \\\"t\\\"} for flag in short_flags[:volume_index])\\n\\n\\ndef _is_docker_short_publish_flag(arg: str) -> bool:\\n    \\\"\\\"\\\"Return whether a Docker short-option token publishes host ports.\\n\\n    Docker accepts values attached to ``-p`` and bundles boolean flags before it\\n    (for example, ``-itp8080:80``), so exact-token checks are insufficient.\\n    \\\"\\\"\\\"\\n    if not arg.startswith(\\\"-\\\") or arg.startswith(\\\"--\\\"):\\n        return False\\n    short_flags = arg[1:].split(\\\"=\\\", 1)[0]\\n    for publish_flag in (\\\"p\\\", \\\"P\\\"):\\n        publish_index = short_flags.find(publish_flag)\\n        if publish_index == 0 or (\\n            publish_index > 0 and all(flag in {\\\"d\\\", \\\"i\\\", \\\"t\\\"} for flag in short_flags[:publish_index])\\n        ):\\n            return True\\n    return False\\n\\n\\ndef _validate_docker_args_lenient(args: list[str]) -> None:\\n    \\\"\\\"\\\"Default policy: only privilege/cap flags and host-namespace ``=`` forms (previous behavior).\\\"\\\"\\\"\\n    for arg in args:\\n        if arg in DOCKER_DANGEROUS_ARGS or arg.startswith(DOCKER_DANGEROUS_ARG_PREFIXES):\\n            _raise_docker_arg(arg)\\n\\n\\ndef _validate_docker_args_hardened(args: list[str]) -> None:\\n    \\\"\\\"\\\"Opt-in strict docker policy.\\n\\n    Blocks host filesystem/device mounts, privilege flags, host/another-container namespaces,\\n    non-default networks, and sandbox-downgrading ``--security-opt`` -- while allowing benign\\n    network/namespace/security values.\\n    \\\"\\\"\\\"\\n    # MCP Docker transports only need ``docker run``. Other subcommands operate on existing\\n    # containers/images or invoke broader build/daemon surfaces (e.g. exec/cp/build/context),\\n    # which defeats the isolation policy when the Docker socket is available. Requiring run as\\n    # the first token also prevents tenant-controlled global daemon selectors such as ``-H``.\\n    if not args or args[0].lower() != \\\"run\\\":\\n        _raise_docker_arg(args[0] if args else \\\"<missing run subcommand>\\\")\\n\\n    for i, arg in enumerate(args):\\n        flag = arg.split(\\\"=\\\", 1)[0]\\n        if (\\n            flag in DOCKER_HARDENED_BLOCKED_FLAGS\\n            or _is_docker_short_volume_flag(arg)\\n            or _is_docker_short_publish_flag(arg)\\n        ):\\n            _raise_docker_arg(arg)\\n        elif flag in DOCKER_HARDENED_NAMESPACE_FLAGS:\\n            value = _docker_arg_value(arg, args, i)\\n            if value == \\\"host\\\" or value.startswith(\\\"container:\\\"):\\n                _raise_docker_arg(arg)\\n        elif flag in DOCKER_HARDENED_NETWORK_FLAGS:\\n            if _docker_arg_value(arg, args, i) not in DOCKER_SAFE_NETWORK_VALUES:\\n                _raise_docker_arg(arg)\\n        elif flag == \\\"--security-opt\\\":\\n            value = _docker_arg_value(arg, args, i)\\n            if any(s in value for s in DOCKER_DANGEROUS_SECURITY_OPT_SUBSTRINGS):\\n                _raise_docker_arg(arg)\\n\\n\\ndef _validate_docker_invocation(args: list[str], *, hardened: bool | None) -> None:\\n    \\\"\\\"\\\"Apply the selected Docker policy to top-level and shell-wrapped invocations.\\\"\\\"\\\"\\n    use_hardened_policy = _docker_hardening_enabled() if hardened is None else hardened\\n    if use_hardened_policy:\\n        _validate_docker_args_hardened(args)\\n    else:\\n        _validate_docker_args_lenient(args)\\n\\n\\ndef validate_mcp_stdio_config(\\n    command: str | None,\\n    args: list[str] | None,\\n    env: dict[str, str] | None,\\n    *,\\n    docker_hardening: bool | None = None,\\n    allowed_packages: Collection[str] | str | None = None,\\n    interpreter_hardening: bool | None = None,\\n    _depth: int = 0,\\n    _seen: frozenset[tuple[str, tuple[str, ...]]] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Validate an MCP stdio command/args/env triple against the security policy.\\n\\n    Mirrors the ``MCPServerConfig`` pydantic validators so the same protections apply at the\\n    flow-execution sink, where a tenant-embedded config never instantiates that model.\\n\\n    Args:\\n        command: the stdio server command (allowlisted base command, optionally a file path).\\n        args: the command arguments to scan for metacharacters / dangerous keywords / docker flags.\\n        env: the environment overrides to scan against the reserved-name blocklist.\\n        docker_hardening: select the docker-arg policy. ``None`` (default) reads the\\n            ``LANGFLOW_MCP_SERVER_DOCKER_HARDENING`` setting; pass an explicit bool to override\\n            (used by tests). ``False`` is the lenient/previous behavior; ``True`` is the\\n            comprehensive multi-tenant policy.\\n        allowed_packages: exact package identities that ``npx``/``uvx`` may execute.\\n            ``None`` reads ``LANGFLOW_MCP_SERVER_ALLOWED_PACKAGES``; when neither is set,\\n            legacy single-tenant package-runner behavior is preserved.\\n        interpreter_hardening: restrict Python/Node entrypoints to Langflow's authenticated\\n            internal agentic MCP module. ``None`` reads\\n            ``LANGFLOW_MCP_SERVER_INTERPRETER_HARDENING``; the default is disabled for\\n            legacy single-tenant compatibility.\\n\\n    Raises:\\n        MCPStdioSecurityError: If the command is not allowlisted, the args contain shell\\n            metacharacters / dangerous keywords / illegal shell-exec flags, a shell wrapper\\n            wraps a non-allowed command, an env var is in the blocklist, or a docker arg\\n            breaks container isolation.\\n    \\\"\\\"\\\"\\n    args = list(args or [])\\n    if interpreter_hardening is None:\\n        interpreter_hardening = _interpreter_hardening_enabled()\\n\\n    # The structured command field is exactly one executable. Options belong in args so every\\n    # policy layer sees the same argv. Parent-directory spaces remain valid for executable paths.\\n    if command:\\n        normalized = command.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n        executable_name = normalized.rsplit(\\\"/\\\", 1)[-1]\\n        first_space = command.find(\\\" \\\")\\n        first_separator = min((index for index, char in enumerate(command) if char in \\\"/\\\\\\\\\\\"), default=-1)\\n        invalid_whitespace = command != command.strip() or any(char.isspace() and char != \\\" \\\" for char in command)\\n        space_without_path_prefix = first_space >= 0 and not 0 <= first_separator < first_space\\n        if (\\n            not executable_name\\n            or invalid_whitespace\\n            or space_without_path_prefix\\n            or any(char.isspace() for char in executable_name)\\n        ):\\n            msg = (\\n                \\\"MCP stdio command must be a single executable name or path; \\\"\\n                \\\"put options and arguments in the 'args' field\\\"\\n            )\\n            raise MCPStdioSecurityError(msg)\\n\\n        signature = (command, tuple(args))\\n        seen = _seen or frozenset()\\n        if signature in seen:\\n            msg = \\\"MCP stdio shell wrapper recursion is not allowed\\\"\\n            raise MCPStdioSecurityError(msg)\\n        _seen = seen | {signature}\\n\\n    # Command allowlist.\\n    if command:\\n        base_command = extract_base_command(command)\\n        if base_command not in ALLOWED_MCP_COMMANDS:\\n            allowed_list = \\\", \\\".join(sorted(ALLOWED_MCP_COMMANDS))\\n            msg = f\\\"Command '{base_command}' is not allowed for security reasons. Allowed commands: {allowed_list}\\\"\\n            raise MCPStdioSecurityError(msg)\\n        _validate_interpreter_invocation(base_command, args, hardened=interpreter_hardening)\\n\\n    normalized_allowed_packages: frozenset[str] | None = None\\n    if allowed_packages is not None:\\n        configured_packages = allowed_packages.split(\\\",\\\") if isinstance(allowed_packages, str) else allowed_packages\\n        normalized_allowed_packages = frozenset(\\n            _normalize_package_name(str(package)) for package in configured_packages if str(package).strip()\\n        )\\n    try:\\n        validate_mcp_stdio_source_policy(\\n            command,\\n            args,\\n            allowed_packages=normalized_allowed_packages,\\n            docker_hardening=docker_hardening,\\n            interpreter_hardening=interpreter_hardening,\\n        )\\n    except ValueError as exc:\\n        raise MCPStdioSecurityError(str(exc)) from exc\\n\\n    # Shell-wrapper rules: -c/-/c only with shell wrappers, and a wrapper may only wrap\\n    # another allowed (non-shell) command. This is what blocks `bash -c '<payload>'`. Checked\\n    # before the metacharacter scan so a `-c` on a non-shell command is reported as such.\\n    if command and args:\\n        base_command = extract_base_command(command)\\n        # Shells and Python interpret ``-c`` as executable code. Package\\n        # runners have their own command-aware flag policy; scanning every\\n        # single-dash token here would misclassify valid uvx values such as\\n        # ``-wmcp-proxy`` merely because the package name contains a ``c``.\\n        checks_code_exec_flags = base_command in SHELL_WRAPPERS | {\\\"python\\\", \\\"python3\\\"}\\n        has_shell_exec_flag = checks_code_exec_flags and any(_is_shell_exec_flag(arg, base_command) for arg in args)\\n\\n        if has_shell_exec_flag and base_command not in SHELL_WRAPPERS:\\n            msg = f\\\"Flag -c or /c is only allowed with shell wrappers (cmd/sh/bash), not with '{base_command}'\\\"\\n            raise MCPStdioSecurityError(msg)\\n\\n        if base_command in SHELL_WRAPPERS:\\n            # Derive the payload from the parsed wrapper rather than a fixed argv index:\\n            # cmd.exe allows benign switches ahead of the execution switch (\\\"/d /c uvx ...\\\"),\\n            # so args[1] would be \\\"/c\\\" there and this gate would report \\\"cannot execute 'c'\\\".\\n            # ``_has_leading_shell_exec_flag`` still guards the position, so a script operand\\n            # cannot precede the execution switch.\\n            wrapped_command = None\\n            wrapped_args: list[str] = []\\n            if _has_leading_shell_exec_flag(args, base_command) and len(args) > 1:\\n                # cmd.exe allows benign switches ahead of the execution switch (\\\"/d /c uvx ...\\\"),\\n                # so a fixed args[1] would be \\\"/c\\\" and this gate would report \\\"cannot execute 'c'\\\".\\n                # Only cmd needs the parsed payload: sh/bash carry their whole command in one\\n                # argument (\\\"sh -c 'id > /tmp/x'\\\"), and splitting that here would let the gate\\n                # inspect only the first token instead of the full command string.\\n                # ``parse_mcp_shell_wrapper`` rejects shell control characters in the cmd\\n                # payload (and unparseable quoting) with a bare ValueError. This function's\\n                # contract is MCPStdioSecurityError for every policy denial, so convert it\\n                # here the same way the source-policy call above does -- otherwise a\\n                # ``cmd /c \\\"uvx x && calc\\\"`` denial escapes as a different exception type\\n                # than the equivalent ``sh -c`` denial raised by the metacharacter scan.\\n                try:\\n                    parsed_wrapper = parse_mcp_shell_wrapper(base_command, args) if base_command == \\\"cmd\\\" else None\\n                except ValueError as exc:\\n                    raise MCPStdioSecurityError(str(exc)) from exc\\n                if parsed_wrapper is not None:\\n                    wrapped_command, wrapped_args = parsed_wrapper\\n                else:\\n                    wrapped_command = args[1]\\n                    wrapped_args = args[2:]\\n\\n            if wrapped_command:\\n                wrapped_base = extract_base_command(wrapped_command)\\n                allowed_wrapped = ALLOWED_MCP_COMMANDS - SHELL_WRAPPERS\\n                if wrapped_base not in allowed_wrapped:\\n                    msg = (\\n                        f\\\"Shell wrapper '{base_command}' cannot execute '{wrapped_base}'. \\\"\\n                        f\\\"Only these commands can be wrapped: {', '.join(sorted(allowed_wrapped))}\\\"\\n                    )\\n                    raise MCPStdioSecurityError(msg)\\n\\n                # Validate the wrapped package runner too. The command may be one string\\n                # (``sh -c 'uvx package'``) or split tokens (``cmd /c uvx package``).\\n                try:\\n                    wrapped_tokens = shlex.split(wrapped_command)\\n                except ValueError:\\n                    wrapped_tokens = wrapped_command.split()\\n                if wrapped_tokens:\\n                    nested_command = wrapped_tokens[0]\\n                    nested_args = wrapped_tokens[1:] + wrapped_args\\n                    nested_base = extract_base_command(nested_command)\\n                    _validate_interpreter_invocation(nested_base, nested_args, hardened=interpreter_hardening)\\n                    if nested_base == \\\"docker\\\":\\n                        _validate_docker_invocation(nested_args, hardened=docker_hardening)\\n\\n    # Argument metacharacters and dangerous keywords.\\n    if args:\\n        # Shell metacharacters enable command injection by breaking out of argument context\\n        for arg in args:\\n            for char in DANGEROUS_SHELL_CHARS:\\n                if char in arg:\\n                    msg = f\\\"Argument contains dangerous shell metacharacter '{char}': {arg}\\\"\\n                    raise MCPStdioSecurityError(msg)\\n\\n        # SECURITY FIX: Tokenize arguments to catch combined dangerous keywords\\n        # like \\\"pip install requests\\\" that bypass whole-string matching.\\n        base_command = extract_base_command(command) if command else \\\"\\\"\\n        for arg in args:\\n            arg_lower = arg.lower()\\n\\n            # Shell exec flags require special validation context to prevent code injection\\n            if arg_lower in SHELL_EXEC_FLAGS:\\n                continue\\n\\n            # Some flags are dangerous in general but safe for specific commands (allowlist)\\n            safe_flags = COMMAND_SAFE_FLAGS.get(base_command, frozenset())\\n            if arg_lower in safe_flags:\\n                continue\\n\\n            # Use shell-style parsing to handle quotes and escapes properly\\n            try:\\n                tokens = shlex.split(arg)\\n            except ValueError:\\n                # Malformed input still needs checking; whitespace split is safer than skipping\\n                tokens = arg.split()\\n\\n            # Attackers may use separators like commas/semicolons to bypass tokenization\\n            expanded_tokens = []\\n            for token in tokens:\\n                import re\\n\\n                subtokens = re.split(r\\\"[,;|&]+\\\", token)\\n                expanded_tokens.extend(t for t in subtokens if t)\\n\\n            for token in expanded_tokens:\\n                token_lower = token.lower()\\n                if token_lower in DANGEROUS_KEYWORDS:\\n                    msg = f\\\"Argument '{arg}' contains dangerous keyword '{token}' and is not allowed\\\"\\n                    raise MCPStdioSecurityError(msg)\\n\\n    # Environment-variable policy. Two layers, both fail-safe:\\n    #   1. Always on: deny whole runtime families (see DANGEROUS_ENV_VAR_PREFIXES).\\n    #   2. Opt-in: when the operator sets mcp_server_env_allowlist, that list is authoritative\\n    #      and every name outside it is refused, which is the durable allowlist posture.\\n    if env:\\n        env_allowlist = _configured_env_allowlist()\\n        for key in env:\\n            if env_allowlist is not None:\\n                if key.strip().lower() not in env_allowlist:\\n                    msg = (\\n                        f\\\"Environment variable '{key}' is not allowed: this deployment restricts \\\"\\n                        \\\"MCP stdio environments to LANGFLOW_MCP_SERVER_ENV_ALLOWLIST\\\"\\n                    )\\n                    raise MCPStdioSecurityError(msg)\\n                continue\\n            if is_dangerous_mcp_env_var(key):\\n                msg = f\\\"Environment variable '{key}' is not allowed for security reasons\\\"\\n                raise MCPStdioSecurityError(msg)\\n\\n    # Docker isolation-breaking arguments. The default (lenient) policy preserves the previous\\n    # behavior; the opt-in hardened policy adds host filesystem/device/namespace coverage. See\\n    # the DOCKER_* constants above for the rationale of each set.\\n    if command and args and extract_base_command(command) == \\\"docker\\\":\\n        _validate_docker_invocation(args, hardened=docker_hardening)\\n\\n    if command and extract_base_command(command) in SHELL_WRAPPERS:\\n        try:\\n            wrapped = parse_mcp_shell_wrapper(command, args)\\n        except ValueError as exc:\\n            raise MCPStdioSecurityError(str(exc)) from exc\\n        if wrapped:\\n            if _depth >= MAX_SHELL_WRAPPER_DEPTH:\\n                msg = f\\\"MCP stdio shell wrapper nesting exceeds {MAX_SHELL_WRAPPER_DEPTH} levels\\\"\\n                raise MCPStdioSecurityError(msg)\\n            validate_mcp_stdio_config(\\n                wrapped[0],\\n                wrapped[1],\\n                env,\\n                docker_hardening=docker_hardening,\\n                allowed_packages=allowed_packages,\\n                interpreter_hardening=interpreter_hardening,\\n                _depth=_depth + 1,\\n                _seen=_seen,\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/source_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01461da08581b125b69467070e55e2879a7a01be174058741c2addc1f5b8a7e1\",\"content\":\"\\\"\\\"\\\"Package-source and Docker host-access policy for MCP stdio servers.\\n\\nApproved MCP launchers such as ``uvx`` and ``npx`` still install code before\\nstarting a server. Their registry/configuration controls therefore belong to\\nLangflow's execution boundary, not to tenant-authored server configuration.\\nThis module keeps that command-aware policy small and dependency-free so it can\\nbe enforced both when the REST model is written and immediately before spawn.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nimport shlex\\nfrom pathlib import Path\\n\\nPACKAGE_MANAGER_CONFIG_ENV_PREFIXES = (\\\"npm_config_\\\", \\\"pip_\\\", \\\"uv_\\\")\\nWINDOWS_DRIVE_PREFIX_LENGTH = 3\\n\\nUVX_BLOCKED_SOURCE_FLAGS = frozenset(\\n    {\\n        \\\"--index\\\",\\n        \\\"--default-index\\\",\\n        \\\"--index-url\\\",\\n        \\\"--extra-index-url\\\",\\n        \\\"--find-links\\\",\\n        \\\"--no-index\\\",\\n        \\\"--config-file\\\",\\n        \\\"--env-file\\\",\\n        \\\"--with-editable\\\",\\n        \\\"--with-requirements\\\",\\n        \\\"--constraints\\\",\\n        \\\"--build-constraints\\\",\\n        \\\"--overrides\\\",\\n        \\\"--directory\\\",\\n        \\\"--project\\\",\\n    }\\n)\\nUVX_BLOCKED_SHORT_SOURCE_FLAGS = frozenset({\\\"-i\\\", \\\"-f\\\", \\\"-c\\\", \\\"-b\\\"})\\nUVX_TRUSTED_PACKAGE_FLAGS = frozenset({\\\"--from\\\", \\\"--with\\\", \\\"-w\\\"})\\nUVX_ATTACHED_VALUE_SHORT_FLAGS = frozenset({\\\"-C\\\", \\\"-P\\\", \\\"-p\\\"})\\nUVX_CLUSTERABLE_BOOLEAN_SHORT_FLAGS = frozenset({\\\"U\\\", \\\"V\\\", \\\"h\\\", \\\"n\\\", \\\"q\\\", \\\"v\\\"})\\nUVX_SAFE_BOOLEAN_FLAGS = frozenset(\\n    {\\n        \\\"-U\\\",\\n        \\\"-V\\\",\\n        \\\"-h\\\",\\n        \\\"-n\\\",\\n        \\\"-q\\\",\\n        \\\"-v\\\",\\n        \\\"-y\\\",\\n        \\\"--compile-bytecode\\\",\\n        \\\"--help\\\",\\n        \\\"--isolated\\\",\\n        \\\"--lfs\\\",\\n        \\\"--managed-python\\\",\\n        \\\"--native-tls\\\",\\n        \\\"--no-binary\\\",\\n        \\\"--no-build\\\",\\n        \\\"--no-build-isolation\\\",\\n        \\\"--no-cache\\\",\\n        \\\"--no-config\\\",\\n        \\\"--no-env-file\\\",\\n        \\\"--no-managed-python\\\",\\n        \\\"--no-progress\\\",\\n        \\\"--no-python-downloads\\\",\\n        \\\"--no-sources\\\",\\n        \\\"--offline\\\",\\n        \\\"--quiet\\\",\\n        \\\"--refresh\\\",\\n        \\\"--reinstall\\\",\\n        \\\"--upgrade\\\",\\n        \\\"--verbose\\\",\\n        \\\"--version\\\",\\n        \\\"--yes\\\",\\n    }\\n)\\n\\nNPX_BLOCKED_SOURCE_FLAGS = frozenset(\\n    {\\n        \\\"--registry\\\",\\n        \\\"--userconfig\\\",\\n        \\\"--globalconfig\\\",\\n        \\\"--call\\\",\\n        \\\"-c\\\",\\n        \\\"--shell\\\",\\n        \\\"--script-shell\\\",\\n        \\\"--dangerously-allow-all-scripts\\\",\\n    }\\n)\\nNPX_TRUSTED_PACKAGE_FLAGS = frozenset({\\\"--package\\\", \\\"-p\\\"})\\nNPX_SAFE_BOOLEAN_FLAGS = frozenset(\\n    {\\\"-y\\\", \\\"--yes\\\", \\\"--workspaces\\\", \\\"--include-workspace-root\\\", \\\"--strict-allow-scripts\\\"}\\n)\\n\\n# Explicit ``--package`` mode decouples installation from command selection, so\\n# only package-owned executables verified by Langflow may be selected. Packages\\n# without an entry here remain usable through the safer direct ``npx PACKAGE``\\n# form, where npx derives the executable from that package's metadata.\\nNPX_SAFE_PACKAGE_ENTRYPOINTS: dict[str, frozenset[str]] = {\\n    \\\"mcp-proxy\\\": frozenset({\\\"mcp-proxy\\\"}),\\n}\\n\\n# ``uvx --from PACKAGE COMMAND`` decouples the package from the executable that\\n# uvx launches. Only known package-owned entrypoints may be selected.\\nUVX_SAFE_FROM_ENTRYPOINTS: dict[str, frozenset[str]] = {\\n    \\\"lfx\\\": frozenset({\\\"lfx-mcp\\\"}),\\n}\\n\\nDOCKER_BLOCKED_HOST_ACCESS_FLAGS = frozenset(\\n    {\\n        \\\"--privileged\\\",\\n        \\\"--cap-add\\\",\\n        \\\"-v\\\",\\n        \\\"--volume\\\",\\n        \\\"--volumes-from\\\",\\n        \\\"--mount\\\",\\n        \\\"--device\\\",\\n        \\\"--device-cgroup-rule\\\",\\n    }\\n)\\nDOCKER_CLUSTERABLE_SHORT_FLAGS = frozenset({\\\"d\\\", \\\"i\\\", \\\"P\\\", \\\"q\\\", \\\"t\\\"})\\nDOCKER_NAMESPACE_FLAGS = frozenset({\\\"--pid\\\", \\\"--ipc\\\", \\\"--uts\\\", \\\"--net\\\", \\\"--network\\\"})\\nDOCKER_DANGEROUS_SECURITY_OPT_SUBSTRINGS = (\\\"unconfined\\\", \\\"disable\\\")\\nDOCKER_HARDENED_BLOCKED_FLAGS = frozenset(\\n    {\\n        \\\"--privileged\\\",\\n        \\\"--cap-add\\\",\\n        \\\"-v\\\",\\n        \\\"--volume\\\",\\n        \\\"--volumes-from\\\",\\n        \\\"--mount\\\",\\n        \\\"--device\\\",\\n        \\\"--device-cgroup-rule\\\",\\n        \\\"--env-file\\\",\\n        \\\"--label-file\\\",\\n        \\\"--cidfile\\\",\\n        \\\"--gpus\\\",\\n        \\\"--use-api-socket\\\",\\n        \\\"--link\\\",\\n        \\\"--runtime\\\",\\n        \\\"-p\\\",\\n        \\\"-P\\\",\\n        \\\"--publish\\\",\\n        \\\"--publish-all\\\",\\n        \\\"--restart\\\",\\n    }\\n)\\nDOCKER_HARDENED_NAMESPACE_FLAGS = frozenset({\\\"--pid\\\", \\\"--ipc\\\", \\\"--uts\\\", \\\"--cgroupns\\\", \\\"--userns\\\"})\\nDOCKER_HARDENED_NETWORK_FLAGS = frozenset({\\\"--net\\\", \\\"--network\\\"})\\nDOCKER_SAFE_NETWORK_VALUES = frozenset({\\\"none\\\", \\\"bridge\\\", \\\"default\\\"})\\nSHELL_CONTROL_CHARS = frozenset({\\\";\\\", \\\"|\\\", \\\"&\\\", \\\"$\\\", \\\"`\\\", \\\"<\\\", \\\">\\\", \\\"\\\\n\\\", \\\"\\\\r\\\"})\\n\\n# cmd.exe switches that do NOT run the rest of the command line. ``/c`` is not the only\\n# executing switch: ``/k`` runs the command and keeps the session alive, and ``/r`` is an\\n# undocumented synonym of ``/c``. Boolean switches may also be clustered ahead of the\\n# executing one (``/q/k``), and a switch may carry a value (``/t:0a``).\\n#\\n# The set is inverted deliberately: anything outside it is treated as executing, so a switch\\n# this module does not know about fails safe (the wrapped payload still gets bound to the\\n# command allowlist) instead of silently skipping the wrapper check.\\nCMD_NON_EXEC_SWITCH_LETTERS = frozenset({\\\"a\\\", \\\"d\\\", \\\"e\\\", \\\"f\\\", \\\"q\\\", \\\"s\\\", \\\"t\\\", \\\"u\\\", \\\"v\\\"})\\n\\nHARDENED_ALLOWED_PYTHON_MODULES = frozenset({\\\"langflow.agentic.mcp\\\", \\\"langflow.agentic.mcp.server\\\"})\\nPYTHON_MODULE_MIN_ARGS = 2\\n\\n# Options whose following token is a value, not uvx's package/command. Source-\\n# selecting options are handled separately above. This lets a later URL remain\\n# a legitimate MCP server argument after the trusted package token.\\nUVX_VALUE_OPTIONS = frozenset(\\n    {\\n        \\\"--python-platform\\\",\\n        \\\"--torch-backend\\\",\\n        \\\"--index-strategy\\\",\\n        \\\"--keyring-provider\\\",\\n        \\\"--resolution\\\",\\n        \\\"--prerelease\\\",\\n        \\\"--fork-strategy\\\",\\n        \\\"--exclude-newer\\\",\\n        \\\"--exclude-newer-package\\\",\\n        \\\"--no-sources-package\\\",\\n        \\\"--upgrade-package\\\",\\n        \\\"-P\\\",\\n        \\\"--reinstall-package\\\",\\n        \\\"--link-mode\\\",\\n        \\\"--config-setting\\\",\\n        \\\"-C\\\",\\n        \\\"--config-settings-package\\\",\\n        \\\"--no-build-isolation-package\\\",\\n        \\\"--no-build-package\\\",\\n        \\\"--no-binary-package\\\",\\n        \\\"--cache-dir\\\",\\n        \\\"--refresh-package\\\",\\n        \\\"--python\\\",\\n        \\\"-p\\\",\\n        \\\"--color\\\",\\n        \\\"--allow-insecure-host\\\",\\n    }\\n)\\nNPX_VALUE_OPTIONS = frozenset({\\\"--workspace\\\", \\\"-w\\\", \\\"--allow-scripts\\\"})\\n\\n_PYTHON_INDEX_REQUIREMENT = re.compile(\\n    r\\\"^[A-Za-z0-9][A-Za-z0-9._-]*\\\"\\n    r\\\"(?:\\\\[[A-Za-z0-9._,-]+\\\\])?\\\"\\n    r\\\"(?:(?:===|==|~=|!=|<=|>=|<|>)[A-Za-z0-9*_.+!-]+\\\"\\n    r\\\"(?:,(?:===|==|~=|!=|<=|>=|<|>)[A-Za-z0-9*_.+!-]+)*)?$\\\"\\n)\\n_NPM_INDEX_PACKAGE = re.compile(\\n    r\\\"^(?:@[A-Za-z0-9][A-Za-z0-9._-]*/)?\\\"\\n    r\\\"[A-Za-z0-9][A-Za-z0-9._-]*\\\"\\n    r\\\"(?:@[A-Za-z0-9][A-Za-z0-9._+~^<>=*-]*)?$\\\"\\n)\\n_LOCAL_ARCHIVE_SUFFIXES = (\\\".whl\\\", \\\".zip\\\", \\\".tar.gz\\\", \\\".tar.bz2\\\", \\\".tgz\\\")\\n\\n\\ndef is_package_manager_config_env_var(key: str) -> bool:\\n    \\\"\\\"\\\"Return whether *key* can reconfigure an approved package launcher.\\\"\\\"\\\"\\n    return key.lower().startswith(PACKAGE_MANAGER_CONFIG_ENV_PREFIXES)\\n\\n\\ndef _setting(name: str, *, default):\\n    \\\"\\\"\\\"Read an MCP/security setting lazily without making this module import-heavy.\\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        return getattr(get_settings_service().settings, name, default)\\n    except Exception:  # noqa: BLE001 - settings can be unavailable during early imports\\n        return default\\n\\n\\ndef _configured_allowed_packages() -> frozenset[str] | None:\\n    configured = _setting(\\\"mcp_server_allowed_packages\\\", default=None)\\n    if not isinstance(configured, str):\\n        return None\\n    return frozenset(_normalize_package_name(item) for item in configured.split(\\\",\\\") if item.strip())\\n\\n\\ndef _normalize_package_name(package_spec: str) -> str:\\n    package = package_spec.strip().lower()\\n    if package.startswith(\\\"@\\\"):\\n        slash_index = package.find(\\\"/\\\")\\n        version_index = package.rfind(\\\"@\\\")\\n        if slash_index >= 0 and version_index > slash_index:\\n            package = package[:version_index]\\n    else:\\n        package = package.split(\\\"@\\\", 1)[0]\\n\\n    for separator in (\\\"==\\\", \\\"~=\\\", \\\">=\\\", \\\"<=\\\", \\\"!=\\\", \\\">\\\", \\\"<\\\", \\\"[\\\"):\\n        package = package.split(separator, 1)[0]\\n    return package.strip()\\n\\n\\ndef _base_command(command: str) -> str:\\n    normalized = command.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n    base = Path(normalized).name.lower()\\n    return base.removesuffix(\\\".exe\\\")\\n\\n\\ndef _looks_like_file_path(command: str) -> bool:\\n    return (\\n        command.startswith((\\\"/\\\", \\\"./\\\", \\\"../\\\"))\\n        or \\\"\\\\\\\\\\\" in command\\n        or (len(command) >= WINDOWS_DRIVE_PREFIX_LENGTH and command[1:3] in {\\\":\\\\\\\\\\\", \\\":/\\\"})\\n    )\\n\\n\\ndef split_mcp_stdio_command(command: str, args: list[str] | None) -> tuple[str, list[str]]:\\n    \\\"\\\"\\\"Normalize a legacy packed command into an executable and argv list.\\\"\\\"\\\"\\n    combined_args = list(args or [])\\n    executable = command\\n    if command and not _looks_like_file_path(command):\\n        try:\\n            command_parts = shlex.split(command)\\n        except ValueError as exc:\\n            msg = \\\"MCP stdio command is not allowed because it cannot be parsed safely\\\"\\n            raise ValueError(msg) from exc\\n        if command_parts:\\n            executable = command_parts[0]\\n            combined_args = command_parts[1:] + combined_args\\n    return executable, combined_args\\n\\n\\ndef _split_command(command: str, args: list[str] | None) -> tuple[str, list[str]]:\\n    executable, combined_args = split_mcp_stdio_command(command, args)\\n    return _base_command(executable), combined_args\\n\\n\\ndef _raise_disallowed(command: str, value: str) -> None:\\n    msg = f\\\"Argument '{value}' is not allowed for MCP stdio command '{command}'\\\"\\n    raise ValueError(msg)\\n\\n\\ndef _option_value(args: list[str], index: int, command: str) -> tuple[str, int]:\\n    _, separator, inline_value = args[index].partition(\\\"=\\\")\\n    if separator:\\n        if not inline_value:\\n            _raise_disallowed(command, args[index])\\n        return inline_value, index + 1\\n    if index + 1 >= len(args):\\n        _raise_disallowed(command, args[index])\\n    return args[index + 1], index + 2\\n\\n\\ndef _validate_python_index_requirement(value: str, command: str) -> None:\\n    if value.lower().endswith(_LOCAL_ARCHIVE_SUFFIXES) or not _PYTHON_INDEX_REQUIREMENT.fullmatch(value):\\n        _raise_disallowed(command, value)\\n\\n\\ndef _validate_npm_index_package(value: str, command: str) -> None:\\n    if value.lower().endswith(_LOCAL_ARCHIVE_SUFFIXES) or not _NPM_INDEX_PACKAGE.fullmatch(value):\\n        _raise_disallowed(command, value)\\n\\n\\ndef _matches_short_option(arg: str, options: frozenset[str]) -> bool:\\n    return not arg.startswith(\\\"--\\\") and any(arg.startswith(option) for option in options)\\n\\n\\ndef _is_uvx_safe_boolean_flag(arg: str) -> bool:\\n    \\\"\\\"\\\"Accept known uvx booleans, including clap-compatible short clusters.\\\"\\\"\\\"\\n    return arg in UVX_SAFE_BOOLEAN_FLAGS or (\\n        arg.startswith(\\\"-\\\")\\n        and not arg.startswith(\\\"--\\\")\\n        and len(arg) > 1\\n        and set(arg[1:]) <= UVX_CLUSTERABLE_BOOLEAN_SHORT_FLAGS\\n    )\\n\\n\\ndef _uvx_package_selection(args: list[str]) -> tuple[list[str], list[str], str | None]:\\n    \\\"\\\"\\\"Return all --from/--with packages and the selected uvx command.\\\"\\\"\\\"\\n    from_packages: list[str] = []\\n    with_packages: list[str] = []\\n    command: str | None = None\\n    index = 0\\n    while index < len(args):\\n        arg = args[index]\\n        if arg == \\\"--\\\":\\n            if index + 1 < len(args):\\n                command = args[index + 1]\\n            break\\n\\n        flag = arg.split(\\\"=\\\", 1)[0]\\n        if flag in UVX_BLOCKED_SOURCE_FLAGS or _matches_short_option(arg, UVX_BLOCKED_SHORT_SOURCE_FLAGS):\\n            _raise_disallowed(\\\"uvx\\\", arg)\\n\\n        if arg.startswith(\\\"-w\\\") and not arg.startswith(\\\"--\\\") and arg != \\\"-w\\\":\\n            package = arg[2:].removeprefix(\\\"=\\\")\\n            if not package:\\n                _raise_disallowed(\\\"uvx\\\", arg)\\n            with_packages.append(package)\\n            index += 1\\n            continue\\n        if flag in UVX_TRUSTED_PACKAGE_FLAGS:\\n            package, index = _option_value(args, index, \\\"uvx\\\")\\n            if flag == \\\"--from\\\":\\n                from_packages.append(package)\\n            else:\\n                with_packages.append(package)\\n            continue\\n        if flag in UVX_VALUE_OPTIONS:\\n            _, index = _option_value(args, index, \\\"uvx\\\")\\n            continue\\n        attached_value_flag = next(\\n            (option for option in UVX_ATTACHED_VALUE_SHORT_FLAGS if arg.startswith(option) and arg != option), None\\n        )\\n        if attached_value_flag is not None:\\n            if not arg[len(attached_value_flag) :].removeprefix(\\\"=\\\"):\\n                _raise_disallowed(\\\"uvx\\\", arg)\\n            index += 1\\n            continue\\n        if _is_uvx_safe_boolean_flag(arg):\\n            index += 1\\n            continue\\n        if arg.startswith(\\\"-\\\"):\\n            # Fail closed: uvx can add value-taking options without exposing\\n            # them in concise help. Skipping an unknown flag could mistake its\\n            # value for the package while uvx executes the following operand.\\n            _raise_disallowed(\\\"uvx\\\", arg)\\n        command = arg\\n        break\\n    return from_packages, with_packages, command\\n\\n\\ndef _is_uvx_with_option(arg: str) -> bool:\\n    \\\"\\\"\\\"Match every spelling uvx accepts for ``--with``: split, inline, and clustered short.\\\"\\\"\\\"\\n    if arg in {\\\"--with\\\", \\\"-w\\\"}:\\n        return True\\n    return arg.startswith(\\\"--with=\\\") or (arg.startswith(\\\"-w\\\") and not arg.startswith(\\\"--\\\"))\\n\\n\\ndef _package_runner_target(base_command: str, args: list[str]) -> tuple[str | None, str | None]:\\n    \\\"\\\"\\\"Extract the installed package and an explicit uvx entrypoint.\\\"\\\"\\\"\\n    index = 0\\n    while index < len(args):\\n        arg = args[index]\\n        if arg in {\\\"-y\\\", \\\"--yes\\\"}:\\n            index += 1\\n            continue\\n        if base_command == \\\"uvx\\\" and (arg == \\\"--from\\\" or arg.startswith(\\\"--from=\\\")):\\n            if arg == \\\"--from\\\":\\n                if index + 2 >= len(args):\\n                    _raise_disallowed(base_command, arg)\\n                package = args[index + 1]\\n                entrypoint = args[index + 2]\\n            else:\\n                package = arg.split(\\\"=\\\", 1)[1]\\n                if not package or index + 1 >= len(args):\\n                    _raise_disallowed(base_command, arg)\\n                entrypoint = args[index + 1]\\n            if entrypoint.startswith(\\\"-\\\"):\\n                _raise_disallowed(base_command, entrypoint)\\n            return package, entrypoint\\n        if base_command == \\\"npx\\\" and (arg == \\\"--package\\\" or arg.startswith(\\\"--package=\\\")):\\n            package, _ = _option_value(args, index, base_command)\\n            return package, None\\n        if base_command == \\\"uvx\\\" and _is_uvx_with_option(arg):\\n            # ``--with`` adds a requirement to the ephemeral environment; it never selects the\\n            # executable. Skipping its value keeps the operand after it as the runner target\\n            # instead of misreading the extra requirement as the package being launched.\\n            index += 2 if arg in {\\\"--with\\\", \\\"-w\\\"} else 1\\n            continue\\n        if arg.startswith(\\\"-\\\"):\\n            index += 2 if arg in UVX_VALUE_OPTIONS | NPX_VALUE_OPTIONS and \\\"=\\\" not in arg else 1\\n            continue\\n        return arg, None\\n    return None, None\\n\\n\\ndef _npx_package_selection(args: list[str]) -> tuple[list[str], str | None]:\\n    \\\"\\\"\\\"Return every explicit npx package and the command selected from them.\\\"\\\"\\\"\\n    packages: list[str] = []\\n    entrypoint: str | None = None\\n    index = 0\\n    while index < len(args):\\n        arg = args[index]\\n        if arg == \\\"--\\\":\\n            if entrypoint is None and index + 1 < len(args):\\n                entrypoint = args[index + 1]\\n            break\\n\\n        flag = arg.split(\\\"=\\\", 1)[0]\\n        if flag in NPX_TRUSTED_PACKAGE_FLAGS:\\n            package, index = _option_value(args, index, \\\"npx\\\")\\n            packages.append(package)\\n            continue\\n        if flag in NPX_VALUE_OPTIONS:\\n            _, index = _option_value(args, index, \\\"npx\\\")\\n            continue\\n        if flag in NPX_SAFE_BOOLEAN_FLAGS:\\n            index += 1\\n            continue\\n        if arg.startswith(\\\"-\\\"):\\n            _raise_disallowed(\\\"npx\\\", arg)\\n        entrypoint = arg\\n        break\\n    return packages, entrypoint\\n\\n\\ndef _validate_npx_package_selection(args: list[str], allowed_packages: frozenset[str]) -> bool:\\n    \\\"\\\"\\\"Validate all explicit packages and their selected npx executable.\\\"\\\"\\\"\\n    packages, entrypoint = _npx_package_selection(args)\\n    if not packages:\\n        return False\\n\\n    normalized_packages: list[str] = []\\n    for package in packages:\\n        normalized_package = _normalize_package_name(package)\\n        if not normalized_package or normalized_package not in allowed_packages:\\n            allowed = \\\", \\\".join(sorted(allowed_packages)) or \\\"<none>\\\"\\n            msg = f\\\"Package '{package or '<missing>'}' is not allowed for MCP npx. Server-approved packages: {allowed}\\\"\\n            raise ValueError(msg)\\n        normalized_packages.append(normalized_package)\\n\\n    # An explicit --package decouples installation from command selection. Keep\\n    # the command tied to one of those packages instead of letting npx launch an\\n    # arbitrary executable already present on PATH.\\n    unverified_packages = [package for package in normalized_packages if package not in NPX_SAFE_PACKAGE_ENTRYPOINTS]\\n    if unverified_packages:\\n        msg = (\\n            f\\\"Package '{unverified_packages[0]}' has no verified entrypoint for explicit MCP npx package selection; \\\"\\n            \\\"use the direct npx package form\\\"\\n        )\\n        raise ValueError(msg)\\n    allowed_entrypoints = set().union(\\n        *(NPX_SAFE_PACKAGE_ENTRYPOINTS.get(package, frozenset()) for package in normalized_packages)\\n    )\\n    if entrypoint not in allowed_entrypoints:\\n        allowed = \\\", \\\".join(sorted(allowed_entrypoints)) or \\\"<none>\\\"\\n        msg = (\\n            f\\\"Entrypoint '{entrypoint or '<missing>'}' is not allowed for MCP npx packages \\\"\\n            f\\\"'{', '.join(normalized_packages)}'. Allowed entrypoints: {allowed}\\\"\\n        )\\n        raise ValueError(msg)\\n    return True\\n\\n\\ndef _sdk_constraint_exemption() -> str | None:\\n    \\\"\\\"\\\"Return the requirement Langflow itself injects as ``uvx --with``, if enabled.\\n\\n    Langflow prepends ``--with <mcp_sdk_constraint>`` to every MCP server it launches\\n    through uvx. Exempting that exact specifier keeps operator package allowlists\\n    working without every deployment adding ``mcp``; any other ``--with`` requirement\\n    is still validated against the allowlist.\\n    \\\"\\\"\\\"\\n    from lfx.base.mcp.uvx import DEFAULT_MCP_SDK_CONSTRAINT\\n\\n    value = _setting(\\\"mcp_sdk_constraint\\\", default=DEFAULT_MCP_SDK_CONSTRAINT)\\n    if isinstance(value, str) and value.strip():\\n        return value.strip()\\n    return None\\n\\n\\ndef _validate_allowed_package(base_command: str, args: list[str], allowed_packages: frozenset[str] | None) -> None:\\n    if allowed_packages is None or base_command not in {\\\"npx\\\", \\\"uvx\\\"}:\\n        return\\n\\n    if base_command == \\\"uvx\\\":\\n        from_packages, with_packages, command = _uvx_package_selection(args)\\n        exemption = _sdk_constraint_exemption()\\n        with_packages = [package for package in with_packages if package != exemption]\\n        selected_packages = [*from_packages, *with_packages]\\n        if not from_packages:\\n            selected_packages.append(command or \\\"<missing>\\\")\\n\\n        for package in selected_packages:\\n            normalized_package = _normalize_package_name(package)\\n            if not normalized_package or normalized_package not in allowed_packages:\\n                allowed = \\\", \\\".join(sorted(allowed_packages)) or \\\"<none>\\\"\\n                msg = f\\\"Package '{package}' is not allowed for MCP uvx. Server-approved packages: {allowed}\\\"\\n                raise ValueError(msg)\\n\\n        if from_packages:\\n            if len(from_packages) != 1:\\n                msg = \\\"Multiple --from packages are not allowed for MCP uvx\\\"\\n                raise ValueError(msg)\\n            primary_package = _normalize_package_name(from_packages[0])\\n            allowed_entrypoints = UVX_SAFE_FROM_ENTRYPOINTS.get(primary_package, frozenset({primary_package}))\\n            if command not in allowed_entrypoints:\\n                msg = (\\n                    f\\\"Entrypoint '{command or '<missing>'}' is not allowed for MCP uvx package '{primary_package}'. \\\"\\n                    f\\\"Allowed entrypoints: {', '.join(sorted(allowed_entrypoints))}\\\"\\n                )\\n                raise ValueError(msg)\\n        return\\n\\n    if base_command == \\\"npx\\\" and _validate_npx_package_selection(args, allowed_packages):\\n        return\\n\\n    target, entrypoint = _package_runner_target(base_command, args)\\n    normalized_target = _normalize_package_name(target or \\\"\\\")\\n    if not normalized_target or normalized_target not in allowed_packages:\\n        allowed = \\\", \\\".join(sorted(allowed_packages)) or \\\"<none>\\\"\\n        msg = (\\n            f\\\"Package '{target or '<missing>'}' is not allowed for MCP {base_command}. \\\"\\n            f\\\"Server-approved packages: {allowed}\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    if base_command == \\\"uvx\\\" and entrypoint is not None:\\n        allowed_entrypoints = UVX_SAFE_FROM_ENTRYPOINTS.get(normalized_target, frozenset({normalized_target}))\\n        if entrypoint not in allowed_entrypoints:\\n            msg = (\\n                f\\\"Entrypoint '{entrypoint}' is not allowed for MCP uvx package '{normalized_target}'. \\\"\\n                f\\\"Allowed entrypoints: {', '.join(sorted(allowed_entrypoints))}\\\"\\n            )\\n            raise ValueError(msg)\\n\\n\\ndef _validate_interpreter_invocation(base_command: str, args: list[str], *, hardened: bool) -> None:\\n    if not hardened:\\n        return\\n    if base_command in {\\\"sh\\\", \\\"bash\\\", \\\"cmd\\\"}:\\n        first_arg = args[0].lower() if args else \\\"\\\"\\n        has_leading_exec_flag = (\\n            has_leading_cmd_exec_flag(args)\\n            if base_command == \\\"cmd\\\"\\n            else first_arg.startswith(\\\"-\\\") and not first_arg.startswith(\\\"--\\\") and \\\"c\\\" in first_arg[1:]\\n        )\\n        if has_leading_exec_flag and parse_mcp_shell_wrapper(base_command, args) is not None:\\n            return\\n        msg = f\\\"Direct shell scripts are not allowed for MCP command '{base_command}'\\\"\\n        raise ValueError(msg)\\n    if base_command not in {\\\"node\\\", \\\"python\\\", \\\"python3\\\"}:\\n        return\\n    if (\\n        base_command in {\\\"python\\\", \\\"python3\\\"}\\n        and len(args) >= PYTHON_MODULE_MIN_ARGS\\n        and args[0] == \\\"-m\\\"\\n        and args[1] in HARDENED_ALLOWED_PYTHON_MODULES\\n    ):\\n        return\\n    msg = f\\\"Interpreter command '{base_command}' is not allowed by MCP interpreter hardening\\\"\\n    raise ValueError(msg)\\n\\n\\ndef _validate_uvx_args(args: list[str]) -> None:\\n    from_packages, with_packages, command = _uvx_package_selection(args)\\n    for package in [*from_packages, *with_packages]:\\n        _validate_python_index_requirement(package, \\\"uvx\\\")\\n    if not from_packages and command is not None:\\n        _validate_python_index_requirement(command, \\\"uvx\\\")\\n\\n\\ndef _validate_npx_args(args: list[str]) -> None:\\n    has_package_option = False\\n    index = 0\\n    while index < len(args):\\n        arg = args[index]\\n        if arg == \\\"--\\\":\\n            if not has_package_option and index + 1 < len(args):\\n                _validate_npm_index_package(args[index + 1], \\\"npx\\\")\\n            return\\n        flag = arg.split(\\\"=\\\", 1)[0]\\n        if flag in NPX_BLOCKED_SOURCE_FLAGS:\\n            _raise_disallowed(\\\"npx\\\", arg)\\n        if flag in NPX_TRUSTED_PACKAGE_FLAGS:\\n            value, next_index = _option_value(args, index, \\\"npx\\\")\\n            _validate_npm_index_package(value, \\\"npx\\\")\\n            has_package_option = True\\n            index = next_index\\n            continue\\n        if flag in NPX_VALUE_OPTIONS:\\n            _, index = _option_value(args, index, \\\"npx\\\")\\n            continue\\n        if flag in NPX_SAFE_BOOLEAN_FLAGS:\\n            index += 1\\n            continue\\n        if arg.startswith(\\\"-\\\"):\\n            _raise_disallowed(\\\"npx\\\", arg)\\n        if not has_package_option:\\n            _validate_npm_index_package(arg, \\\"npx\\\")\\n        return\\n\\n\\ndef _is_clustered_short_flag(flag: str, target: str, allowed_prefixes: frozenset[str]) -> bool:\\n    if not flag.startswith(\\\"-\\\") or flag.startswith(\\\"--\\\"):\\n        return False\\n    cluster = flag[1:].split(\\\"=\\\", 1)[0]\\n    index = cluster.find(target)\\n    return index >= 0 and all(short_flag in allowed_prefixes for short_flag in cluster[:index])\\n\\n\\ndef _validate_docker_args(args: list[str], *, hardened: bool) -> None:\\n    # Docker is allowlisted only as an isolated MCP server launcher. Other\\n    # subcommands operate on the shared daemon and bypass the run-argument policy.\\n    if not args or args[0].lower() != \\\"run\\\":\\n        _raise_disallowed(\\\"docker\\\", args[0] if args else \\\"<missing run subcommand>\\\")\\n\\n    for index, arg in enumerate(args):\\n        flag = arg.split(\\\"=\\\", 1)[0]\\n        has_volume_short_flag = _is_clustered_short_flag(flag, \\\"v\\\", DOCKER_CLUSTERABLE_SHORT_FLAGS)\\n        if flag in DOCKER_BLOCKED_HOST_ACCESS_FLAGS or has_volume_short_flag:\\n            _raise_disallowed(\\\"docker\\\", arg)\\n        if flag in DOCKER_NAMESPACE_FLAGS:\\n            value, _ = _option_value(args, index, \\\"docker\\\")\\n            value = value.lower()\\n            if value == \\\"host\\\" or value.startswith(\\\"container:\\\"):\\n                _raise_disallowed(\\\"docker\\\", arg)\\n        if flag == \\\"--security-opt\\\":\\n            value, _ = _option_value(args, index, \\\"docker\\\")\\n            if any(part in value.lower() for part in DOCKER_DANGEROUS_SECURITY_OPT_SUBSTRINGS):\\n                _raise_disallowed(\\\"docker\\\", arg)\\n\\n        if not hardened:\\n            continue\\n        if flag in DOCKER_HARDENED_BLOCKED_FLAGS or any(\\n            _is_clustered_short_flag(flag, publish_flag, frozenset({\\\"d\\\", \\\"i\\\", \\\"t\\\"})) for publish_flag in (\\\"p\\\", \\\"P\\\")\\n        ):\\n            _raise_disallowed(\\\"docker\\\", arg)\\n        if flag in DOCKER_HARDENED_NAMESPACE_FLAGS:\\n            value, _ = _option_value(args, index, \\\"docker\\\")\\n            if value.lower() == \\\"host\\\" or value.lower().startswith(\\\"container:\\\"):\\n                _raise_disallowed(\\\"docker\\\", arg)\\n        if flag in DOCKER_HARDENED_NETWORK_FLAGS:\\n            value, _ = _option_value(args, index, \\\"docker\\\")\\n            if value.lower() not in DOCKER_SAFE_NETWORK_VALUES:\\n                _raise_disallowed(\\\"docker\\\", arg)\\n\\n\\ndef _parse_shell_payload(command: str, payload: str) -> tuple[str, list[str]]:\\n    if any(char in payload for char in SHELL_CONTROL_CHARS):\\n        _raise_disallowed(command, payload)\\n    try:\\n        parts = shlex.split(payload)\\n    except ValueError as exc:\\n        msg = f\\\"Shell wrapper '{command}' payload cannot be parsed safely\\\"\\n        raise ValueError(msg) from exc\\n    if not parts:\\n        _raise_disallowed(command, payload)\\n    return parts[0], parts[1:]\\n\\n\\ndef is_cmd_exec_flag(arg: str) -> bool:\\n    \\\"\\\"\\\"Return whether a cmd.exe switch token makes cmd execute the rest of its argv.\\\"\\\"\\\"\\n    arg_lower = arg.lower()\\n    if not arg_lower.startswith(\\\"/\\\"):\\n        return False\\n    # ``/q/k`` packs several switches into one token and a switch may carry a value\\n    # (``/t:0a``), so only the leading letter of each part identifies the switch.\\n    return any(part[:1] not in CMD_NON_EXEC_SWITCH_LETTERS for part in arg_lower.split(\\\"/\\\") if part)\\n\\n\\ndef has_leading_cmd_exec_flag(args: list[str]) -> bool:\\n    \\\"\\\"\\\"Whether a cmd.exe execution switch precedes every operand.\\n\\n    cmd.exe accepts benign switches ahead of the execution switch (``/d /c uvx ...``),\\n    and a switch may carry a value (``/t:0a``). Those are skipped. Scanning stops at the\\n    first token that is not a switch, so a script operand can never precede the execution\\n    switch and be mistaken for a validated wrapper -- ``parse_mcp_shell_wrapper`` alone is\\n    not sufficient here because it skips non-switch tokens while searching.\\n    \\\"\\\"\\\"\\n    for arg in args:\\n        arg_lower = arg.lower()\\n        if not arg_lower.startswith(\\\"/\\\"):\\n            return False\\n        if is_cmd_exec_flag(arg_lower):\\n            return True\\n    return False\\n\\n\\ndef parse_mcp_shell_wrapper(command: str, args: list[str]) -> tuple[str, list[str]] | None:\\n    \\\"\\\"\\\"Return a shell wrapper's canonical executable and argv payload.\\\"\\\"\\\"\\n    command = _base_command(command)\\n    for index, arg in enumerate(args):\\n        arg_lower = arg.lower()\\n        if command == \\\"cmd\\\":\\n            if not is_cmd_exec_flag(arg_lower) or index + 1 >= len(args):\\n                continue\\n            payload = args[index + 1 :]\\n            if any(char in \\\" \\\".join(payload) for char in SHELL_CONTROL_CHARS):\\n                _raise_disallowed(command, \\\" \\\".join(payload))\\n            return split_mcp_stdio_command(payload[0], payload[1:])\\n\\n        is_exec_flag = arg_lower.startswith(\\\"-\\\") and not arg_lower.startswith(\\\"--\\\") and \\\"c\\\" in arg_lower[1:]\\n        if not is_exec_flag:\\n            continue\\n\\n        # bash/sh accept the command attached to -c or as the next token. Any\\n        # later tokens become $0/$1 rather than additional command arguments.\\n        option_cluster = arg[1:]\\n        attached_command = option_cluster[option_cluster.lower().index(\\\"c\\\") + 1 :]\\n        if attached_command:\\n            return _parse_shell_payload(command, attached_command)\\n        if index + 1 < len(args):\\n            return _parse_shell_payload(command, args[index + 1])\\n    return None\\n\\n\\ndef validate_mcp_stdio_source_policy(\\n    command: str | None,\\n    args: list[str] | None,\\n    *,\\n    allowed_packages: frozenset[str] | None = None,\\n    docker_hardening: bool | None = None,\\n    interpreter_hardening: bool | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Reject package-source redirection and Docker host access.\\n\\n    ``uvx --from`` and package-addition flags remain available only for plain\\n    package requirements resolved through the default trusted index. Direct\\n    URL, VCS, and filesystem requirements do not match that grammar.\\n    \\\"\\\"\\\"\\n    if not command:\\n        return\\n    base_command, combined_args = _split_command(command, args)\\n    configured_packages = _configured_allowed_packages() if allowed_packages is None else allowed_packages\\n    use_docker_hardening = (\\n        bool(_setting(\\\"mcp_server_docker_hardening\\\", default=False)) if docker_hardening is None else docker_hardening\\n    )\\n    use_interpreter_hardening = (\\n        bool(_setting(\\\"mcp_server_interpreter_hardening\\\", default=False))\\n        if interpreter_hardening is None\\n        else interpreter_hardening\\n    )\\n\\n    _validate_interpreter_invocation(base_command, combined_args, hardened=use_interpreter_hardening)\\n    if base_command == \\\"uvx\\\":\\n        _validate_uvx_args(combined_args)\\n    elif base_command == \\\"npx\\\":\\n        _validate_npx_args(combined_args)\\n    elif base_command == \\\"docker\\\":\\n        _validate_docker_args(combined_args, hardened=use_docker_hardening)\\n\\n    _validate_allowed_package(base_command, combined_args, configured_packages)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/util.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ccb8fbe0fb651978be42d18c00f6614532be1fca7a151ea5ca8680bd34c5b9e1\",\"content\":\"import asyncio\\nimport builtins\\nimport contextlib\\nimport inspect\\nimport json\\nimport os\\nimport re\\nimport shlex\\nimport shutil\\nimport unicodedata\\nfrom collections.abc import AsyncIterator, Awaitable, Callable\\nfrom pathlib import Path\\nfrom types import UnionType\\nfrom typing import Annotated, Any, TypedDict, Union, get_args, get_origin\\nfrom urllib.parse import urlparse\\nfrom uuid import UUID\\n\\nimport httpx\\nfrom anyio import ClosedResourceError\\nfrom httpx import codes as httpx_codes\\nfrom langchain_core.runnables import RunnableConfig\\nfrom langchain_core.tools import ArgsSchema, StructuredTool\\nfrom mcp import ClientSession\\nfrom mcp.shared.exceptions import McpError\\nfrom pydantic import BaseModel, SkipValidation\\n\\nfrom lfx.base.agents.utils import maybe_unflatten_dict\\nfrom lfx.base.mcp import security as mcp_security\\nfrom lfx.base.mcp.security import (\\n    AGENTIC_MCP_MODULE,\\n    AGENTIC_USER_ID_ENV_VAR,\\n    validate_mcp_stdio_config,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import outbound_call_span\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.json_schema import create_input_schema_from_json_schema\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\nfrom lfx.utils.url_redaction import redact_urls_in_text, sanitize_url_for_display\\n\\nMCP_TOOL_SPAN_NAME = \\\"mcp.tool.call\\\"\\nHTTP_ERROR_STATUS_CODE = httpx_codes.BAD_REQUEST  # HTTP status code for client errors\\n\\n# HTTP status codes used in validation\\nHTTP_NOT_FOUND = 404\\nHTTP_METHOD_NOT_ALLOWED = 405\\nHTTP_NOT_ACCEPTABLE = 406\\nHTTP_BAD_REQUEST = 400\\nHTTP_TOO_MANY_REQUESTS = 429\\nHTTP_INTERNAL_SERVER_ERROR = 500\\nHTTP_UNAUTHORIZED = 401\\nHTTP_FORBIDDEN = 403\\n\\n# Backward-compatible exports; the canonical policy lives in lfx.base.mcp.security.\\nDANGEROUS_MCP_ENV_VARS = mcp_security.DANGEROUS_MCP_ENV_VARS\\nis_dangerous_mcp_env_var = mcp_security.is_dangerous_mcp_env_var\\n\\n# Minimum cleanup interval to prevent tight-loop CPU spin if settings return 0 or fail.\\n_MCP_CLEANUP_INTERVAL_MIN = 30  # seconds\\n_SESSION_VALIDATION_TIMEOUT_FLOOR = 10.0\\n# Mirrors the McpSettings.mcp_server_timeout default. Only used when the settings object lacks\\n# the field or carries a non-positive value, so a misconfiguration cannot resurrect a shorter cap.\\n_SESSION_INIT_TIMEOUT_FALLBACK = 60.0\\n\\n\\ndef _validate_mcp_stdio_env(env: dict[str, str] | None) -> dict[str, str]:\\n    \\\"\\\"\\\"Backward-compatible env-only wrapper around the shared stdio policy.\\\"\\\"\\\"\\n    validate_mcp_stdio_config(None, None, env)\\n    return env or {}\\n\\n\\ndef _get_mcp_setting(key: str, default: Any = None) -> Any:\\n    \\\"\\\"\\\"Read MCP settings from settings service (no cache \u2014 settings may change).\\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    return getattr(settings, key, default)\\n\\n\\ndef _resolve_mcp_tool_execution_timeout(tool_execution_timeout: float | None) -> float:\\n    \\\"\\\"\\\"Resolve MCP tool execution timeout from explicit input or MCP settings.\\n\\n    Priority for picking the timeout:\\n    1. `tool_execution_timeout`: Custom UI override directly on the component (Highest).\\n    2. Global Settings: The maximum value between `mcp_tool_execution_timeout`\\n       and `mcp_server_timeout` from global settings.\\n    3. Fallback: 180.0 seconds if no custom or global settings exist (Lowest).\\n\\n    Negative values are treated as unset (use system default) because\\n    ``asyncio.wait_for`` immediately raises ``TimeoutError`` for any timeout < 0.\\n    \\\"\\\"\\\"\\n    if tool_execution_timeout is not None and float(tool_execution_timeout) > 0:\\n        return float(tool_execution_timeout)\\n\\n    configured = _get_mcp_setting(\\\"mcp_tool_execution_timeout\\\", None)\\n    mcp_server_timeout = _get_mcp_setting(\\\"mcp_server_timeout\\\", None)\\n\\n    configured_timeouts = [float(value) for value in (configured, mcp_server_timeout) if value is not None]\\n    return max(configured_timeouts) if configured_timeouts else 180.0\\n\\n\\ndef get_session_validation_timeout() -> float:\\n    \\\"\\\"\\\"Derive a fast session health-check timeout from the configured connection budget.\\\"\\\"\\\"\\n    connect_timeout = _get_mcp_setting(\\\"mcp_server_timeout\\\", None)\\n    if connect_timeout is None:\\n        return _SESSION_VALIDATION_TIMEOUT_FLOOR\\n    return max(_SESSION_VALIDATION_TIMEOUT_FLOOR, float(connect_timeout) / 3.0)\\n\\n\\ndef get_session_init_timeout() -> float:\\n    \\\"\\\"\\\"Budget for a new transport session to finish ``initialize``.\\n\\n    Derived from ``mcp_server_timeout`` so the inner readiness wait in the session\\n    creators and the outer ``connect_to_server`` budget are the same number. This used\\n    to be a hardcoded 30 s, which silently capped ``LANGFLOW_MCP_SERVER_TIMEOUT`` at 30\\n    and, on the ``run_tool`` path (no outer connect budget), was the real connect limit.\\n\\n    Non-positive values are treated as unset, like ``_resolve_mcp_tool_execution_timeout``,\\n    because ``asyncio.wait_for`` fails immediately for any timeout <= 0.\\n    \\\"\\\"\\\"\\n    connect_timeout = _get_mcp_setting(\\\"mcp_server_timeout\\\", None)\\n    if connect_timeout is None or float(connect_timeout) <= 0:\\n        return _SESSION_INIT_TIMEOUT_FALLBACK\\n    return float(connect_timeout)\\n\\n\\ndef get_max_sessions_per_server() -> int:\\n    \\\"\\\"\\\"Get maximum number of sessions per server to prevent resource exhaustion.\\\"\\\"\\\"\\n    return _get_mcp_setting(\\\"mcp_max_sessions_per_server\\\")\\n\\n\\ndef get_session_idle_timeout() -> int:\\n    \\\"\\\"\\\"Get 5 minutes idle timeout for sessions.\\\"\\\"\\\"\\n    return _get_mcp_setting(\\\"mcp_session_idle_timeout\\\")\\n\\n\\ndef get_session_cleanup_interval() -> int:\\n    \\\"\\\"\\\"Get cleanup interval in seconds, clamped to a safe minimum.\\n\\n    Guard: if settings return 0, None, or a negative value the _periodic_cleanup\\n    loop would call asyncio.sleep(0) on every iteration, spinning at 100% CPU.\\n    \\\"\\\"\\\"\\n    interval = _get_mcp_setting(\\\"mcp_session_cleanup_interval\\\")\\n    if not interval or interval < _MCP_CLEANUP_INTERVAL_MIN:\\n        return _MCP_CLEANUP_INTERVAL_MIN\\n    return interval\\n\\n\\n# RFC 7230 compliant header name pattern: token = 1*tchar\\n# tchar = \\\"!\\\" / \\\"#\\\" / \\\"$\\\" / \\\"%\\\" / \\\"&\\\" / \\\"'\\\" / \\\"*\\\" / \\\"+\\\" / \\\"-\\\" / \\\".\\\" /\\n#         \\\"^\\\" / \\\"_\\\" / \\\"`\\\" / \\\"|\\\" / \\\"~\\\" / DIGIT / ALPHA\\nHEADER_NAME_PATTERN = re.compile(r\\\"^[!#$%&\\\\'*+\\\\-.0-9A-Z^_`a-z|~]+$\\\")\\n\\n# Common allowed headers for MCP connections\\nALLOWED_HEADERS = {\\n    \\\"authorization\\\",\\n    \\\"accept\\\",\\n    \\\"accept-encoding\\\",\\n    \\\"accept-language\\\",\\n    \\\"cache-control\\\",\\n    \\\"content-type\\\",\\n    \\\"user-agent\\\",\\n    \\\"x-api-key\\\",\\n    \\\"x-auth-token\\\",\\n    \\\"x-custom-header\\\",\\n    \\\"x-langflow-session\\\",\\n    \\\"x-mcp-client\\\",\\n    \\\"x-requested-with\\\",\\n}\\n\\n\\ndef create_mcp_http_client_with_ssl_option(\\n    headers: dict[str, str] | None = None,\\n    timeout: httpx.Timeout | None = None,\\n    auth: httpx.Auth | None = None,\\n    *,\\n    verify_ssl: bool = True,\\n) -> httpx.AsyncClient:\\n    \\\"\\\"\\\"Create an httpx AsyncClient with configurable SSL verification.\\n\\n    This is a custom factory that extends the standard MCP client factory\\n    to support disabling SSL verification for self-signed certificates.\\n\\n    Redirects are disabled: connector URLs are SSRF-checked once before\\n    connect, and following 3xx without re-validation could reach private\\n    or link-local hosts. Matches A2A agent client hardening.\\n\\n    Args:\\n        headers: Optional headers to include with all requests.\\n        timeout: Request timeout as httpx.Timeout object.\\n        auth: Optional authentication handler.\\n        verify_ssl: Whether to verify SSL certificates (default: True).\\n\\n    Returns:\\n        Configured httpx.AsyncClient instance.\\n    \\\"\\\"\\\"\\n    kwargs: dict[str, Any] = {\\n        \\\"follow_redirects\\\": False,\\n        \\\"verify\\\": verify_ssl,\\n    }\\n\\n    if timeout is None:\\n        kwargs[\\\"timeout\\\"] = httpx.Timeout(30.0)\\n    else:\\n        kwargs[\\\"timeout\\\"] = timeout\\n\\n    if headers is not None:\\n        kwargs[\\\"headers\\\"] = headers\\n\\n    if auth is not None:\\n        kwargs[\\\"auth\\\"] = auth\\n\\n    return httpx.AsyncClient(**kwargs)\\n\\n\\ndef validate_headers(headers: dict[str, str]) -> dict[str, str]:\\n    \\\"\\\"\\\"Validate and sanitize HTTP headers according to RFC 7230.\\n\\n    Args:\\n        headers: Dictionary of header name-value pairs\\n\\n    Returns:\\n        Dictionary of validated and sanitized headers\\n\\n    Raises:\\n        ValueError: If headers contain invalid names or values\\n    \\\"\\\"\\\"\\n    if not headers:\\n        return {}\\n\\n    sanitized_headers = {}\\n\\n    for name, value in headers.items():\\n        if not isinstance(name, str) or not isinstance(value, str):\\n            logger.warning(f\\\"Skipping non-string header: {name}={value}\\\")\\n            continue\\n\\n        # Validate header name according to RFC 7230\\n        if not HEADER_NAME_PATTERN.match(name):\\n            logger.warning(f\\\"Invalid header name '{name}', skipping\\\")\\n            continue\\n\\n        # Normalize header name to lowercase (HTTP headers are case-insensitive)\\n        normalized_name = name.lower()\\n\\n        # Optional: Check against whitelist of allowed headers\\n        if normalized_name not in ALLOWED_HEADERS:\\n            # For MCP, we'll be permissive and allow non-standard headers\\n            # but log a warning for security awareness\\n            logger.debug(f\\\"Using non-standard header: {normalized_name}\\\")\\n\\n        # Check for potential header injection attempts BEFORE sanitizing\\n        if \\\"\\\\r\\\" in value or \\\"\\\\n\\\" in value:\\n            logger.warning(f\\\"Potential header injection detected in '{name}', skipping\\\")\\n            continue\\n\\n        # Sanitize header value - remove control characters and newlines\\n        # RFC 7230: field-value = *( field-content / obs-fold )\\n        # We'll remove control characters (0x00-0x1F, 0x7F) except tab (0x09) and space (0x20)\\n        sanitized_value = re.sub(r\\\"[\\\\x00-\\\\x08\\\\x0A-\\\\x1F\\\\x7F]\\\", \\\"\\\", value)\\n\\n        # Remove leading/trailing whitespace\\n        sanitized_value = sanitized_value.strip()\\n\\n        if not sanitized_value:\\n            logger.warning(f\\\"Header '{name}' has empty value after sanitization, skipping\\\")\\n            continue\\n\\n        sanitized_headers[normalized_name] = sanitized_value\\n\\n    return sanitized_headers\\n\\n\\ndef sanitize_mcp_name(name: str, max_length: int = 46) -> str:\\n    \\\"\\\"\\\"Sanitize a name for MCP usage by removing emojis, diacritics, and special characters.\\n\\n    Args:\\n        name: The original name to sanitize\\n        max_length: Maximum length for the sanitized name\\n\\n    Returns:\\n        A sanitized name containing only letters, numbers, hyphens, and underscores\\n    \\\"\\\"\\\"\\n    if not name or not name.strip():\\n        return \\\"\\\"\\n\\n    # Remove emojis using regex pattern\\n    emoji_pattern = re.compile(\\n        \\\"[\\\"\\n        \\\"\\\\U0001f600-\\\\U0001f64f\\\"  # emoticons\\n        \\\"\\\\U0001f300-\\\\U0001f5ff\\\"  # symbols & pictographs\\n        \\\"\\\\U0001f680-\\\\U0001f6ff\\\"  # transport & map symbols\\n        \\\"\\\\U0001f1e0-\\\\U0001f1ff\\\"  # flags (iOS)\\n        \\\"\\\\U00002500-\\\\U00002bef\\\"  # chinese char\\n        \\\"\\\\U00002702-\\\\U000027b0\\\"\\n        \\\"\\\\U00002702-\\\\U000027b0\\\"\\n        \\\"\\\\U000024c2-\\\\U0001f251\\\"\\n        \\\"\\\\U0001f926-\\\\U0001f937\\\"\\n        \\\"\\\\U00010000-\\\\U0010ffff\\\"\\n        \\\"\\\\u2640-\\\\u2642\\\"\\n        \\\"\\\\u2600-\\\\u2b55\\\"\\n        \\\"\\\\u200d\\\"\\n        \\\"\\\\u23cf\\\"\\n        \\\"\\\\u23e9\\\"\\n        \\\"\\\\u231a\\\"\\n        \\\"\\\\ufe0f\\\"  # dingbats\\n        \\\"\\\\u3030\\\"\\n        \\\"]+\\\",\\n        flags=re.UNICODE,\\n    )\\n\\n    # Remove emojis\\n    name = emoji_pattern.sub(\\\"\\\", name)\\n\\n    # Normalize unicode characters to remove diacritics\\n    name = unicodedata.normalize(\\\"NFD\\\", name)\\n    name = \\\"\\\".join(char for char in name if unicodedata.category(char) != \\\"Mn\\\")\\n\\n    # Replace spaces and special characters with underscores\\n    name = re.sub(r\\\"[^\\\\w\\\\s-]\\\", \\\"\\\", name)  # Keep only word chars, spaces, and hyphens\\n    name = re.sub(r\\\"[-\\\\s]+\\\", \\\"_\\\", name)  # Replace spaces and hyphens with underscores\\n    name = re.sub(r\\\"_+\\\", \\\"_\\\", name)  # Collapse multiple underscores\\n\\n    # Remove leading/trailing underscores\\n    name = name.strip(\\\"_\\\")\\n\\n    # Ensure it starts with a letter or underscore (not a number)\\n    if name and name[0].isdigit():\\n        name = f\\\"_{name}\\\"\\n\\n    # Convert to lowercase\\n    name = name.lower()\\n\\n    # Truncate to max length\\n    if len(name) > max_length:\\n        name = name[:max_length].rstrip(\\\"_\\\")\\n\\n    # If empty after sanitization, provide a default\\n    if not name:\\n        name = \\\"unnamed\\\"\\n\\n    return name\\n\\n\\ndef _camel_to_snake(name: str) -> str:\\n    \\\"\\\"\\\"Convert camelCase to snake_case.\\\"\\\"\\\"\\n    import re\\n\\n    # Insert an underscore before any uppercase letter that follows a lowercase letter\\n    s1 = re.sub(\\\"([a-z0-9])([A-Z])\\\", r\\\"\\\\1_\\\\2\\\", name)\\n    return s1.lower()\\n\\n\\ndef _convert_camel_case_to_snake_case(provided_args: dict[str, Any], arg_schema: type[BaseModel]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Convert camelCase field names to snake_case if the schema expects snake_case fields.\\\"\\\"\\\"\\n    schema_fields = set(arg_schema.model_fields.keys())\\n    converted_args = {}\\n\\n    for key, value in provided_args.items():\\n        # If the key already exists in schema, use it as-is\\n        if key in schema_fields:\\n            converted_args[key] = value\\n        else:\\n            # Try converting camelCase to snake_case\\n            snake_key = _camel_to_snake(key)\\n            if snake_key in schema_fields:\\n                converted_args[snake_key] = value\\n            else:\\n                # If neither the original nor converted key exists, keep original\\n                # The validation will catch this error\\n                converted_args[key] = value\\n\\n    return converted_args\\n\\n\\ndef _resolve_expected_type(annotation: Any) -> type | None:\\n    \\\"\\\"\\\"Resolve the effective expected type from a Pydantic field annotation.\\n\\n    Handles Union, UnionType (X | None), list, list[X]. Returns the primary\\n    type (dict, list, int, float, bool, str) or None if not one we normalize.\\n    \\\"\\\"\\\"\\n    ann = annotation\\n    origin = get_origin(ann)\\n    if origin is UnionType or origin is Union:\\n        args = get_args(ann)\\n        non_none = [a for a in args if a is not type(None)]\\n        if non_none:\\n            ann = non_none[0]\\n            origin = get_origin(ann)\\n    if origin is list or ann is list:\\n        return list\\n    if origin is dict or ann is dict:\\n        return dict\\n    if ann in (int, float, bool, str):\\n        return ann\\n    return None\\n\\n\\ndef _annotation_accepts_none(annotation: Any) -> bool:\\n    \\\"\\\"\\\"Check if annotation accepts None (e.g. Union[X, None], X | None).\\\"\\\"\\\"\\n    origin = get_origin(annotation)\\n    if origin is UnionType or origin is Union:\\n        args = get_args(annotation)\\n        return type(None) in args\\n    return False\\n\\n\\ndef _is_pydantic_model_type(annotation: Any) -> bool:\\n    \\\"\\\"\\\"Check if annotation refers to a Pydantic BaseModel (possibly in Union with None).\\\"\\\"\\\"\\n    ann = annotation\\n    origin = get_origin(ann)\\n    if origin is UnionType or origin is Union:\\n        args = get_args(ann)\\n        non_none = [a for a in args if a is not type(None)]\\n        if non_none:\\n            ann = non_none[0]\\n    return isinstance(ann, type) and issubclass(ann, BaseModel)\\n\\n\\ndef _unwrap_langflow_json_value(value: Any) -> Any:\\n    \\\"\\\"\\\"Return the payload dict from Langflow JSON/Data values wired into MCP object parameters.\\\"\\\"\\\"\\n    if isinstance(value, Data):\\n        return value.data\\n    return value\\n\\n\\ndef _try_convert_value(value: Any, expected_type: type, field_name: str, tool_name: str) -> Any:\\n    \\\"\\\"\\\"Try to convert value to expected type. Raise ValueError with clear message on failure.\\\"\\\"\\\"\\n\\n    def _err(type_desc: str, detail: str) -> ValueError:\\n        msg = f\\\"Tool '{tool_name}': Parameter '{field_name}' expects {type_desc} {detail}\\\"\\n        return ValueError(msg)\\n\\n    expected_type_desc = expected_type.__name__\\n\\n    if value is None and expected_type in (int, float, bool, dict, list):\\n        raise _err(expected_type_desc, \\\"but received None.\\\")\\n\\n    if expected_type in (dict, list):\\n        value = _unwrap_langflow_json_value(value)\\n\\n    # return correctly typed value, but handle the\\n    # special case of bool as this is a subclass of int\\n    # we'll NOT return but raise an error\\n    if isinstance(value, expected_type) and not (expected_type is int and isinstance(value, bool)):\\n        return value\\n\\n    # return custom classes as is\\n    if expected_type not in (dict, list, int, float, bool):\\n        return value\\n\\n    if expected_type in (dict, list):\\n        expected_type_desc = \\\"object (dict)\\\" if expected_type is dict else \\\"array (list)\\\"\\n        if isinstance(value, str):\\n            try:\\n                parsed = json.loads(value)\\n            except json.JSONDecodeError as e:\\n                raise _err(expected_type_desc, f\\\"but received invalid JSON string {value!r}; {e}\\\") from e\\n            if not isinstance(parsed, expected_type):\\n                raise _err(expected_type_desc, f\\\"but JSON parsed to {type(parsed).__name__}.\\\")\\n            return parsed\\n\\n    elif expected_type is int:\\n        expected_type_desc = \\\"integer (int)\\\"\\n        if isinstance(value, float) and value.is_integer():\\n            return int(value)\\n        if isinstance(value, str):\\n            try:\\n                return int(value)\\n            except ValueError as e:\\n                raise _err(expected_type_desc, f\\\"but received string: {value!r}; could not convert.\\\") from e\\n\\n    elif expected_type is float:\\n        expected_type_desc = \\\"number (float)\\\"\\n        if isinstance(value, (int, float)):\\n            return float(value)\\n        if isinstance(value, str):\\n            try:\\n                return float(value)\\n            except ValueError as e:\\n                raise _err(expected_type_desc, f\\\"but received string: {value!r}; could not convert.\\\") from e\\n\\n    elif expected_type is bool and isinstance(value, str):\\n        expected_type_desc = \\\"boolean (bool)\\\"\\n        lower = value.strip().lower()\\n        if lower in (\\\"true\\\", \\\"1\\\", \\\"yes\\\"):\\n            return True\\n        if lower in (\\\"false\\\", \\\"0\\\", \\\"no\\\"):\\n            return False\\n\\n    detail = f\\\"but received {type(value).__name__}: {value!r}; could not convert.\\\"\\n    raise _err(expected_type_desc, detail)\\n\\n\\ndef _normalize_arguments_for_mcp(\\n    arguments: dict[str, Any], arg_schema: type[BaseModel], tool_name: str\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Normalize tool arguments for MCP: try-convert when value type != schema expected type.\\n\\n    Uses schema from MCP server (no guessing). On conversion failure, raises\\n    ValueError with clear user-facing message.\\n    \\\"\\\"\\\"\\n    result: dict[str, Any] = {}\\n    schema_field_names = set(arg_schema.model_fields.keys())\\n    for field_name, model_field in arg_schema.model_fields.items():\\n        value = arguments.get(field_name)\\n        if value is None:\\n            if not (model_field.is_required() or field_name in arguments):\\n                continue\\n            expected = _resolve_expected_type(model_field.annotation)\\n            if expected in (list, dict, str) and model_field.is_required():\\n                result[field_name] = [] if expected is list else ({} if expected is dict else \\\"\\\")\\n            elif expected in (list, dict, str) and _annotation_accepts_none(model_field.annotation):\\n                result[field_name] = None\\n            else:\\n                result[field_name] = value\\n            continue\\n        expected = _resolve_expected_type(model_field.annotation)\\n        if expected is None:\\n            # Nested Pydantic model (object with properties): UI/API often sends as JSON string\\n            if _is_pydantic_model_type(model_field.annotation):\\n                value = _unwrap_langflow_json_value(value)\\n                if isinstance(value, str):\\n                    try:\\n                        parsed = json.loads(value)\\n                    except json.JSONDecodeError as e:\\n                        msg = (\\n                            f\\\"Tool '{tool_name}': Parameter '{field_name}' expects object \\\"\\n                            f\\\"but received invalid JSON string {value!r}; {e}\\\"\\n                        )\\n                        raise ValueError(msg) from e\\n                    if not isinstance(parsed, dict):\\n                        msg = (\\n                            f\\\"Tool '{tool_name}': Parameter '{field_name}' expects object \\\"\\n                            f\\\"but JSON parsed to {type(parsed).__name__}.\\\"\\n                        )\\n                        raise ValueError(msg)  # noqa: TRY004\\n                    value = parsed\\n            result[field_name] = value\\n            continue\\n        if expected is str:\\n            result[field_name] = value\\n            continue\\n        result[field_name] = _try_convert_value(value, expected, field_name, tool_name)\\n    # Preserve extra keys so Pydantic validation can report them\\n    result.update({k: v for k, v in arguments.items() if k not in schema_field_names})\\n    return result\\n\\n\\ndef _handle_tool_validation_error(\\n    e: Exception, tool_name: str, provided_args: dict[str, Any], arg_schema: type[BaseModel]\\n) -> None:\\n    \\\"\\\"\\\"Handle validation errors for tool arguments with detailed error messages.\\\"\\\"\\\"\\n    # Check if this is a case where the tool was called with no arguments\\n    if not provided_args and hasattr(arg_schema, \\\"model_fields\\\"):\\n        required_fields = [name for name, field in arg_schema.model_fields.items() if field.is_required()]\\n        if required_fields:\\n            msg = (\\n                f\\\"Tool '{tool_name}' requires arguments but none were provided. \\\"\\n                f\\\"Required fields: {', '.join(required_fields)}. \\\"\\n                f\\\"Please check that the LLM is properly calling the tool with arguments.\\\"\\n            )\\n            raise ValueError(msg) from e\\n    msg = f\\\"Invalid input: {e}\\\"\\n    raise ValueError(msg) from e\\n\\n\\ndef _strip_none_recursive(obj: Any) -> Any:\\n    \\\"\\\"\\\"Recursively remove None values from dicts (including inside lists).\\n\\n    ``model_dump(exclude_none=True)`` handles top-level and nested-model\\n    None fields, but when LLMs explicitly send ``null`` for fields inside\\n    arrays of objects the serialised dict may still contain ``None``.\\n    This helper guarantees a clean payload before it reaches the MCP server.\\n    \\\"\\\"\\\"\\n    if isinstance(obj, dict):\\n        return {k: _strip_none_recursive(v) for k, v in obj.items() if v is not None}\\n    if isinstance(obj, list):\\n        return [_strip_none_recursive(item) for item in obj]\\n    return obj\\n\\n\\ndef _convert_mcp_result(result: Any) -> Any:\\n    \\\"\\\"\\\"Convert a CallToolResult into a format LangChain agents can consume.\\n\\n    - Text-only results \u2192 plain string (backward compatible).\\n    - Results containing images or unsupported blocks \u2192 list of LangChain\\n      content blocks so that vision-capable LLMs receive proper multimodal\\n      input instead of a raw base64 string (fixes issue #11812).\\n    - Unsupported block types (resource, resource_link, audio, etc.) are\\n      serialised as ``{\\\"type\\\": \\\"text\\\", \\\"text\\\": json.dumps(block)}`` so no\\n      content is silently dropped on the agent path.\\n    - Only collapses back to a plain string when every block is plain text.\\n    \\\"\\\"\\\"\\n    if result is None:\\n        return \\\"\\\"\\n\\n    content = getattr(result, \\\"content\\\", None)\\n    if not content:\\n        return \\\"\\\"\\n\\n    needs_list = any(getattr(block, \\\"type\\\", None) != \\\"text\\\" for block in content)\\n\\n    if not needs_list:\\n        # Text-only: join all text blocks into a single string (backward compat)\\n        return \\\"\\\\n\\\".join(getattr(block, \\\"text\\\", \\\"\\\") for block in content if getattr(block, \\\"type\\\", None) == \\\"text\\\")\\n\\n    # Mixed or non-text: build a list of LangChain content blocks\\n    blocks: list[dict] = []\\n    for block in content:\\n        block_type = getattr(block, \\\"type\\\", None)\\n        if block_type == \\\"text\\\":\\n            blocks.append({\\\"type\\\": \\\"text\\\", \\\"text\\\": getattr(block, \\\"text\\\", \\\"\\\")})\\n        elif block_type == \\\"image\\\":\\n            mime = getattr(block, \\\"mimeType\\\", None) or \\\"image/png\\\"\\n            data = getattr(block, \\\"data\\\", \\\"\\\")\\n            blocks.append(\\n                {\\n                    \\\"type\\\": \\\"image_url\\\",\\n                    \\\"image_url\\\": {\\\"url\\\": f\\\"data:{mime};base64,{data}\\\"},\\n                }\\n            )\\n        else:\\n            # Unsupported block type (resource, resource_link, audio, \u2026):\\n            # serialise to JSON text so no content is lost on the agent path.\\n            try:\\n                raw_text = json.dumps(block.model_dump(), ensure_ascii=False)\\n            except AttributeError:\\n                raw_text = json.dumps({\\\"type\\\": block_type, \\\"raw\\\": str(block)}, ensure_ascii=False)\\n            blocks.append({\\\"type\\\": \\\"text\\\", \\\"text\\\": raw_text})\\n    return blocks\\n\\n\\ndef _raise_if_tool_result_is_error(tool_name: str, result: Any) -> None:\\n    \\\"\\\"\\\"A CallToolResult with isError=True is a FAILED call; returning it as data hides the failure.\\n\\n    Enforced here (package code, shared by the component build and the agent tool path) rather\\n    than only in the component, because saved flows freeze component code and a pre-fix\\n    ``build_output`` would keep swallowing failures.\\n    \\\"\\\"\\\"\\n    if not getattr(result, \\\"isError\\\", False):\\n        return\\n    content = getattr(result, \\\"content\\\", None) or []\\n    error_text = \\\" \\\".join(\\n        getattr(block, \\\"text\\\", \\\"\\\") for block in content if getattr(block, \\\"type\\\", None) == \\\"text\\\"\\n    ).strip()\\n    msg = f\\\"MCP tool '{tool_name}' failed: {error_text or 'no error detail provided'}\\\"\\n    raise ValueError(msg)\\n\\n\\ndef create_tool_coroutine(tool_name: str, arg_schema: type[BaseModel], client) -> Callable[..., Awaitable]:\\n    async def tool_coroutine(*args, **kwargs):\\n        # Get field names from the model (preserving order)\\n        field_names = list(arg_schema.model_fields.keys())\\n        provided_args = {}\\n        # Map positional arguments to their corresponding field names\\n        for i, arg in enumerate(args):\\n            if i >= len(field_names):\\n                msg = \\\"Too many positional arguments provided\\\"\\n                raise ValueError(msg)\\n            provided_args[field_names[i]] = arg\\n        # Merge in keyword arguments\\n        provided_args.update(kwargs)\\n        provided_args = _convert_camel_case_to_snake_case(provided_args, arg_schema)\\n        original_args = provided_args\\n        provided_args = _normalize_arguments_for_mcp(provided_args, arg_schema, tool_name)\\n        # Validate input and fill defaults for missing optional fields\\n        try:\\n            validated = arg_schema.model_validate(provided_args)\\n        except Exception as e:  # noqa: BLE001\\n            _handle_tool_validation_error(e, tool_name, original_args, arg_schema)\\n\\n        try:\\n            arguments = _strip_none_recursive(validated.model_dump(exclude_none=True))\\n            result = await client.run_tool(tool_name, arguments=arguments)\\n        except Exception as e:\\n            await logger.aerror(f\\\"Tool '{tool_name}' execution failed: {e}\\\")\\n            # Re-raise with more context\\n            msg = f\\\"Tool '{tool_name}' execution failed: {e}\\\"\\n            raise ValueError(msg) from e\\n        _raise_if_tool_result_is_error(tool_name, result)\\n        return result\\n\\n    return tool_coroutine\\n\\n\\ndef create_tool_func(tool_name: str, arg_schema: type[BaseModel], client) -> Callable[..., str]:\\n    def tool_func(*args, **kwargs):\\n        field_names = list(arg_schema.model_fields.keys())\\n        provided_args = {}\\n        for i, arg in enumerate(args):\\n            if i >= len(field_names):\\n                msg = \\\"Too many positional arguments provided\\\"\\n                raise ValueError(msg)\\n            provided_args[field_names[i]] = arg\\n        provided_args.update(kwargs)\\n        provided_args = _convert_camel_case_to_snake_case(provided_args, arg_schema)\\n        original_args = provided_args\\n        provided_args = _normalize_arguments_for_mcp(provided_args, arg_schema, tool_name)\\n        try:\\n            validated = arg_schema.model_validate(provided_args)\\n        except Exception as e:  # noqa: BLE001\\n            _handle_tool_validation_error(e, tool_name, original_args, arg_schema)\\n\\n        try:\\n            arguments = _strip_none_recursive(validated.model_dump(exclude_none=True))\\n            result = run_until_complete(client.run_tool(tool_name, arguments=arguments))\\n        except Exception as e:\\n            logger.error(f\\\"Tool '{tool_name}' execution failed: {e}\\\")\\n            # Re-raise with more context\\n            msg = f\\\"Tool '{tool_name}' execution failed: {e}\\\"\\n            raise ValueError(msg) from e\\n        _raise_if_tool_result_is_error(tool_name, result)\\n        return result\\n\\n    return tool_func\\n\\n\\ndef get_unique_name(base_name, max_length, existing_names):\\n    name = base_name[:max_length]\\n    if name not in existing_names:\\n        return name\\n    i = 1\\n    while True:\\n        suffix = f\\\"_{i}\\\"\\n        truncated_base = base_name[: max_length - len(suffix)]\\n        candidate = f\\\"{truncated_base}{suffix}\\\"\\n        if candidate not in existing_names:\\n            return candidate\\n        i += 1\\n\\n\\nasync def get_flow_snake_case(\\n    flow_name: str,\\n    user_id: str,\\n    session,\\n    *,\\n    is_action: bool | None = None,\\n    project_id: UUID | str | None = None,\\n    mcp_enabled_only: bool = False,\\n):\\n    \\\"\\\"\\\"Resolve an MCP tool name to a flow.\\n\\n    ``project_id`` and ``mcp_enabled_only`` default to the historical behavior because\\n    this function is public ``lfx`` surface and still backs the global MCP server, where\\n    user-only scoping is correct. Project-scoped callers must pass both: without them a\\n    tool call resolves against every flow the user owns, so an unexposed flow is\\n    reachable by name and two projects sharing an ``action_name`` collide on whichever\\n    row the planner happens to return first.\\n    \\\"\\\"\\\"\\n    try:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n    except ImportError as e:\\n        msg = \\\"Langflow Flow model is not available. This feature requires the full Langflow installation.\\\"\\n        raise ImportError(msg) from e\\n\\n    uuid_user_id = UUID(user_id) if isinstance(user_id, str) else user_id\\n\\n    stmt = select(Flow).where(Flow.user_id == uuid_user_id).where(Flow.is_component == False)  # noqa: E712\\n    if project_id is not None:\\n        uuid_project_id = UUID(project_id) if isinstance(project_id, str) else project_id\\n        stmt = stmt.where(Flow.folder_id == uuid_project_id)\\n    if mcp_enabled_only:\\n        stmt = stmt.where(Flow.mcp_enabled == True)  # noqa: E712\\n    # ``action_name`` has no uniqueness constraint; without an explicit order the winner\\n    # is heap-order dependent and an unrelated edit can flip which flow a tool call runs.\\n    stmt = stmt.order_by(Flow.id)\\n    flows = (await session.exec(stmt)).all()\\n\\n    for flow in flows:\\n        if is_action and flow.action_name:\\n            this_flow_name = sanitize_mcp_name(flow.action_name)\\n        else:\\n            this_flow_name = sanitize_mcp_name(flow.name)\\n\\n        if this_flow_name == flow_name:\\n            return flow\\n    return None\\n\\n\\ndef _is_valid_key_value_item(item: Any) -> bool:\\n    \\\"\\\"\\\"Check if an item is a valid key-value dictionary.\\\"\\\"\\\"\\n    return isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item\\n\\n\\ndef _process_headers(headers: Any, request_variables: dict[str, str] | None = None) -> dict:\\n    \\\"\\\"\\\"Process the headers input into a valid dictionary and resolve global variables.\\n\\n    Args:\\n        headers: The headers to process, can be dict, str, or list\\n        request_variables: Optional dict of global variables to resolve header values\\n    Returns:\\n        Processed and validated dictionary with resolved global variable values\\n    \\\"\\\"\\\"\\n    if headers is None:\\n        return {}\\n    if isinstance(headers, dict):\\n        resolved_headers = _resolve_global_variables_in_headers(headers, request_variables)\\n        return validate_headers(resolved_headers)\\n    if isinstance(headers, list):\\n        processed_headers = {}\\n        try:\\n            for item in headers:\\n                if not _is_valid_key_value_item(item):\\n                    continue\\n                key = item[\\\"key\\\"]\\n                value = item[\\\"value\\\"]\\n                processed_headers[key] = value\\n        except (KeyError, TypeError, ValueError):\\n            return {}  # Return empty dictionary instead of None\\n        resolved_headers = _resolve_global_variables_in_headers(processed_headers, request_variables)\\n        return validate_headers(resolved_headers)\\n    return {}\\n\\n\\ndef _inject_mcp_stdio_headers(args: list[str], headers: dict[str, str]) -> list[str]:\\n    \\\"\\\"\\\"Add sanitized proxy header arguments without treating opaque values as command syntax.\\\"\\\"\\\"\\n    if not headers:\\n        return list(args)\\n\\n    final_args = list(args)\\n    extra_args: list[str] = []\\n    for key, value in headers.items():\\n        extra_args.extend([\\\"--headers\\\", key, value])\\n\\n    if \\\"--headers\\\" in final_args:\\n        idx = final_args.index(\\\"--headers\\\")\\n        return final_args[:idx] + extra_args + final_args[idx:]\\n\\n    # Insert before the last positional argument (typically the upstream URL),\\n    # while skipping flag/value pairs.\\n    last_positional_idx: int | None = None\\n    index = 0\\n    while index < len(final_args):\\n        if final_args[index].startswith(\\\"-\\\"):\\n            index += 1\\n            if (\\n                index < len(final_args)\\n                and not final_args[index].startswith(\\\"-\\\")\\n                and not final_args[index].startswith((\\\"http://\\\", \\\"https://\\\"))\\n            ):\\n                index += 1\\n        else:\\n            last_positional_idx = index\\n            index += 1\\n\\n    if last_positional_idx is not None:\\n        return final_args[:last_positional_idx] + extra_args + final_args[last_positional_idx:]\\n    return [*final_args, *extra_args]\\n\\n\\nGLOBAL_VARIABLE_PLACEHOLDER_PATTERN = re.compile(r\\\"\\\\{\\\\{\\\\s*([A-Za-z_][A-Za-z0-9_\\\\-]*)\\\\s*\\\\}\\\\}\\\")\\n\\nHTTP_STATUS_IN_MESSAGE_PATTERN = re.compile(r\\\"(?:HTTP|status(?:\\\\s+code)?)[\\\\s:=]*([45]\\\\d{2})\\\\b\\\", re.IGNORECASE)\\n\\n\\ndef _exception_group_types() -> tuple[type[BaseException], ...]:\\n    types_: list[type[BaseException]] = []\\n    builtin_group = getattr(builtins, \\\"BaseExceptionGroup\\\", None)\\n    if builtin_group is not None:\\n        types_.append(builtin_group)\\n    try:\\n        from exceptiongroup import BaseExceptionGroup as BackportGroup\\n    except ImportError:\\n        pass\\n    else:\\n        if BackportGroup not in types_:\\n            types_.append(BackportGroup)\\n    return tuple(types_)\\n\\n\\n_EXCEPTION_GROUP_TYPES = _exception_group_types()\\n\\n\\ndef _substitute_global_variables(value: str, request_variables: dict[str, str] | None) -> str:\\n    \\\"\\\"\\\"Resolve a whole-value variable name, or ``{{NAME}}`` placeholders inside a value.\\n\\n    Whole-value matching alone cannot compose a value, so a base URL could not be varied\\n    per environment while keeping a project id. An unknown placeholder is left verbatim:\\n    blanking it would build a URL that looks valid and points somewhere else.\\n    \\\"\\\"\\\"\\n    if not request_variables or not value:\\n        return value\\n    if value in request_variables:\\n        return request_variables[value]\\n    return GLOBAL_VARIABLE_PLACEHOLDER_PATTERN.sub(\\n        lambda match: request_variables.get(match.group(1), match.group(0)), value\\n    )\\n\\n\\ndef resolve_global_variables_in_url(url: str, request_variables: dict[str, str] | None) -> str:\\n    \\\"\\\"\\\"Resolve global variables in a server URL, matching how headers are resolved.\\\"\\\"\\\"\\n    if not isinstance(url, str):\\n        return url\\n    return _substitute_global_variables(url, request_variables)\\n\\n\\ndef config_uses_global_variables(server_config: dict | None) -> bool:\\n    \\\"\\\"\\\"Report whether a server config references global variables anywhere.\\n\\n    Gating the variable load on headers alone meant a config whose only variable lived in\\n    the URL never had anything to resolve against. ``env`` counts for the same reason and\\n    is scrubbed into ``MCP_*`` names by the same code path: leaving it out handed the\\n    stdio subprocess the variable name in place of the credential.\\n    \\\"\\\"\\\"\\n    if not server_config:\\n        return False\\n    if server_config.get(\\\"headers\\\") or server_config.get(\\\"env\\\"):\\n        return True\\n    url = server_config.get(\\\"url\\\")\\n    return bool(isinstance(url, str) and GLOBAL_VARIABLE_PLACEHOLDER_PATTERN.search(url))\\n\\n\\ndef extract_http_status(error: BaseException) -> int | None:\\n    \\\"\\\"\\\"Find the HTTP status of an outbound failure, however deeply anyio grouped it.\\n\\n    The status never survives on the group itself: ``str()`` of a TaskGroup failure is\\n    ``unhandled errors in a TaskGroup``, so reading the top-level exception tells the\\n    operator nothing about why the server rejected the call.\\n    \\\"\\\"\\\"\\n    for leaf in _iter_exception_leaves(error):\\n        if isinstance(leaf, httpx.HTTPStatusError):\\n            return leaf.response.status_code\\n        if isinstance(leaf, McpError):\\n            match = HTTP_STATUS_IN_MESSAGE_PATTERN.search(str(leaf))\\n            if match:\\n                return int(match.group(1))\\n    return None\\n\\n\\ndef describe_mcp_tool_failure(tool_name: str, url: str | None, error: BaseException) -> str:\\n    \\\"\\\"\\\"Describe a tool call the remote server rejected, naming the status when there is one.\\n\\n    Connect-time reporting is not enough: a credential can expire after the session is\\n    established, and the rejection then lands here instead.\\n    \\\"\\\"\\\"\\n    status = extract_http_status(error)\\n    target = f\\\" at {sanitize_url_for_display(url)}\\\" if url else \\\"\\\"\\n    cause = redact_urls_in_text(str(error))\\n    if status in (HTTP_UNAUTHORIZED, HTTP_FORBIDDEN):\\n        return (\\n            f\\\"Tool '{tool_name}'{target} was rejected with HTTP {status}: \\\"\\n            f\\\"the configured credential was refused. Cause: {cause}\\\"\\n        )\\n    if status is not None:\\n        return f\\\"Tool '{tool_name}'{target} failed with HTTP {status}: {cause}\\\"\\n    return f\\\"Tool '{tool_name}'{target} failed: {cause}\\\"\\n\\n\\ndef describe_mcp_connection_failure(server_name: str, url: str, error: BaseException) -> str:\\n    \\\"\\\"\\\"Describe an outbound MCP failure by target, status and cause.\\n\\n    A wrong credential surfaced as ``unhandled errors in a TaskGroup`` with no indication\\n    that authentication failed or which server rejected it.\\n    \\\"\\\"\\\"\\n    target = sanitize_url_for_display(url) if urlparse(url).scheme else server_name\\n    cause = redact_urls_in_text(str(error))\\n\\n    status = extract_http_status(error)\\n    if status in (HTTP_UNAUTHORIZED, HTTP_FORBIDDEN):\\n        return (\\n            f\\\"MCP server '{server_name}' at {target} rejected the request with HTTP {status}: \\\"\\n            f\\\"the configured credential was refused. Cause: {cause}\\\"\\n        )\\n    if status is not None:\\n        return f\\\"MCP server '{server_name}' at {target} failed with HTTP {status}: {cause}\\\"\\n    return f\\\"MCP server '{server_name}' at {target} failed: {cause}\\\"\\n\\n\\ndef _resolve_global_variables_in_headers(headers: dict, request_variables: dict[str, str] | None) -> dict:\\n    \\\"\\\"\\\"Resolve global variable names in header values to their actual values.\\n\\n    Args:\\n        headers: Dictionary of headers where values might be global variable names\\n        request_variables: Dictionary of global variables from request context\\n\\n    Returns:\\n        Dictionary with resolved header values\\n    \\\"\\\"\\\"\\n    if not request_variables:\\n        return headers\\n\\n    return {\\n        key: _substitute_global_variables(value, request_variables) if isinstance(value, str) else value\\n        for key, value in headers.items()\\n    }\\n\\n\\ndef _validate_node_installation(command: str) -> str:\\n    \\\"\\\"\\\"Validate the npx command.\\\"\\\"\\\"\\n    if \\\"npx\\\" in command and not shutil.which(\\\"node\\\"):\\n        msg = \\\"Node.js is not installed. Please install Node.js to use npx commands.\\\"\\n        raise ValueError(msg)\\n    return command\\n\\n\\nasync def _validate_connection_params(mode: str, command: str | None = None, url: str | None = None) -> None:\\n    \\\"\\\"\\\"Validate connection parameters based on mode.\\\"\\\"\\\"\\n    if mode not in [\\\"Stdio\\\", \\\"Streamable_HTTP\\\", \\\"SSE\\\"]:\\n        msg = f\\\"Invalid mode: {mode}. Must be either 'Stdio', 'Streamable_HTTP', or 'SSE'\\\"\\n        raise ValueError(msg)\\n\\n    if mode == \\\"Stdio\\\" and not command:\\n        msg = \\\"Command is required for Stdio mode\\\"\\n        raise ValueError(msg)\\n    if mode == \\\"Stdio\\\" and command:\\n        _validate_node_installation(command)\\n    if mode in [\\\"Streamable_HTTP\\\", \\\"SSE\\\"] and not url:\\n        msg = f\\\"URL is required for {mode} mode\\\"\\n        raise ValueError(msg)\\n\\n\\n# Streamable HTTP connect: retries before giving up (transient network / server restart)\\nSTREAMABLE_HTTP_CONNECT_ATTEMPTS = 3\\nSTREAMABLE_HTTP_RETRY_BASE_DELAY_SEC = 0.35\\n\\n\\ndef _iter_exception_leaves(exc: BaseException) -> list[BaseException]:\\n    \\\"\\\"\\\"Flatten ExceptionGroup / TaskGroup failures to individual exceptions.\\n\\n    On Python 3.10 the builtin does not exist and anyio raises the ``exceptiongroup``\\n    backport instead, so checking builtins alone left every 3.10 deployment unable to\\n    see the real cause inside a TaskGroup failure.\\n    \\\"\\\"\\\"\\n    if isinstance(exc, _EXCEPTION_GROUP_TYPES):\\n        leaves: list[BaseException] = []\\n        for sub in exc.exceptions:\\n            leaves.extend(_iter_exception_leaves(sub))\\n        return leaves\\n    return [exc]\\n\\n\\ndef _is_transient_streamable_http_error(exc: BaseException) -> bool:\\n    \\\"\\\"\\\"True when Streamable HTTP failed for a likely-temporary reason; do not fall back to SSE.\\\"\\\"\\\"\\n    for leaf in _iter_exception_leaves(exc):\\n        if isinstance(leaf, (asyncio.TimeoutError, ConnectionError, OSError, BrokenPipeError)):\\n            return True\\n        if isinstance(leaf, ClosedResourceError):\\n            return True\\n        if isinstance(leaf, httpx.RequestError):\\n            return True\\n        if isinstance(leaf, httpx.HTTPStatusError):\\n            # Server errors and rate limits \u2014 retry Streamable HTTP, not SSE switch\\n            if leaf.response.status_code >= HTTP_INTERNAL_SERVER_ERROR:\\n                return True\\n            if leaf.response.status_code == HTTP_TOO_MANY_REQUESTS:\\n                return True\\n            # 404/405/406: try SSE; other 4xx: retry Streamable HTTP\\n            return leaf.response.status_code not in (\\n                HTTP_NOT_FOUND,\\n                HTTP_METHOD_NOT_ALLOWED,\\n                HTTP_NOT_ACCEPTABLE,\\n            )\\n        if isinstance(leaf, McpError):\\n            msg = str(leaf).lower()\\n            return not any(x in msg for x in (\\\"404\\\", \\\"405\\\", \\\"406\\\", \\\"not found\\\", \\\"method not allowed\\\"))\\n        msg = str(leaf).lower()\\n        if any(\\n            x in msg\\n            for x in (\\n                \\\"session terminated\\\",\\n                \\\"connection closed\\\",\\n                \\\"connection lost\\\",\\n                \\\"connection reset\\\",\\n                \\\"taskgroup\\\",\\n                \\\"unhandled errors in a taskgroup\\\",\\n                \\\"broken pipe\\\",\\n                \\\"transport closed\\\",\\n                \\\"stream closed\\\",\\n            )\\n        ):\\n            return True\\n    return False\\n\\n\\ndef _should_attempt_sse_after_streamable_failure(exc: BaseException) -> bool:\\n    \\\"\\\"\\\"True when Streamable HTTP likely failed because the endpoint expects legacy SSE, not transient outage.\\\"\\\"\\\"\\n    if _is_transient_streamable_http_error(exc):\\n        return False\\n    for leaf in _iter_exception_leaves(exc):\\n        if isinstance(leaf, httpx.HTTPStatusError) and leaf.response.status_code in (\\n            HTTP_NOT_FOUND,\\n            HTTP_METHOD_NOT_ALLOWED,\\n            HTTP_NOT_ACCEPTABLE,\\n        ):\\n            return True\\n        if isinstance(leaf, McpError):\\n            msg = str(leaf).lower()\\n            if any(x in msg for x in (\\\"404\\\", \\\"405\\\", \\\"406\\\", \\\"not found\\\", \\\"method not allowed\\\", \\\"not acceptable\\\")):\\n                return True\\n    lowered = str(exc).lower()\\n    return any(x in lowered for x in (\\\"404\\\", \\\"405\\\", \\\"406\\\", \\\"not found\\\", \\\"method not allowed\\\", \\\"not acceptable\\\"))\\n\\n\\ndef _is_mcp_session_bust_error(exc: BaseException) -> bool:\\n    \\\"\\\"\\\"Whether cached ClientSession should be discarded and re-established (run_tool / list_tools).\\\"\\\"\\\"\\n    for leaf in _iter_exception_leaves(exc):\\n        if isinstance(leaf, ClosedResourceError):\\n            return True\\n        if isinstance(leaf, McpError):\\n            msg = str(leaf).lower()\\n            if any(x in msg for x in (\\\"connection closed\\\", \\\"session terminated\\\", \\\"connection lost\\\")):\\n                return True\\n        msg = str(leaf).lower()\\n        if any(x in msg for x in (\\\"session terminated\\\", \\\"connection closed\\\", \\\"connection lost\\\")):\\n            return True\\n    return False\\n\\n\\nclass _ServerLockEntry(TypedDict):\\n    \\\"\\\"\\\"Shape of each value in ``MCPSessionManager._server_locks``.\\n\\n    ``pins`` is the number of callers that have obtained (but not yet\\n    released) the lock via ``_server_lock``; it gates reclamation of the\\n    entry so a new caller can't grab a fresh lock while an older caller is\\n    about to enter the old one.\\n    \\\"\\\"\\\"\\n\\n    lock: asyncio.Lock\\n    pins: int\\n\\n\\n# TODO(langflow-ai/langflow#12541-followup): MCPSessionManager lives in this\\n# 2k+ line module; extract it (and the concurrency primitives below) into a\\n# dedicated ``mcp/session_manager.py`` so future edits stay small.\\nclass MCPSessionManager:\\n    \\\"\\\"\\\"Manages persistent MCP sessions with proper context manager lifecycle.\\n\\n    Fixed version that addresses the memory leak issue by:\\n    1. Session reuse based on server identity rather than unique context IDs\\n    2. Maximum session limits per server to prevent resource exhaustion\\n    3. Idle timeout for automatic session cleanup\\n    4. Periodic cleanup of stale sessions\\n    5. Transport preference caching to avoid retrying failed transports\\n    \\\"\\\"\\\"\\n\\n    def __init__(self):\\n        # Structure: server_key -> {\\\"sessions\\\": {session_id: session_info}, \\\"last_cleanup\\\": timestamp}\\n        self.sessions_by_server = {}\\n        self._background_tasks: set[asyncio.Task[Any]] = set()  # Keep references to background tasks\\n        # Backwards-compatibility maps: which context_id uses which (server_key, session_id)\\n        self._context_to_session: dict[str, tuple[str, str]] = {}\\n        # Reference count for each active (server_key, session_id)\\n        self._session_refcount: dict[tuple[str, str], int] = {}\\n        # Cache which transport works for each server to avoid retrying failed transports\\n        # server_key -> \\\"streamable_http\\\" | \\\"sse\\\"\\n        self._transport_preference: dict[str, str] = {}\\n        # Per-server asyncio locks to serialize session create/reuse/cleanup under\\n        # concurrent access. Without this, two concurrent flow executions sharing\\n        # the same MCP server URL can race on the sessions dict and raise a\\n        # KeyError from `del sessions[session_id]` in `_cleanup_session_by_id`, or\\n        # create colliding session_ids from `len(sessions)`.\\n        #\\n        # Each entry is a `_ServerLockEntry` {\\\"lock\\\": asyncio.Lock(), \\\"pins\\\": int}.\\n        # The pin count is the number of callers that have obtained (but not yet\\n        # released) the lock via `_server_lock`. We reclaim the entry only when\\n        # pins == 0 and the lock is not held, to avoid a new caller grabbing a\\n        # fresh lock while an older caller is about to enter the old one.\\n        self._server_locks: dict[str, _ServerLockEntry] = {}\\n        self._locks_guard = asyncio.Lock()\\n        # Monotonic counter per server_key to generate unique session_ids even\\n        # when sessions are removed between allocations.\\n        self._session_id_counters: dict[str, int] = {}\\n        self._cleanup_task = None\\n        self._start_cleanup_task()\\n\\n    @contextlib.asynccontextmanager\\n    async def _server_lock(self, server_key: str) -> AsyncIterator[None]:\\n        \\\"\\\"\\\"Acquire the per-server lock with pin counting for safe reclamation.\\n\\n        The pin count prevents reclaiming a lock that another task is about to\\n        enter (e.g. between obtaining a reference and calling ``async with``).\\n        Reclamation in `_cleanup_idle_sessions` / `_release_server_lock_if_idle`\\n        only runs when pins drop to zero *and* the lock is not held.\\n        \\\"\\\"\\\"\\n        async with self._locks_guard:\\n            entry = self._server_locks.get(server_key)\\n            if entry is None:\\n                entry = _ServerLockEntry(lock=asyncio.Lock(), pins=0)\\n                self._server_locks[server_key] = entry\\n            entry[\\\"pins\\\"] += 1\\n            lock = entry[\\\"lock\\\"]\\n        try:\\n            async with lock:\\n                yield\\n        finally:\\n            await self._release_server_lock_if_idle(server_key)\\n\\n    async def _release_server_lock_if_idle(self, server_key: str):\\n        \\\"\\\"\\\"Drop the pin and, once the server is fully idle, reclaim the maps.\\n\\n        Reclamation is deliberately conservative: we only drop the lock entry\\n        (and the matching session-id counter) when *both* conditions hold \u2014\\n        pin count is zero and the server has no remaining sessions. This\\n        prevents two problems:\\n        - Churning the lock on every `get_session` call while a server is\\n          actively in use (pin count oscillates 0\u21941 between callers).\\n        - Rotating auth/session headers (which change `server_key` via\\n          `_get_server_key`) leaking per-key entries forever in long-lived\\n          processes.\\n        \\\"\\\"\\\"\\n        async with self._locks_guard:\\n            entry = self._server_locks.get(server_key)\\n            if entry is None:\\n                return\\n            entry[\\\"pins\\\"] -= 1\\n            if entry[\\\"pins\\\"] < 0:\\n                # A negative pin count means a missing acquire or a double release.\\n                # Log loudly so it surfaces in telemetry instead of being swept.\\n                await logger.awarning(\\n                    f\\\"Negative pin count ({entry['pins']}) for server_key {server_key}; \\\"\\n                    \\\"this indicates a missing _server_lock acquire or a double release.\\\",\\n                )\\n            if entry[\\\"pins\\\"] <= 0 and not entry[\\\"lock\\\"].locked() and server_key not in self.sessions_by_server:\\n                self._server_locks.pop(server_key, None)\\n                self._session_id_counters.pop(server_key, None)\\n\\n    def _next_session_id(self, server_key: str) -> str:\\n        \\\"\\\"\\\"Generate a monotonically unique session_id for *server_key*.\\n\\n        Caller must hold ``self._server_lock(server_key)`` while invoking this.\\n        The increment is otherwise unsynchronised \u2014 two concurrent callers\\n        without the lock would race on ``_session_id_counters[server_key]`` and\\n        produce colliding ids.\\n        \\\"\\\"\\\"\\n        current = self._session_id_counters.get(server_key, 0)\\n        self._session_id_counters[server_key] = current + 1\\n        return f\\\"{server_key}_{current}\\\"\\n\\n    def _sessions_for(self, server_key: str) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Return the sessions dict for *server_key* (empty dict if absent).\\n\\n        Encapsulates the ``sessions_by_server[server_key][\\\"sessions\\\"]`` shape\\n        so callers don't have to reach through the outer envelope. Handles the\\n        legacy structure (sessions stored directly under the server_key)\\n        uniformly as well.\\n        \\\"\\\"\\\"\\n        server_data = self.sessions_by_server.get(server_key)\\n        if server_data is None:\\n            return {}\\n        if isinstance(server_data, dict) and \\\"sessions\\\" in server_data:\\n            return server_data[\\\"sessions\\\"]\\n        return server_data  # legacy flat structure\\n\\n    def _start_cleanup_task(self):\\n        \\\"\\\"\\\"Start the periodic cleanup task.\\n\\n        Safe to call from __init__ (synchronous context): if no event loop is\\n        running yet we silently skip task creation.  get_session() calls this\\n        again on every invocation, so the task is always started once a loop\\n        is available.\\n        \\\"\\\"\\\"\\n        try:\\n            asyncio.get_running_loop()\\n        except RuntimeError:\\n            # No running event loop \u2014 defer until get_session() is awaited.\\n            return\\n        if self._cleanup_task is None or self._cleanup_task.done():\\n            self._cleanup_task = asyncio.create_task(self._periodic_cleanup())\\n            self._background_tasks.add(self._cleanup_task)\\n            self._cleanup_task.add_done_callback(self._background_tasks.discard)\\n\\n    async def _periodic_cleanup(self):\\n        \\\"\\\"\\\"Periodically clean up idle sessions.\\\"\\\"\\\"\\n        while True:\\n            try:\\n                await asyncio.sleep(get_session_cleanup_interval())\\n                await self._cleanup_idle_sessions()\\n            except asyncio.CancelledError:\\n                break\\n            except Exception as e:  # noqa: BLE001\\n                # Catch all recoverable errors so the cleanup loop never silently dies.\\n                # asyncio.CancelledError is excluded by the clause above and re-raised.\\n                await logger.awarning(f\\\"Error in periodic cleanup: {e}\\\")\\n\\n    async def _cleanup_idle_sessions(self):\\n        \\\"\\\"\\\"Clean up sessions that have been idle for too long.\\n\\n        Acquires the per-server lock before mutating the sessions dict so we\\n        don't race with `get_session()` \u2014 otherwise a concurrent `get_session`\\n        could finish validating a session while this task pops and cancels it,\\n        handing the caller a dead session plus a dangling refcount entry.\\n        \\\"\\\"\\\"\\n        current_time = asyncio.get_event_loop().time()\\n\\n        # Snapshot keys to avoid mutating-while-iterating.\\n        for server_key in list(self.sessions_by_server.keys()):\\n            async with self._server_lock(server_key):\\n                sessions = self._sessions_for(server_key)\\n                if not sessions and server_key not in self.sessions_by_server:\\n                    continue\\n\\n                sessions_to_remove = [\\n                    session_id\\n                    for session_id, session_info in list(sessions.items())\\n                    if current_time - session_info[\\\"last_used\\\"] > get_session_idle_timeout()\\n                ]\\n\\n                for session_id in sessions_to_remove:\\n                    await logger.ainfo(f\\\"Cleaning up idle session {session_id} for server {server_key}\\\")\\n                    await self._cleanup_session_by_id(server_key, session_id)\\n\\n                # Remove server entry if no sessions left. The counter for\\n                # this server_key is reclaimed by `_release_server_lock_if_idle`\\n                # once this lock's pin count hits zero.\\n                if not sessions:\\n                    self.sessions_by_server.pop(server_key, None)\\n\\n    def _get_server_key(self, connection_params, transport_type: str) -> str:\\n        \\\"\\\"\\\"Generate a consistent server key based on connection parameters.\\\"\\\"\\\"\\n        if transport_type == \\\"stdio\\\":\\n            if hasattr(connection_params, \\\"command\\\"):\\n                # Include command, args, and environment for uniqueness\\n                command_str = f\\\"{connection_params.command} {' '.join(connection_params.args or [])}\\\"\\n                env_str = str(sorted((connection_params.env or {}).items()))\\n                key_input = f\\\"{command_str}|{env_str}\\\"\\n                return f\\\"stdio_{hash(key_input)}\\\"\\n        elif transport_type == \\\"streamable_http\\\" and (\\n            isinstance(connection_params, dict) and \\\"url\\\" in connection_params\\n        ):\\n            # Include URL and headers for uniqueness\\n            url = connection_params[\\\"url\\\"]\\n            headers = str(sorted((connection_params.get(\\\"headers\\\", {})).items()))\\n            key_input = f\\\"{url}|{headers}\\\"\\n            return f\\\"streamable_http_{hash(key_input)}\\\"\\n\\n        # Fallback to a generic key\\n        return f\\\"{transport_type}_{hash(str(connection_params))}\\\"\\n\\n    async def invalidate_server_key(self, server_key: str) -> None:\\n        \\\"\\\"\\\"Tear down all sessions for this server and reset transport preference (e.g. remote MCP restart).\\\"\\\"\\\"\\n        self._transport_preference.pop(server_key, None)\\n        if server_key in self.sessions_by_server:\\n            server_data = self.sessions_by_server[server_key]\\n            sessions = server_data.get(\\\"sessions\\\", {}) if isinstance(server_data, dict) else server_data\\n            for sid in list(sessions.keys()):\\n                await self._cleanup_session_by_id(server_key, sid)\\n            self.sessions_by_server.pop(server_key, None)\\n        for k in list(self._session_refcount):\\n            if k[0] == server_key:\\n                self._session_refcount.pop(k, None)\\n        for ctx, pair in list(self._context_to_session.items()):\\n            if pair[0] == server_key:\\n                self._context_to_session.pop(ctx, None)\\n\\n    async def _validate_session_connectivity(self, session) -> bool:\\n        \\\"\\\"\\\"Validate that the session is actually usable by testing a simple operation.\\\"\\\"\\\"\\n        try:\\n            # Try to list tools as a connectivity test (this is a lightweight operation)\\n            # Keep the health check shorter than connection setup while honoring its configured budget.\\n            response = await asyncio.wait_for(session.list_tools(), timeout=get_session_validation_timeout())\\n        except Exception as e:  # noqa: BLE001\\n            # Any failure means the session is not safe to reuse (SDK errors, terminated session, etc.)\\n            await logger.adebug(f\\\"Session connectivity test failed: {type(e).__name__}: {e}\\\")\\n            return False\\n        else:\\n            # Validate that we got a meaningful response\\n            if response is None:\\n                await logger.adebug(\\\"Session connectivity test failed: received None response\\\")\\n                return False\\n            try:\\n                # Check if we can access the tools list (even if empty)\\n                tools = getattr(response, \\\"tools\\\", None)\\n                if tools is None:\\n                    await logger.adebug(\\\"Session connectivity test failed: no tools attribute in response\\\")\\n                    return False\\n            except (AttributeError, TypeError) as e:\\n                await logger.adebug(f\\\"Session connectivity test failed while validating response: {e}\\\")\\n                return False\\n            else:\\n                await logger.adebug(f\\\"Session connectivity test passed: found {len(tools)} tools\\\")\\n                return True\\n\\n    async def get_session(self, context_id: str, connection_params, transport_type: str):\\n        \\\"\\\"\\\"Get or create a session with improved reuse strategy.\\n\\n        The key insight is that we should reuse sessions based on the server\\n        identity (command + args for stdio, URL for Streamable HTTP) rather than the context_id.\\n        This prevents creating a new subprocess for each unique context.\\n\\n        Concurrent callers for the same server are serialized via a per-server\\n        lock. This is required to keep the `sessions` dict consistent across\\n        concurrent flow executions that share a single `MCPSessionManager`\\n        (e.g. two `MCPTools` components pointing at the same SSE URL).\\n        \\\"\\\"\\\"\\n        server_key = self._get_server_key(connection_params, transport_type)\\n\\n        # Ensure cleanup task is running. _start_cleanup_task() is a no-op if\\n        # called from __init__ before the event loop was started, so we retry\\n        # here where we are guaranteed to be inside an async context.\\n        self._start_cleanup_task()\\n\\n        async with self._server_lock(server_key):\\n            # Ensure server entry exists\\n            if server_key not in self.sessions_by_server:\\n                self.sessions_by_server[server_key] = {\\n                    \\\"sessions\\\": {},\\n                    \\\"last_cleanup\\\": asyncio.get_event_loop().time(),\\n                }\\n\\n            server_data = self.sessions_by_server[server_key]\\n            sessions = server_data[\\\"sessions\\\"]\\n\\n            # Try to find a healthy existing session.\\n            # Only sessions whose background task is still running are considered alive.\\n            # We do NOT call list_tools() here because that would add up to\\n            # (max_sessions x 3 s timeout) = ~30 s of blocking on every run_tool invocation.\\n            for session_id, session_info in list(sessions.items()):\\n                session = session_info[\\\"session\\\"]\\n                task = session_info[\\\"task\\\"]\\n\\n                if not task.done():\\n                    # Background task is still alive \u2014 treat the session as healthy.\\n                    session_info[\\\"last_used\\\"] = asyncio.get_event_loop().time()\\n                    await logger.adebug(f\\\"Reusing existing session {session_id} for server {server_key}\\\")\\n                    # record mapping & bump ref-count for backwards compatibility\\n                    self._context_to_session[context_id] = (server_key, session_id)\\n                    self._session_refcount[(server_key, session_id)] = (\\n                        self._session_refcount.get((server_key, session_id), 0) + 1\\n                    )\\n                    return session\\n                # Background task finished \u2014 session is dead, clean it up.\\n                await logger.ainfo(f\\\"Session {session_id} for server {server_key} task is done, cleaning up\\\")\\n                await self._cleanup_session_by_id(server_key, session_id)\\n\\n            # Check if we've reached the maximum number of sessions for this server\\n            if len(sessions) >= get_max_sessions_per_server():\\n                # Remove the oldest session\\n                oldest_session_id = min(sessions.keys(), key=lambda x: sessions[x][\\\"last_used\\\"])\\n                await logger.ainfo(\\n                    f\\\"Maximum sessions reached for server {server_key}, removing oldest session {oldest_session_id}\\\"\\n                )\\n                await self._cleanup_session_by_id(server_key, oldest_session_id)\\n\\n            # Create new session. Use a monotonic counter so removed sessions\\n            # don't cause id collisions with newly-created sessions.\\n            session_id = self._next_session_id(server_key)\\n            await logger.ainfo(f\\\"Creating new session {session_id} for server {server_key}\\\")\\n\\n            if transport_type == \\\"stdio\\\":\\n                session, task = await self._create_stdio_session(session_id, connection_params)\\n                actual_transport = \\\"stdio\\\"\\n            elif transport_type == \\\"streamable_http\\\":\\n                # Pass the cached transport preference if available (SSE only when last success required it)\\n                preferred_transport = self._transport_preference.get(server_key)\\n                session, task, actual_transport, sse_pref_lock = await self._create_streamable_http_session(\\n                    session_id, connection_params, preferred_transport\\n                )\\n                if actual_transport == \\\"streamable_http\\\":\\n                    self._transport_preference[server_key] = \\\"streamable_http\\\"\\n                elif sse_pref_lock:\\n                    self._transport_preference[server_key] = \\\"sse\\\"\\n            else:\\n                msg = f\\\"Unknown transport type: {transport_type}\\\"\\n                raise ValueError(msg)\\n\\n            # Store session info with the actual transport used\\n            sessions[session_id] = {\\n                \\\"session\\\": session,\\n                \\\"task\\\": task,\\n                \\\"type\\\": actual_transport,\\n                \\\"last_used\\\": asyncio.get_event_loop().time(),\\n            }\\n\\n            # register mapping & initial ref-count for the new session\\n            self._context_to_session[context_id] = (server_key, session_id)\\n            self._session_refcount[(server_key, session_id)] = 1\\n\\n            return session\\n\\n    def _abort_session_task(self, task: asyncio.Task[Any]) -> None:\\n        \\\"\\\"\\\"Cancel and reap a transport task when session creation is interrupted.\\\"\\\"\\\"\\n        if task.done():\\n            self._background_tasks.discard(task)\\n            return\\n\\n        task.cancel()\\n\\n        async def reap_task() -> None:\\n            with contextlib.suppress(asyncio.CancelledError, Exception):\\n                await task\\n            self._background_tasks.discard(task)\\n\\n        # Reap outside the cancelled caller so transport shutdown can finish.\\n        reaper = asyncio.create_task(reap_task())\\n        self._background_tasks.add(reaper)\\n        reaper.add_done_callback(self._background_tasks.discard)\\n\\n    async def _create_stdio_session(self, session_id: str, connection_params):\\n        \\\"\\\"\\\"Create a new stdio session as a background task to avoid context issues.\\\"\\\"\\\"\\n        import asyncio\\n\\n        from mcp.client.stdio import stdio_client\\n\\n        # Create a future to get the session\\n        session_future: asyncio.Future[ClientSession] = asyncio.Future()\\n\\n        async def session_task():\\n            \\\"\\\"\\\"Background task that keeps the session alive.\\\"\\\"\\\"\\n            try:\\n                async with stdio_client(connection_params) as (read, write):\\n                    session = ClientSession(read, write)\\n                    async with session:\\n                        await session.initialize()\\n                        # Signal that session is ready\\n                        session_future.set_result(session)\\n\\n                        # Keep the session alive until cancelled\\n                        import anyio\\n\\n                        event = anyio.Event()\\n                        try:\\n                            await event.wait()\\n                        except asyncio.CancelledError:\\n                            await logger.ainfo(f\\\"Session {session_id} is shutting down\\\")\\n            except Exception as e:  # noqa: BLE001\\n                if not session_future.done():\\n                    session_future.set_exception(e)\\n\\n        # Start the background task\\n        task = asyncio.create_task(session_task())\\n        self._background_tasks.add(task)\\n        task.add_done_callback(self._background_tasks.discard)\\n\\n        # Wait for the session to be ready within the configured connect budget. A cold stdio\\n        # server (e.g. a packaged interpreter importing Langflow) can take well over 20 s here.\\n        try:\\n            session = await asyncio.wait_for(session_future, timeout=get_session_init_timeout())\\n        except asyncio.CancelledError:\\n            self._abort_session_task(task)\\n            raise\\n        except asyncio.TimeoutError as timeout_err:\\n            # Clean up the failed task\\n            if not task.done():\\n                task.cancel()\\n                import contextlib\\n\\n                with contextlib.suppress(asyncio.CancelledError):\\n                    await task\\n            self._background_tasks.discard(task)\\n            msg = f\\\"Timeout waiting for STDIO session {session_id} to initialize\\\"\\n            await logger.aerror(msg)\\n            raise ValueError(msg) from timeout_err\\n\\n        return session, task\\n\\n    async def _create_streamable_http_session(\\n        self, session_id: str, connection_params, preferred_transport: str | None = None\\n    ):\\n        \\\"\\\"\\\"Create Streamable HTTP session with selective SSE fallback (background task lifecycle).\\n\\n        SSE is attempted only when Streamable HTTP fails with an endpoint/transport mismatch signal\\n        (e.g. HTTP 404/405/406), not for transient outages (connection reset, TaskGroup teardown, etc.).\\n\\n        Returns:\\n            tuple: (session, task, transport_used, sse_preference_lock) where sse_preference_lock is True\\n            iff SSE connected successfully and the server key should prefer legacy SSE in the future.\\n        \\\"\\\"\\\"\\n        import asyncio\\n\\n        from mcp.client.sse import sse_client\\n        from mcp.client.streamable_http import streamablehttp_client\\n\\n        session_future: asyncio.Future[ClientSession] = asyncio.Future()\\n        used_transport: list[str] = []\\n        sse_preference_locked: list[bool] = [False]\\n\\n        verify_ssl = connection_params.get(\\\"verify_ssl\\\", True)\\n\\n        def custom_httpx_factory(\\n            headers: dict[str, str] | None = None,\\n            timeout: httpx.Timeout | None = None,\\n            auth: httpx.Auth | None = None,\\n        ) -> httpx.AsyncClient:\\n            return create_mcp_http_client_with_ssl_option(\\n                headers=headers, timeout=timeout, auth=auth, verify_ssl=verify_ssl\\n            )\\n\\n        async def session_task():\\n            \\\"\\\"\\\"Background task that keeps the session alive.\\\"\\\"\\\"\\n            streamable_error = None\\n\\n            if preferred_transport != \\\"sse\\\":\\n                for attempt in range(STREAMABLE_HTTP_CONNECT_ATTEMPTS):\\n                    try:\\n                        await logger.adebug(\\n                            f\\\"Attempting Streamable HTTP connection for session {session_id} \\\"\\n                            f\\\"(attempt {attempt + 1}/{STREAMABLE_HTTP_CONNECT_ATTEMPTS})\\\"\\n                        )\\n                        async with streamablehttp_client(\\n                            url=connection_params[\\\"url\\\"],\\n                            headers=connection_params[\\\"headers\\\"],\\n                            timeout=connection_params[\\\"timeout_seconds\\\"],\\n                            httpx_client_factory=custom_httpx_factory,\\n                        ) as (read, write, _):\\n                            session = ClientSession(read, write)\\n                            async with session:\\n                                await asyncio.wait_for(session.initialize(), timeout=2.0)\\n                                used_transport.append(\\\"streamable_http\\\")\\n                                await logger.ainfo(f\\\"Session {session_id} connected via Streamable HTTP\\\")\\n                                session_future.set_result(session)\\n\\n                                import anyio\\n\\n                                event = anyio.Event()\\n                                try:\\n                                    await event.wait()\\n                                except asyncio.CancelledError:\\n                                    await logger.ainfo(f\\\"Session {session_id} (Streamable HTTP) is shutting down\\\")\\n                        return  # noqa: TRY300\\n                    except asyncio.CancelledError:\\n                        raise\\n                    except Exception as e:  # noqa: BLE001\\n                        if _is_transient_streamable_http_error(e) and attempt < STREAMABLE_HTTP_CONNECT_ATTEMPTS - 1:\\n                            await logger.awarning(\\n                                f\\\"Streamable HTTP transient failure for session {session_id} \\\"\\n                                f\\\"(attempt {attempt + 1}): {e}; retrying...\\\"\\n                            )\\n                            await asyncio.sleep(STREAMABLE_HTTP_RETRY_BASE_DELAY_SEC * (attempt + 1))\\n                            continue\\n                        streamable_error = e\\n                        break\\n\\n                if streamable_error is not None:\\n                    if _is_transient_streamable_http_error(streamable_error):\\n                        await logger.aerror(\\n                            f\\\"Streamable HTTP failed after {STREAMABLE_HTTP_CONNECT_ATTEMPTS} attempt(s) \\\"\\n                            f\\\"for session {session_id}: {streamable_error}. Not attempting SSE fallback.\\\"\\n                        )\\n                        if not session_future.done():\\n                            session_future.set_exception(streamable_error)\\n                        return\\n                    if not _should_attempt_sse_after_streamable_failure(streamable_error):\\n                        if not session_future.done():\\n                            session_future.set_exception(streamable_error)\\n                        return\\n                    await logger.awarning(\\n                        f\\\"Streamable HTTP failed for session {session_id}: {streamable_error}. \\\"\\n                        \\\"Trying SSE (endpoint may require legacy transport)...\\\"\\n                    )\\n            else:\\n                await logger.adebug(f\\\"Skipping Streamable HTTP for session {session_id}, using cached SSE preference\\\")\\n\\n            # SSE path: preferred mode, or Streamable indicated legacy transport\\n            try:\\n                await logger.adebug(f\\\"Attempting SSE connection for session {session_id}\\\")\\n                sse_read_timeout = connection_params.get(\\\"sse_read_timeout_seconds\\\", 30)\\n\\n                async with sse_client(\\n                    connection_params[\\\"url\\\"],\\n                    connection_params[\\\"headers\\\"],\\n                    connection_params[\\\"timeout_seconds\\\"],\\n                    sse_read_timeout,\\n                    httpx_client_factory=custom_httpx_factory,\\n                ) as (read, write):\\n                    session = ClientSession(read, write)\\n                    async with session:\\n                        await session.initialize()\\n                        used_transport.append(\\\"sse\\\")\\n                        sse_preference_locked[0] = True\\n                        fallback_msg = \\\" (fallback)\\\" if streamable_error else \\\" (preferred)\\\"\\n                        await logger.ainfo(f\\\"Session {session_id} connected via SSE{fallback_msg}\\\")\\n                        if not session_future.done():\\n                            session_future.set_result(session)\\n\\n                        import anyio\\n\\n                        event = anyio.Event()\\n                        try:\\n                            await event.wait()\\n                        except asyncio.CancelledError:\\n                            await logger.ainfo(f\\\"Session {session_id} (SSE) is shutting down\\\")\\n            except Exception as sse_error:  # noqa: BLE001\\n                if streamable_error:\\n                    await logger.aerror(\\n                        f\\\"Both Streamable HTTP and SSE failed for session {session_id}. \\\"\\n                        f\\\"Streamable HTTP error: {streamable_error}. SSE error: {sse_error}\\\"\\n                    )\\n                    if not session_future.done():\\n                        session_future.set_exception(\\n                            ValueError(\\n                                f\\\"Failed to connect via Streamable HTTP ({streamable_error}) or SSE ({sse_error})\\\"\\n                            )\\n                        )\\n                else:\\n                    await logger.aerror(f\\\"SSE connection failed for session {session_id}: {sse_error}\\\")\\n                    if not session_future.done():\\n                        session_future.set_exception(ValueError(f\\\"Failed to connect via SSE: {sse_error}\\\"))\\n\\n        task = asyncio.create_task(session_task())\\n        self._background_tasks.add(task)\\n        task.add_done_callback(self._background_tasks.discard)\\n\\n        try:\\n            session = await asyncio.wait_for(session_future, timeout=get_session_init_timeout())\\n            if used_transport:\\n                transport_used = used_transport[0]\\n                await logger.ainfo(f\\\"Session {session_id} successfully established using {transport_used}\\\")\\n                return session, task, transport_used, sse_preference_locked[0]\\n            msg = f\\\"Session {session_id} established but transport not recorded\\\"\\n            raise ValueError(msg)\\n        except asyncio.CancelledError:\\n            self._abort_session_task(task)\\n            raise\\n        except asyncio.TimeoutError as timeout_err:\\n            if not task.done():\\n                task.cancel()\\n                with contextlib.suppress(asyncio.CancelledError):\\n                    await task\\n            self._background_tasks.discard(task)\\n            msg = f\\\"Timeout waiting for Streamable HTTP/SSE session {session_id} to initialize\\\"\\n            await logger.aerror(msg)\\n            raise ValueError(msg) from timeout_err\\n\\n    async def _cleanup_session_by_id(self, server_key: str, session_id: str):\\n        \\\"\\\"\\\"Clean up a specific session by server key and session ID.\\n\\n        Safe against concurrent cleanup of the same session: we `pop` the entry\\n        up front so two concurrent callers don't both try to cancel the same\\n        task or `del` the same key (which raised `KeyError: 'streamable_http_..._0'`\\n        previously under concurrent flow execution).\\n        \\\"\\\"\\\"\\n        sessions = self._sessions_for(server_key)\\n        if not sessions and server_key not in self.sessions_by_server:\\n            return\\n\\n        # Atomically remove the session entry; only the caller that wins this\\n        # pop performs the actual teardown. Concurrent callers get None and\\n        # return early instead of racing on del/task.cancel().\\n        session_info = sessions.pop(session_id, None)\\n        if session_info is None:\\n            return\\n\\n        try:\\n            # First try to properly close the session if it exists\\n            if \\\"session\\\" in session_info:\\n                session = session_info[\\\"session\\\"]\\n\\n                # Try async close first (aclose method)\\n                if hasattr(session, \\\"aclose\\\"):\\n                    try:\\n                        await session.aclose()\\n                        await logger.adebug(\\\"Successfully closed session %s using aclose()\\\", session_id)\\n                    except Exception as e:  # noqa: BLE001\\n                        await logger.adebug(\\\"Error closing session %s with aclose(): %s\\\", session_id, e)\\n\\n                # If no aclose, try regular close method\\n                elif hasattr(session, \\\"close\\\"):\\n                    try:\\n                        # Check if close() is awaitable using inspection\\n                        if inspect.iscoroutinefunction(session.close):\\n                            # It's an async method\\n                            await session.close()\\n                            await logger.adebug(\\\"Successfully closed session %s using async close()\\\", session_id)\\n                        else:\\n                            # Try calling it and check if result is awaitable\\n                            close_result = session.close()\\n                            if inspect.isawaitable(close_result):\\n                                await close_result\\n                                await logger.adebug(\\n                                    \\\"Successfully closed session %s using awaitable close()\\\", session_id\\n                                )\\n                            else:\\n                                # It's a synchronous close\\n                                await logger.adebug(\\\"Successfully closed session %s using sync close()\\\", session_id)\\n                    except Exception as e:  # noqa: BLE001\\n                        await logger.adebug(\\\"Error closing session %s with close(): %s\\\", session_id, e)\\n\\n            # Cancel the background task which will properly close the session\\n            if \\\"task\\\" in session_info:\\n                task = session_info[\\\"task\\\"]\\n                if not task.done():\\n                    task.cancel()\\n                    try:\\n                        await task\\n                    except asyncio.CancelledError:\\n                        await logger.ainfo(f\\\"Cancelled task for session {session_id}\\\")\\n        except Exception as e:  # noqa: BLE001\\n            # Teardown is load-bearing: MCP transports (stdio subprocess, SSE,\\n            # streamable HTTP) all raise their own exception hierarchies on\\n            # shutdown, and a leak on cleanup is far worse than a swallowed\\n            # error. Log and continue rather than propagating.\\n            await logger.awarning(f\\\"Error cleaning up session {session_id}: {e}\\\")\\n\\n    async def cleanup_all(self):\\n        \\\"\\\"\\\"Clean up all sessions.\\\"\\\"\\\"\\n        # Cancel periodic cleanup task\\n        if self._cleanup_task and not self._cleanup_task.done():\\n            self._cleanup_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._cleanup_task\\n\\n        # Clean up all sessions\\n        for server_key in list(self.sessions_by_server.keys()):\\n            for session_id in list(self._sessions_for(server_key).keys()):\\n                await self._cleanup_session_by_id(server_key, session_id)\\n\\n        # Clear the sessions_by_server structure completely\\n        self.sessions_by_server.clear()\\n\\n        # Clear compatibility maps\\n        self._context_to_session.clear()\\n        self._session_refcount.clear()\\n\\n        # Reclaim per-server lock and counter maps. Safe here because\\n        # cleanup_all is a shutdown/reset operation; no other manager state\\n        # should be in use past this point.\\n        async with self._locks_guard:\\n            self._server_locks.clear()\\n            self._session_id_counters.clear()\\n\\n        # Clear all background tasks\\n        for task in list(self._background_tasks):\\n            if not task.done():\\n                task.cancel()\\n                with contextlib.suppress(asyncio.CancelledError):\\n                    await task\\n\\n        # Give a bit more time for subprocess transports to clean up\\n        # This helps prevent the BaseSubprocessTransport.__del__ warnings\\n        await asyncio.sleep(0.5)\\n\\n    async def _cleanup_session(self, context_id: str):\\n        \\\"\\\"\\\"Backward-compat cleanup by context_id.\\n\\n        Decrements the ref-count for the session used by *context_id* and only\\n        tears the session down when the last context that references it goes\\n        away.\\n\\n        Acquires the per-server lock so concurrent `get_session()` calls don't\\n        observe a half-torn-down session (e.g. returning a ClientSession whose\\n        background task was just cancelled out from under them).\\n\\n        Uses a compare-and-swap on `_context_to_session[context_id]` before\\n        popping it: if a concurrent `get_session()` has re-pointed the same\\n        context at a *different* server (e.g. a component reconnecting to a\\n        new MCP URL while the old disconnect is in flight), we must not wipe\\n        out the fresh mapping \u2014 otherwise the new session leaks. The per-\\n        server lock doesn't cover this case because the new and old sessions\\n        live under different server_keys, so the two operations run in\\n        parallel.\\n        \\\"\\\"\\\"\\n        mapping = self._context_to_session.get(context_id)\\n        if not mapping:\\n            await logger.adebug(f\\\"No session mapping found for context_id {context_id}\\\")\\n            return\\n\\n        server_key, session_id = mapping\\n        async with self._server_lock(server_key):\\n            ref_key = (server_key, session_id)\\n            remaining = self._session_refcount.get(ref_key, 1) - 1\\n\\n            if remaining <= 0:\\n                await self._cleanup_session_by_id(server_key, session_id)\\n                self._session_refcount.pop(ref_key, None)\\n            else:\\n                self._session_refcount[ref_key] = remaining\\n\\n            # CAS: only drop the context->session mapping if it still points\\n            # at the session we just cleaned up. The get() and pop() below run\\n            # synchronously with no `await` between them, so no other coroutine\\n            # can interleave and re-point the mapping after our check.\\n            if self._context_to_session.get(context_id) == (server_key, session_id):\\n                self._context_to_session.pop(context_id, None)\\n\\n\\nclass MCPStdioClient:\\n    def __init__(self, component_cache=None, tool_execution_timeout: float | None = None):\\n        self.session: ClientSession | None = None\\n        self._connection_params = None\\n        self._connected = False\\n        self._session_context: str | None = None\\n        self._component_cache = component_cache\\n        self._tool_execution_timeout = _resolve_mcp_tool_execution_timeout(tool_execution_timeout)\\n\\n    async def _connect_to_server(\\n        self,\\n        command_str: str,\\n        env: dict[str, str] | None = None,\\n        *,\\n        current_user_id: str | UUID | None = None,\\n        headers: dict[str, str] | None = None,\\n    ) -> list[StructuredTool]:\\n        \\\"\\\"\\\"Connect to MCP server using stdio transport (SDK style).\\n\\n        The server process is launched **without a shell** (``shell=False``\\n        semantics): ``command_str`` is tokenized with :func:`shlex.split` and\\n        the resulting executable + arguments are passed to\\n        :class:`~mcp.StdioServerParameters` directly.  The MCP SDK then execs\\n        the process via ``anyio.open_process`` on POSIX and\\n        ``create_windows_process`` on Windows -- the latter resolving ``.cmd`` /\\n        ``.bat`` / ``.exe`` wrappers (e.g. ``npx.cmd``) through ``shutil.which``\\n        -- so no ``bash -c`` / ``cmd /c`` wrapper is required on any platform.\\n\\n        Removing the shell wrapper structurally eliminates the entire class of\\n        injection vectors that depend on a shell interpreter starting up:\\n        shell metacharacters, ``IFS`` word-splitting, ``CDPATH`` redirection,\\n        ``BASH_ENV`` / ``ENV`` / ``BASH_FUNC_*`` startup injection, and\\n        ``PS4`` / ``SHELLOPTS`` xtrace abuse.  None of those can fire because no\\n        shell is ever spawned.  The :func:`_validate_mcp_stdio_env` backstop\\n        still rejects loader and interpreter env vars (``LD_PRELOAD``,\\n        ``DYLD_*``, ``GCONV_PATH``, ``PYTHONPATH``, ``NODE_OPTIONS``, ...) which\\n        remain dangerous regardless of the shell because they are honored by the\\n        dynamic linker or the target interpreter itself.\\n        \\\"\\\"\\\"\\n        from mcp import StdioServerParameters\\n\\n        command_parts = shlex.split(command_str)\\n        if not command_parts:\\n            msg = \\\"MCP stdio command is empty\\\"\\n            raise ValueError(msg)\\n\\n        command, args = command_parts[0], command_parts[1:]\\n        # Final pre-spawn enforcement. This must remain here even though API and\\n        # component call sites validate earlier: callers can instantiate this client\\n        # directly, and no unvalidated argv or tenant-controlled environment may reach\\n        # StdioServerParameters.\\n        validate_mcp_stdio_config(command, args, env)\\n        # Component headers are validated as HTTP data and appended as structured\\n        # argv only after command policy succeeds. Cookie/signature values may\\n        # legitimately contain shell-looking punctuation, which is inert because\\n        # the process is launched without a shell.\\n        final_args = _inject_mcp_stdio_headers(args, _process_headers(headers))\\n        safe_env = _validate_mcp_stdio_env(env)\\n        if AGENTIC_MCP_MODULE in command or any(AGENTIC_MCP_MODULE in arg for arg in args):\\n            if not current_user_id:\\n                msg = \\\"The Langflow agentic MCP server requires an authenticated user context and cannot be used here.\\\"\\n                raise ValueError(msg)\\n            # Bind the trusted identity only after validating the tenant-controlled\\n            # environment. Supplying this key in the config is rejected above.\\n            safe_env = {**safe_env, AGENTIC_USER_ID_ENV_VAR: str(current_user_id)}\\n        env_data: dict[str, str] = {\\\"DEBUG\\\": \\\"true\\\", \\\"PATH\\\": os.environ[\\\"PATH\\\"], **safe_env}\\n\\n        # shell=False: exec the binary directly with structured args. The MCP SDK\\n        # abstracts the platform differences (POSIX exec vs. Windows executable\\n        # resolution), so identical parameters work on every OS and no shell\\n        # interpreter is ever interposed between Langflow and the server process.\\n        server_params = StdioServerParameters(\\n            command=command,\\n            args=final_args,\\n            env=env_data,\\n        )\\n\\n        # Store connection parameters for later use in run_tool\\n        self._connection_params = server_params\\n\\n        # If no session context is set, create a default one\\n        if not self._session_context:\\n            # Generate a fallback context based on connection parameters\\n            import uuid\\n\\n            param_hash = uuid.uuid4().hex[:8]\\n            self._session_context = f\\\"default_{param_hash}\\\"\\n\\n        # Get or create a persistent session\\n        session = await self._get_or_create_session()\\n        response = await session.list_tools()\\n        self._connected = True\\n        return response.tools\\n\\n    async def connect_to_server(\\n        self,\\n        command_str: str,\\n        env: dict[str, str] | None = None,\\n        *,\\n        current_user_id: str | UUID | None = None,\\n        headers: dict[str, str] | None = None,\\n    ) -> list[StructuredTool]:\\n        \\\"\\\"\\\"Connect to MCP server using stdio transport (SDK style).\\\"\\\"\\\"\\n        return await asyncio.wait_for(\\n            self._connect_to_server(command_str, env, current_user_id=current_user_id, headers=headers),\\n            timeout=get_settings_service().settings.mcp_server_timeout,\\n        )\\n\\n    def set_session_context(self, context_id: str):\\n        \\\"\\\"\\\"Set the session context (e.g., flow_id + user_id + session_id).\\\"\\\"\\\"\\n        self._session_context = context_id\\n\\n    def _get_session_manager(self) -> MCPSessionManager:\\n        \\\"\\\"\\\"Get or create session manager from component cache.\\\"\\\"\\\"\\n        if not self._component_cache:\\n            # Fallback to instance-level session manager if no cache\\n            if not hasattr(self, \\\"_session_manager\\\"):\\n                self._session_manager = MCPSessionManager()\\n            return self._session_manager\\n\\n        from lfx.services.cache.utils import CacheMiss\\n\\n        session_manager = self._component_cache.get(\\\"mcp_session_manager\\\")\\n        if isinstance(session_manager, CacheMiss):\\n            session_manager = MCPSessionManager()\\n            self._component_cache.set(\\\"mcp_session_manager\\\", session_manager)\\n        return session_manager\\n\\n    async def _get_or_create_session(self) -> ClientSession:\\n        \\\"\\\"\\\"Get or create a persistent session for the current context.\\\"\\\"\\\"\\n        if not self._session_context or not self._connection_params:\\n            msg = \\\"Session context and connection params must be set\\\"\\n            raise ValueError(msg)\\n\\n        # Use cached session manager to get/create persistent session\\n        session_manager = self._get_session_manager()\\n        return await session_manager.get_session(self._session_context, self._connection_params, \\\"stdio\\\")\\n\\n    def _tool_span_attributes(self, tool_name: str) -> dict[str, str]:\\n        \\\"\\\"\\\"Identifiers for the span: which tool, on which server, over which transport.\\n\\n        The server is the command and its first argument, basenames only. That is the part that\\n        says which server this is (``uvx some-mcp-server``, ``python server.py``); later flags\\n        are left out because they can carry tokens, and the span boundary is identifiers only.\\n        \\\"\\\"\\\"\\n        attributes = {\\\"mcp.tool.name\\\": tool_name, \\\"mcp.transport\\\": \\\"stdio\\\"}\\n        command = getattr(self._connection_params, \\\"command\\\", None)\\n        if command:\\n            args = getattr(self._connection_params, \\\"args\\\", None) or []\\n            server = Path(command).name\\n            if args:\\n                server = f\\\"{server} {Path(args[0]).name}\\\"\\n            attributes[\\\"mcp.server\\\"] = server\\n        return attributes\\n\\n    async def run_tool(self, tool_name: str, arguments: dict[str, Any], timeout: float | None = None) -> Any:  # noqa: ASYNC109\\n        \\\"\\\"\\\"Run the tool, with one application span covering the call and any retries.\\\"\\\"\\\"\\n        with outbound_call_span(MCP_TOOL_SPAN_NAME, self._tool_span_attributes(tool_name)) as span:\\n            result = await self._run_tool(tool_name, arguments, timeout)\\n            # MCP reports a failed tool as isError on the result rather than by raising, and the\\n            # caller only converts that to an exception after this span has closed. Without this\\n            # a failed call exports as a success and the outbound error rate is always zero.\\n            if getattr(result, \\\"isError\\\", False):\\n                span.record_error(\\\"ToolError\\\")\\n            return result\\n\\n    async def _run_tool(\\n        self,\\n        tool_name: str,\\n        arguments: dict[str, Any],\\n        timeout: float | None = None,  # noqa: ASYNC109\\n    ) -> Any:\\n        \\\"\\\"\\\"Run a tool with the given arguments using context-specific session.\\n\\n        Args:\\n            tool_name: Name of the tool to run\\n            arguments: Dictionary of arguments to pass to the tool\\n            timeout: Optional timeout in seconds. If not provided, uses the client's configured timeout.\\n\\n        Returns:\\n            The result of the tool execution\\n\\n        Raises:\\n            ValueError: If session is not initialized or tool execution fails\\n        \\\"\\\"\\\"\\n        if not self._connected or not self._connection_params:\\n            msg = \\\"Session not initialized or disconnected. Call connect_to_server first.\\\"\\n            raise ValueError(msg)\\n\\n        # If no session context is set, create a default one\\n        if not self._session_context:\\n            # Generate a fallback context based on connection parameters\\n            import uuid\\n\\n            param_hash = uuid.uuid4().hex[:8]\\n            self._session_context = f\\\"default_{param_hash}\\\"\\n\\n        # Use provided timeout or fall back to client's configured timeout\\n        effective_timeout = timeout if timeout is not None else self._tool_execution_timeout\\n\\n        max_retries = 2\\n        last_error_type = None\\n        last_error: Exception | None = None\\n\\n        for attempt in range(max_retries):\\n            try:\\n                await logger.adebug(f\\\"Attempting to run tool '{tool_name}' (attempt {attempt + 1}/{max_retries})\\\")\\n                # Get or create persistent session\\n                session = await self._get_or_create_session()\\n\\n                result = await asyncio.wait_for(\\n                    session.call_tool(tool_name, arguments=arguments),\\n                    timeout=effective_timeout,\\n                )\\n            except Exception as e:\\n                last_error = e\\n                current_error_type = type(e).__name__\\n                await logger.awarning(f\\\"Tool '{tool_name}' failed on attempt {attempt + 1}: {current_error_type} - {e}\\\")\\n\\n                # Import specific MCP error types for detection\\n                try:\\n                    is_closed_resource_error = isinstance(e, ClosedResourceError)\\n                    is_mcp_connection_error = isinstance(e, McpError) and \\\"Connection closed\\\" in str(e)\\n                except ImportError:\\n                    is_closed_resource_error = \\\"ClosedResourceError\\\" in str(type(e))\\n                    is_mcp_connection_error = \\\"Connection closed\\\" in str(e)\\n\\n                # A server that answered with a status is not a transport fault: the branches\\n                # below match none of it, so it used to reach the caller as the raw TaskGroup\\n                # string. Retrying is pointless \u2014 the same call gets the same answer.\\n                if not (is_closed_resource_error or is_mcp_connection_error) and extract_http_status(e) is not None:\\n                    msg = describe_mcp_tool_failure(tool_name, None, e)\\n                    await logger.aerror(msg)\\n                    self._connected = False\\n                    raise ValueError(msg) from e\\n\\n                # Detect timeout errors\\n                is_timeout_error = isinstance(e, asyncio.TimeoutError | TimeoutError)\\n\\n                # If we're getting the same error type repeatedly, don't retry\\n                if last_error_type == current_error_type and attempt > 0:\\n                    await logger.aerror(f\\\"Repeated {current_error_type} error for tool '{tool_name}', not retrying\\\")\\n                    break\\n\\n                last_error_type = current_error_type\\n\\n                # If it's a connection error (ClosedResourceError or MCP connection closed) and we have retries left\\n                if (is_closed_resource_error or is_mcp_connection_error) and attempt < max_retries - 1:\\n                    await logger.awarning(\\n                        f\\\"MCP session connection issue for tool '{tool_name}', retrying with fresh session...\\\"\\n                    )\\n                    # Clean up the dead session\\n                    if self._session_context:\\n                        session_manager = self._get_session_manager()\\n                        await session_manager._cleanup_session(self._session_context)\\n                    # Add a small delay before retry\\n                    await asyncio.sleep(0.5)\\n                    continue\\n\\n                # If it's a timeout error and we have retries left, try once more\\n                if is_timeout_error and attempt < max_retries - 1:\\n                    await logger.awarning(f\\\"Tool '{tool_name}' timed out, retrying...\\\")\\n                    # Don't clean up session for timeouts, might just be a slow response\\n                    await asyncio.sleep(1.0)\\n                    continue\\n\\n                # For other errors or no retries left, handle as before\\n                if (\\n                    isinstance(e, ConnectionError | TimeoutError | OSError | ValueError)\\n                    or is_closed_resource_error\\n                    or is_mcp_connection_error\\n                    or is_timeout_error\\n                ):\\n                    msg = describe_mcp_tool_failure(tool_name, None, e)\\n                    await logger.aerror(msg)\\n                    # Clean up failed session from cache\\n                    if self._session_context and self._component_cache:\\n                        cache_key = f\\\"mcp_session_stdio_{self._session_context}\\\"\\n                        self._component_cache.delete(cache_key)\\n                    self._connected = False\\n                    raise ValueError(msg) from e\\n                # Re-raise unexpected errors\\n                raise\\n            else:\\n                await logger.adebug(f\\\"Tool '{tool_name}' completed successfully\\\")\\n                return result\\n\\n        # This should never be reached due to the exception handling above\\n        msg = f\\\"Failed to run tool '{tool_name}': Maximum retries exceeded with repeated {last_error_type} errors\\\"\\n        await logger.aerror(msg)\\n        raise ValueError(msg) from last_error\\n\\n    async def disconnect(self):\\n        \\\"\\\"\\\"Properly close the connection and clean up resources.\\\"\\\"\\\"\\n        # For stdio transport, there is no remote session to terminate explicitly\\n        # The session cleanup happens when the background task is cancelled\\n\\n        # Clean up local session using the session manager\\n        if self._session_context:\\n            session_manager = self._get_session_manager()\\n            await session_manager._cleanup_session(self._session_context)\\n\\n        # Reset local state\\n        self.session = None\\n        self._connection_params = None\\n        self._connected = False\\n        self._session_context = None\\n\\n    async def __aenter__(self):\\n        return self\\n\\n    async def __aexit__(self, exc_type, exc_val, exc_tb):\\n        await self.disconnect()\\n\\n\\nclass MCPStreamableHttpClient:\\n    def __init__(self, component_cache=None, tool_execution_timeout: float | None = None):\\n        self.session: ClientSession | None = None\\n        self._connection_params = None\\n        self._connected = False\\n        self._session_context: str | None = None\\n        self._component_cache = component_cache\\n        self._tool_execution_timeout = _resolve_mcp_tool_execution_timeout(tool_execution_timeout)\\n\\n    def _get_session_manager(self) -> MCPSessionManager:\\n        \\\"\\\"\\\"Get or create session manager from component cache.\\\"\\\"\\\"\\n        if not self._component_cache:\\n            # Fallback to instance-level session manager if no cache\\n            if not hasattr(self, \\\"_session_manager\\\"):\\n                self._session_manager = MCPSessionManager()\\n            return self._session_manager\\n\\n        from lfx.services.cache.utils import CacheMiss\\n\\n        session_manager = self._component_cache.get(\\\"mcp_session_manager\\\")\\n        if isinstance(session_manager, CacheMiss):\\n            session_manager = MCPSessionManager()\\n            self._component_cache.set(\\\"mcp_session_manager\\\", session_manager)\\n        return session_manager\\n\\n    async def validate_url(self, url: str | None) -> tuple[bool, str]:\\n        \\\"\\\"\\\"Validate the Streamable HTTP URL before attempting connection.\\\"\\\"\\\"\\n        try:\\n            parsed = urlparse(url)\\n            if not parsed.scheme or not parsed.netloc:\\n                return False, \\\"Invalid URL format. Must include scheme (http/https) and host.\\\"\\n        except (ValueError, OSError) as e:\\n            return False, f\\\"URL validation error: {e!s}\\\"\\n        return True, \\\"\\\"\\n\\n    async def _connect_to_server(\\n        self,\\n        url: str | None,\\n        headers: dict[str, str] | None = None,\\n        timeout_seconds: int = 30,\\n        sse_read_timeout_seconds: int = 30,\\n        *,\\n        verify_ssl: bool = True,\\n    ) -> list[StructuredTool]:\\n        \\\"\\\"\\\"Connect to MCP server using Streamable HTTP transport with SSE fallback (SDK style).\\\"\\\"\\\"\\n        # Validate and sanitize headers early\\n        validated_headers = _process_headers(headers)\\n\\n        if url is None:\\n            msg = \\\"URL is required for StreamableHTTP or SSE mode\\\"\\n            raise ValueError(msg)\\n\\n        # Only validate URL if we don't have a cached session\\n        # This avoids expensive HTTP validation calls when reusing sessions\\n        if not self._connected or not self._connection_params:\\n            is_valid, error_msg = await self.validate_url(url)\\n            if not is_valid:\\n                msg = f\\\"Invalid Streamable HTTP or SSE URL ({url}): {error_msg}\\\"\\n                raise ValueError(msg)\\n            # Store connection parameters for later use in run_tool\\n            # Include SSE read timeout for fallback and SSL verification option\\n            self._connection_params = {\\n                \\\"url\\\": url,\\n                \\\"headers\\\": validated_headers,\\n                \\\"timeout_seconds\\\": timeout_seconds,\\n                \\\"sse_read_timeout_seconds\\\": sse_read_timeout_seconds,\\n                \\\"verify_ssl\\\": verify_ssl,\\n            }\\n        elif headers:\\n            self._connection_params[\\\"headers\\\"] = validated_headers\\n\\n        # If no session context is set, create a default one\\n        if not self._session_context:\\n            # Generate a fallback context based on connection parameters\\n            import uuid\\n\\n            param_hash = uuid.uuid4().hex[:8]\\n            self._session_context = f\\\"default_http_{param_hash}\\\"\\n\\n        # Get or create a persistent session (will try Streamable HTTP, then selective SSE fallback)\\n        session = await self._get_or_create_session()\\n        try:\\n            response = await session.list_tools()\\n        except Exception:\\n            self._connected = False\\n            if self._connection_params:\\n                session_manager = self._get_session_manager()\\n                sk = session_manager._get_server_key(self._connection_params, \\\"streamable_http\\\")\\n                await session_manager.invalidate_server_key(sk)\\n            raise\\n        self._connected = True\\n        return response.tools\\n\\n    async def connect_to_server(\\n        self,\\n        url: str,\\n        headers: dict[str, str] | None = None,\\n        sse_read_timeout_seconds: int = 30,\\n        *,\\n        verify_ssl: bool = True,\\n    ) -> list[StructuredTool]:\\n        \\\"\\\"\\\"Connect to MCP server using Streamable HTTP with SSE fallback transport (SDK style).\\\"\\\"\\\"\\n        return await asyncio.wait_for(\\n            self._connect_to_server(\\n                url, headers, sse_read_timeout_seconds=sse_read_timeout_seconds, verify_ssl=verify_ssl\\n            ),\\n            timeout=get_settings_service().settings.mcp_server_timeout,\\n        )\\n\\n    def set_session_context(self, context_id: str):\\n        \\\"\\\"\\\"Set the session context (e.g., flow_id + user_id + session_id).\\\"\\\"\\\"\\n        self._session_context = context_id\\n\\n    async def _get_or_create_session(self) -> ClientSession:\\n        \\\"\\\"\\\"Get or create a persistent session for the current context.\\\"\\\"\\\"\\n        if not self._session_context or not self._connection_params:\\n            msg = \\\"Session context and params must be set\\\"\\n            raise ValueError(msg)\\n\\n        # Use cached session manager to get/create persistent session\\n        session_manager = self._get_session_manager()\\n        # Cache session so we can access server-assigned session_id later for DELETE\\n        self.session = await session_manager.get_session(\\n            self._session_context, self._connection_params, \\\"streamable_http\\\"\\n        )\\n        return self.session\\n\\n    async def _terminate_remote_session(self) -> None:\\n        \\\"\\\"\\\"Attempt to explicitly terminate the remote MCP session via HTTP DELETE (best-effort).\\\"\\\"\\\"\\n        # Only relevant for Streamable HTTP or SSE transport\\n        if not self._connection_params or \\\"url\\\" not in self._connection_params:\\n            return\\n\\n        url: str = self._connection_params[\\\"url\\\"]\\n\\n        # Retrieve session id from the underlying SDK if exposed\\n        session_id = None\\n        if getattr(self, \\\"session\\\", None) is not None:\\n            # Common attributes in MCP python SDK: `session_id` or `id`\\n            session_id = getattr(self.session, \\\"session_id\\\", None) or getattr(self.session, \\\"id\\\", None)\\n\\n        headers: dict[str, str] = dict(self._connection_params.get(\\\"headers\\\", {}))\\n        if session_id:\\n            headers[\\\"Mcp-Session-Id\\\"] = str(session_id)\\n\\n        try:\\n            async with httpx.AsyncClient(timeout=5.0) as client:\\n                await client.delete(url, headers=headers)\\n        except Exception as e:  # noqa: BLE001\\n            # DELETE is advisory\u2014log and continue\\n            logger.debug(f\\\"Unable to send session DELETE to '{url}': {e}\\\")\\n\\n    def _tool_span_attributes(self, tool_name: str) -> dict[str, str]:\\n        \\\"\\\"\\\"Identifiers for the span: which tool, on which server, over which transport.\\n\\n        The transport is read from the session manager rather than hardcoded, because this class\\n        also serves SSE: ``MCPSseClient`` is an alias for it, and a streamable-http server can\\n        fall back to SSE at runtime. A literal would label those calls streamable_http.\\n\\n        The server is the host, never the full URL: a URL can carry credentials in its query\\n        string, which is the leak the export boundary exists to strip.\\n        \\\"\\\"\\\"\\n        attributes = {\\\"mcp.tool.name\\\": tool_name, \\\"mcp.transport\\\": \\\"streamable_http\\\"}\\n        params = self._connection_params\\n        if isinstance(params, dict) and params.get(\\\"url\\\"):\\n            session_manager = self._get_session_manager()\\n            server_key = session_manager._get_server_key(params, \\\"streamable_http\\\")\\n            attributes[\\\"mcp.transport\\\"] = session_manager._transport_preference.get(server_key, \\\"streamable_http\\\")\\n            host = urlparse(params[\\\"url\\\"]).netloc.rsplit(\\\"@\\\", maxsplit=1)[-1]\\n            if host:\\n                attributes[\\\"mcp.server\\\"] = host\\n        return attributes\\n\\n    async def run_tool(self, tool_name: str, arguments: dict[str, Any], timeout: float | None = None) -> Any:  # noqa: ASYNC109\\n        \\\"\\\"\\\"Run the tool, with one application span covering the call and any retries.\\\"\\\"\\\"\\n        with outbound_call_span(MCP_TOOL_SPAN_NAME, self._tool_span_attributes(tool_name)) as span:\\n            result = await self._run_tool(tool_name, arguments, timeout)\\n            # See the stdio client: MCP reports tool failure in the result, not by raising.\\n            if getattr(result, \\\"isError\\\", False):\\n                span.record_error(\\\"ToolError\\\")\\n            return result\\n\\n    async def _run_tool(\\n        self,\\n        tool_name: str,\\n        arguments: dict[str, Any],\\n        timeout: float | None = None,  # noqa: ASYNC109\\n    ) -> Any:\\n        \\\"\\\"\\\"Run a tool with the given arguments using context-specific session.\\n\\n        Args:\\n            tool_name: Name of the tool to run\\n            arguments: Dictionary of arguments to pass to the tool\\n            timeout: Optional timeout in seconds. If not provided, uses the client's configured timeout.\\n\\n        Returns:\\n            The result of the tool execution\\n\\n        Raises:\\n            ValueError: If session is not initialized or tool execution fails\\n        \\\"\\\"\\\"\\n        if not self._connected or not self._connection_params:\\n            msg = \\\"Session not initialized or disconnected. Call connect_to_server first.\\\"\\n            raise ValueError(msg)\\n\\n        # If no session context is set, create a default one\\n        if not self._session_context:\\n            # Generate a fallback context based on connection parameters\\n            import uuid\\n\\n            param_hash = uuid.uuid4().hex[:8]\\n            self._session_context = f\\\"default_http_{param_hash}\\\"\\n\\n        # Use provided timeout or fall back to client's configured timeout\\n        effective_timeout = timeout if timeout is not None else self._tool_execution_timeout\\n\\n        max_retries = 2\\n        last_error_type = None\\n        last_error: Exception | None = None\\n\\n        for attempt in range(max_retries):\\n            try:\\n                await logger.adebug(f\\\"Attempting to run tool '{tool_name}' (attempt {attempt + 1}/{max_retries})\\\")\\n                # Get or create persistent session\\n                session = await self._get_or_create_session()\\n\\n                result = await asyncio.wait_for(\\n                    session.call_tool(tool_name, arguments=arguments),\\n                    timeout=effective_timeout,\\n                )\\n            except Exception as e:\\n                last_error = e\\n                current_error_type = type(e).__name__\\n                await logger.awarning(f\\\"Tool '{tool_name}' failed on attempt {attempt + 1}: {current_error_type} - {e}\\\")\\n\\n                bust_session = _is_mcp_session_bust_error(e)\\n\\n                # A server that answered with a status is not a transport fault: the branches\\n                # below match none of it, so it used to reach the caller as the raw TaskGroup\\n                # string. Retrying is pointless \u2014 the same call gets the same answer.\\n                if not bust_session and extract_http_status(e) is not None:\\n                    msg = describe_mcp_tool_failure(tool_name, (self._connection_params or {}).get(\\\"url\\\"), e)\\n                    await logger.aerror(msg)\\n                    self._connected = False\\n                    raise ValueError(msg) from e\\n\\n                # Detect timeout errors\\n                is_timeout_error = isinstance(e, asyncio.TimeoutError | TimeoutError)\\n\\n                # If we're getting the same error type repeatedly, don't retry\\n                if last_error_type == current_error_type and attempt > 0:\\n                    await logger.aerror(f\\\"Repeated {current_error_type} error for tool '{tool_name}', not retrying\\\")\\n                    break\\n\\n                last_error_type = current_error_type\\n\\n                if bust_session and attempt < max_retries - 1:\\n                    await logger.awarning(\\n                        f\\\"MCP session issue for tool '{tool_name}', invalidating server sessions and retrying...\\\"\\n                    )\\n                    if self._connection_params:\\n                        session_manager = self._get_session_manager()\\n                        sk = session_manager._get_server_key(self._connection_params, \\\"streamable_http\\\")\\n                        await session_manager.invalidate_server_key(sk)\\n                    await asyncio.sleep(0.5)\\n                    continue\\n\\n                # If it's a timeout error and we have retries left, try once more\\n                if is_timeout_error and attempt < max_retries - 1:\\n                    await logger.awarning(f\\\"Tool '{tool_name}' timed out, retrying...\\\")\\n                    # Don't clean up session for timeouts, might just be a slow response\\n                    await asyncio.sleep(1.0)\\n                    continue\\n\\n                # For other errors or no retries left, handle as before\\n                if (\\n                    isinstance(e, ConnectionError | TimeoutError | OSError | ValueError)\\n                    or bust_session\\n                    or is_timeout_error\\n                ):\\n                    msg = describe_mcp_tool_failure(tool_name, (self._connection_params or {}).get(\\\"url\\\"), e)\\n                    await logger.aerror(msg)\\n                    # Clean up failed session from cache\\n                    if self._session_context and self._component_cache:\\n                        cache_key = f\\\"mcp_session_http_{self._session_context}\\\"\\n                        self._component_cache.delete(cache_key)\\n                    self._connected = False\\n                    raise ValueError(msg) from e\\n                # Re-raise unexpected errors\\n                raise\\n            else:\\n                await logger.adebug(f\\\"Tool '{tool_name}' completed successfully\\\")\\n                return result\\n\\n        # This should never be reached due to the exception handling above\\n        msg = f\\\"Failed to run tool '{tool_name}': Maximum retries exceeded with repeated {last_error_type} errors\\\"\\n        await logger.aerror(msg)\\n        raise ValueError(msg) from last_error\\n\\n    async def disconnect(self):\\n        \\\"\\\"\\\"Properly close the connection and clean up resources.\\\"\\\"\\\"\\n        # Attempt best-effort remote session termination first\\n        await self._terminate_remote_session()\\n\\n        # Clean up local session using the session manager\\n        if self._session_context:\\n            session_manager = self._get_session_manager()\\n            await session_manager._cleanup_session(self._session_context)\\n\\n        # Reset local state\\n        self.session = None\\n        self._connection_params = None\\n        self._connected = False\\n        self._session_context = None\\n\\n    async def __aenter__(self):\\n        return self\\n\\n    async def __aexit__(self, exc_type, exc_val, exc_tb):\\n        await self.disconnect()\\n\\n\\n# Backward compatibility: MCPSseClient is now an alias for MCPStreamableHttpClient\\n# The new client supports both Streamable HTTP and SSE with automatic fallback\\nMCPSseClient = MCPStreamableHttpClient\\n\\n\\ndef _internal_mcp_hosts() -> set[str]:\\n    \\\"\\\"\\\"Operator-allowlisted internal MCP hosts (lowercased ``host`` / ``host:port``), or empty.\\n\\n    Empty by default (feature off / unset) so nothing is treated as internal \u2014 the fail-closed\\n    baseline for outbound end-user header injection.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        raw = get_settings_service().settings.serving_internal_mcp_hosts\\n    except (ImportError, AttributeError):\\n        return set()\\n    if not raw:\\n        return set()\\n    return {h.strip().lower() for h in raw.split(\\\",\\\") if h.strip()}\\n\\n\\ndef _is_internal_mcp_target(url: str) -> bool:\\n    \\\"\\\"\\\"Whether ``url``'s host is on the internal allowlist (exact host, or host:port).\\n\\n    Userinfo is stripped before matching (mirrors the session-key host parse elsewhere). A bare\\n    ``host`` allowlist entry matches any port; a ``host:port`` entry matches only that port.\\n    \\\"\\\"\\\"\\n    allowed = _internal_mcp_hosts()\\n    if not allowed:\\n        return False\\n    netloc = urlparse(url).netloc.rsplit(\\\"@\\\", maxsplit=1)[-1].lower()\\n    if not netloc:\\n        return False\\n    candidates = {netloc}\\n    # Also consider the bare host (strip a trailing :port; leave bracketed IPv6 intact).\\n    if not netloc.startswith(\\\"[\\\") and \\\":\\\" in netloc:\\n        candidates.add(netloc.rsplit(\\\":\\\", maxsplit=1)[0])\\n    return bool(candidates & allowed)\\n\\n\\ndef _maybe_inject_end_user_header(headers: dict, url: str, end_user_id: str | None) -> dict:\\n    \\\"\\\"\\\"Append the serving end-user identity header for INTERNAL/owned MCP targets only.\\n\\n    Fail-closed: the end-user id is PII, so it is forwarded ONLY when (a) an id is present,\\n    (b) the serving end-user header feature is configured, and (c) the target host is on the\\n    operator's internal allowlist. External servers \u2014 or any run without an end user / with the\\n    feature off \u2014 get the headers unchanged. This is what lets a sibling project on the same\\n    plane attribute the call to the same end user without leaking identity off-deployment.\\n    \\\"\\\"\\\"\\n    if not end_user_id:\\n        return headers\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        header_name = get_settings_service().settings.serving_end_user_header\\n    except (ImportError, AttributeError):\\n        header_name = None\\n    if not header_name or not _is_internal_mcp_target(url):\\n        return headers\\n    return validate_headers({**(headers or {}), header_name: end_user_id})\\n\\n\\nasync def update_tools(\\n    server_name: str,\\n    server_config: dict,\\n    mcp_stdio_client: MCPStdioClient | None = None,\\n    mcp_streamable_http_client: MCPStreamableHttpClient | None = None,\\n    mcp_sse_client: MCPStreamableHttpClient | None = None,  # Backward compatibility\\n    request_variables: dict[str, str] | None = None,\\n    tool_execution_timeout: float | None = None,\\n    current_user_id: str | UUID | None = None,\\n    end_user_id: str | None = None,\\n    url_variables: dict[str, str] | None = None,\\n) -> tuple[str, list[StructuredTool], dict[str, StructuredTool]]:\\n    \\\"\\\"\\\"Fetch server config and update available tools.\\n\\n    Args:\\n        server_name: Name of the MCP server\\n        server_config: Server configuration dictionary\\n        mcp_stdio_client: Optional stdio client instance\\n        mcp_streamable_http_client: Optional streamable HTTP client instance\\n        mcp_sse_client: Optional SSE client instance (backward compatibility)\\n        request_variables: Optional dict of global variables to resolve in headers. On a run\\n            these carry the caller's ``X-Langflow-Global-Var-*`` values, so they are trusted\\n            for headers only.\\n        url_variables: Global variables trusted to resolve the target URL. Kept separate from\\n            ``request_variables`` on purpose: resolving the URL from caller-supplied values\\n            would let whoever calls a flow choose where it connects \u2014 and the resolved\\n            credential headers travel to that destination. SSRF validation rejects internal\\n            targets, not an arbitrary external one.\\n        tool_execution_timeout: Optional timeout in seconds for tool execution (int or float)\\n        current_user_id: Authenticated user id of the caller. Injected into the env of the\\n            internal agentic MCP server (``langflow.agentic.mcp``) at spawn time so its tools are\\n            scoped to this user. Never sourced from the (tenant-controlled) server config.\\n        end_user_id: Serving-plane end-user identity of the run. Forwarded as the end-user header\\n            ONLY to operator-allowlisted internal hosts (fail-closed); external servers never\\n            receive it. None / feature-off means no header is appended (BC).\\n    \\\"\\\"\\\"\\n    if server_config is None:\\n        server_config = {}\\n    if not server_name:\\n        return \\\"\\\", [], {}\\n\\n    if mcp_stdio_client is None:\\n        mcp_stdio_client = MCPStdioClient(tool_execution_timeout=tool_execution_timeout)\\n    # Update timeout on existing client only if a new timeout is provided.\\n    # Route through _resolve_mcp_tool_execution_timeout so that negative values\\n    # (entered before UI validation fires) never reach asyncio.wait_for.\\n    elif tool_execution_timeout is not None:\\n        mcp_stdio_client._tool_execution_timeout = _resolve_mcp_tool_execution_timeout(tool_execution_timeout)\\n\\n    # Backward compatibility: accept mcp_sse_client parameter\\n    if mcp_streamable_http_client is None:\\n        if mcp_sse_client is not None:\\n            mcp_streamable_http_client = mcp_sse_client\\n            # Set timeout on the aliased client if provided\\n            if tool_execution_timeout is not None:\\n                mcp_streamable_http_client._tool_execution_timeout = _resolve_mcp_tool_execution_timeout(\\n                    tool_execution_timeout\\n                )\\n        else:\\n            mcp_streamable_http_client = MCPStreamableHttpClient(tool_execution_timeout=tool_execution_timeout)\\n    # Update timeout on existing client only if a new timeout is provided\\n    elif tool_execution_timeout is not None:\\n        mcp_streamable_http_client._tool_execution_timeout = _resolve_mcp_tool_execution_timeout(tool_execution_timeout)\\n\\n    # Fetch server config from backend\\n    # Determine mode from config, defaulting to Streamable_HTTP if URL present\\n    mode = server_config.get(\\\"mode\\\", \\\"\\\")\\n    if not mode:\\n        mode = \\\"Stdio\\\" if \\\"command\\\" in server_config else \\\"Streamable_HTTP\\\" if \\\"url\\\" in server_config else \\\"\\\"\\n\\n    command = server_config.get(\\\"command\\\", \\\"\\\")\\n    url = resolve_global_variables_in_url(server_config.get(\\\"url\\\", \\\"\\\"), url_variables)\\n    tools = []\\n    headers = _process_headers(server_config.get(\\\"headers\\\", {}), request_variables)\\n\\n    try:\\n        await _validate_connection_params(mode, command, url)\\n    except ValueError as e:\\n        logger.error(f\\\"Invalid MCP server configuration for '{server_name}': {e}\\\")\\n        raise\\n\\n    # Determine connection type and parameters\\n    client: MCPStdioClient | MCPStreamableHttpClient | None = None\\n    if mode == \\\"Stdio\\\":\\n        args = list(server_config.get(\\\"args\\\", []))\\n        # Resolved from the database set only, never from request_variables: env is handed\\n        # to a spawned process, so a caller-populated value is a worse hand-off than a URL.\\n        # Left literal, the reference the scrub writes would reach the subprocess as its key.\\n        env = _resolve_global_variables_in_headers(server_config.get(\\\"env\\\", {}) or {}, url_variables)\\n        # SECURITY: A tenant-built flow can embed this stdio config directly in the\\n        # MCPTools component value, bypassing REST-layer model validation. Enforce the\\n        # shared policy here, then enforce it again at the final process-spawn boundary.\\n        validate_mcp_stdio_config(command, args, env)\\n\\n        is_agentic_server = AGENTIC_MCP_MODULE in command or any(AGENTIC_MCP_MODULE in arg for arg in args)\\n        if is_agentic_server and not current_user_id:\\n            msg = \\\"The Langflow agentic MCP server requires an authenticated user context and cannot be used here.\\\"\\n            raise ValueError(msg)\\n        # `command` is a structured executable field, not a shell fragment. Keeping it\\n        # intact preserves legitimate executable paths that contain spaces.\\n        full_command = shlex.join([command, *args])\\n        if is_agentic_server and headers:\\n            tools = await mcp_stdio_client.connect_to_server(\\n                full_command,\\n                env,\\n                current_user_id=current_user_id,\\n                headers=headers,\\n            )\\n        elif is_agentic_server:\\n            tools = await mcp_stdio_client.connect_to_server(full_command, env, current_user_id=current_user_id)\\n        elif headers:\\n            tools = await mcp_stdio_client.connect_to_server(full_command, env, headers=headers)\\n        else:\\n            tools = await mcp_stdio_client.connect_to_server(full_command, env)\\n        client = mcp_stdio_client\\n    elif mode in [\\\"Streamable_HTTP\\\", \\\"SSE\\\"]:\\n        # Streamable HTTP connection with SSE fallback\\n        # SECURITY: a tenant-embedded MCP HTTP config could point at an internal service or\\n        # the cloud-metadata endpoint. Guard the URL with the same SSRF posture as other\\n        # outbound fetches (no-op when SSRF protection is disabled / host is allowlisted).\\n        validate_connector_url_for_ssrf(url)\\n        # Serving-plane: forward the end-user identity to a SIBLING project (an operator-\\n        # allowlisted internal host) so it attributes the run to the same end user. Fail-closed \u2014\\n        # external hosts never receive the PII header; no-op when the feature is off / no end user.\\n        headers = _maybe_inject_end_user_header(headers, url, end_user_id)\\n        verify_ssl = server_config.get(\\\"verify_ssl\\\", True)\\n        try:\\n            tools = await mcp_streamable_http_client.connect_to_server(url, headers=headers, verify_ssl=verify_ssl)\\n        except Exception as exc:\\n            # A rejected credential otherwise surfaced as \\\"unhandled errors in a TaskGroup\\\",\\n            # naming neither the target nor the fact that authentication was the problem.\\n            detail = describe_mcp_connection_failure(server_name, url, exc)\\n            logger.error(detail)\\n            raise ConnectionError(detail) from exc\\n        client = mcp_streamable_http_client\\n    else:\\n        logger.error(f\\\"Invalid MCP server mode for '{server_name}': {mode}\\\")\\n        return \\\"\\\", [], {}\\n\\n    if not tools or not client or not client._connected:\\n        logger.warning(f\\\"No tools available from MCP server '{server_name}' or connection failed\\\")\\n        return \\\"\\\", [], {}\\n\\n    tool_list = []\\n    tool_cache: dict[str, StructuredTool] = {}\\n    for tool in tools:\\n        if not tool or not hasattr(tool, \\\"name\\\"):\\n            continue\\n        try:\\n            args_schema = create_input_schema_from_json_schema(tool.inputSchema)\\n            if not args_schema:\\n                logger.warning(f\\\"Could not create schema for tool '{tool.name}' from server '{server_name}'\\\")\\n                continue\\n\\n            # Create a custom StructuredTool that bypasses schema validation\\n            class MCPStructuredTool(StructuredTool):\\n                _tool_call_id_key = \\\"_lf_tool_call_id\\\"\\n\\n                def _to_args_and_kwargs(\\n                    self, tool_input: str | dict, tool_call_id: str | None\\n                ) -> tuple[tuple, dict[str, Any]]:\\n                    \\\"\\\"\\\"Normalize MCP tool input before LangChain validates it.\\\"\\\"\\\"\\n                    if isinstance(tool_input, str):\\n                        try:\\n                            parsed_input = json.loads(tool_input)\\n                        except json.JSONDecodeError:\\n                            parsed_input = {\\\"input\\\": tool_input}\\n                    else:\\n                        parsed_input = tool_input or {}\\n\\n                    converted_input = self._convert_parameters(parsed_input)\\n                    tool_args, tool_kwargs = super()._to_args_and_kwargs(converted_input, tool_call_id)\\n                    if tool_call_id is not None:\\n                        tool_kwargs[self._tool_call_id_key] = tool_call_id\\n                    return tool_args, tool_kwargs\\n\\n                def _run(self, *args: Any, config: RunnableConfig, run_manager=None, **kwargs: Any) -> tuple[Any, Any]:\\n                    \\\"\\\"\\\"Return converted content plus the raw MCP result as artifact.\\\"\\\"\\\"\\n                    tool_call_id = kwargs.pop(self._tool_call_id_key, None)\\n                    raw = super()._run(*args, config=config, run_manager=run_manager, **kwargs)\\n                    content = _convert_mcp_result(raw) if tool_call_id and hasattr(raw, \\\"content\\\") else raw\\n                    return content, raw\\n\\n                async def _arun(\\n                    self, *args: Any, config: RunnableConfig, run_manager=None, **kwargs: Any\\n                ) -> tuple[Any, Any]:\\n                    \\\"\\\"\\\"Return converted content plus the raw MCP result as artifact.\\\"\\\"\\\"\\n                    tool_call_id = kwargs.pop(self._tool_call_id_key, None)\\n                    raw = await super()._arun(*args, config=config, run_manager=run_manager, **kwargs)\\n                    content = _convert_mcp_result(raw) if tool_call_id and hasattr(raw, \\\"content\\\") else raw\\n                    return content, raw\\n\\n                def _convert_parameters(self, input_dict):\\n                    if not input_dict or not isinstance(input_dict, dict):\\n                        return input_dict\\n\\n                    converted_dict = {}\\n                    original_fields = set(self.args_schema.model_fields.keys())\\n\\n                    for key, value in input_dict.items():\\n                        if key in original_fields:\\n                            # Field exists as-is\\n                            converted_dict[key] = value\\n                        else:\\n                            # Try to convert camelCase to snake_case\\n                            snake_key = _camel_to_snake(key)\\n                            if snake_key in original_fields:\\n                                converted_dict[snake_key] = value\\n                            else:\\n                                # Keep original key (may be flattened e.g. params.search)\\n                                converted_dict[key] = value\\n\\n                    unflattened = maybe_unflatten_dict(converted_dict)\\n                    # Normalize: convert JSON strings to dict for nested model params\\n                    normalized = _normalize_arguments_for_mcp(unflattened, self.args_schema, self.name)\\n                    # Preserve extra keys not in schema (e.g. flattened keys)\\n                    schema_fields = set(self.args_schema.model_fields.keys())\\n                    for key, value in unflattened.items():\\n                        if key not in schema_fields and key not in normalized:\\n                            normalized[key] = value\\n                    return normalized\\n\\n            if not MCPStructuredTool.__pydantic_complete__:\\n                MCPStructuredTool.model_rebuild(\\n                    _types_namespace={\\n                        \\\"Annotated\\\": Annotated,\\n                        \\\"ArgsSchema\\\": ArgsSchema,\\n                        \\\"SkipValidation\\\": SkipValidation,\\n                    }\\n                )\\n\\n            tool_obj = MCPStructuredTool(\\n                name=tool.name,\\n                description=tool.description or \\\"\\\",\\n                args_schema=args_schema,\\n                func=create_tool_func(tool.name, args_schema, client),\\n                coroutine=create_tool_coroutine(tool.name, args_schema, client),\\n                tags=[tool.name],\\n                metadata={\\\"server_name\\\": server_name, \\\"output_schema\\\": getattr(tool, \\\"outputSchema\\\", None)},\\n                response_format=\\\"content_and_artifact\\\",\\n            )\\n\\n            tool_list.append(tool_obj)\\n            tool_cache[tool.name] = tool_obj\\n        except (ConnectionError, TimeoutError, OSError, ValueError) as e:\\n            logger.error(f\\\"Failed to create tool '{tool.name}' from server '{server_name}': {e}\\\")\\n            msg = f\\\"Failed to create tool '{tool.name}' from server '{server_name}': {e}\\\"\\n            raise ValueError(msg) from e\\n        except (TypeError, AttributeError, KeyError, NameError, RecursionError) as e:\\n            # Per-tool resilience (#11229): isolate one bad schema, keep the rest of the toolset.\\n            logger.exception(\\n                f\\\"Skipping tool '{getattr(tool, 'name', '<unknown>')}' from MCP server \\\"\\n                f\\\"'{server_name}' due to schema-processing error: \\\"\\n                f\\\"{type(e).__name__}: {e}. inputSchema={getattr(tool, 'inputSchema', None)!r}\\\"\\n            )\\n            continue\\n\\n    logger.info(f\\\"Successfully loaded {len(tool_list)} tools from MCP server '{server_name}'\\\")\\n    return mode, tool_list, tool_cache\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/mcp/uvx.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5066c18ccf1cf02d875cc0794ff17be032195b1e8d9938ab25ada19a6e5ed0d6\",\"content\":\"\\\"\\\"\\\"Shared argv helpers for MCP servers that Langflow launches through ``uvx``.\\n\\n``uvx`` builds a fresh environment per invocation, so Langflow's own ``mcp`` pin never\\nreaches the server it spawns. The packages Langflow launches (``mcp-proxy``,\\n``mcp-composer``) declare an unbounded ``mcp>=1.x``, which now resolves to the 2.0 SDK --\\na release that removed ``request_ctx`` and renamed ``McpError``, so those packages fail\\nat import. Injecting the constraint as ``--with`` keeps the resolve on a compatible SDK.\\n\\\"\\\"\\\"\\n\\n# ``~=1.28`` is PEP 440 for \\\">=1.28, <2.0\\\" and, unlike ``mcp<2.0.0``, contains no character\\n# that the stdio command policy rejects as a shell metacharacter.\\nDEFAULT_MCP_SDK_CONSTRAINT = \\\"mcp~=1.28\\\"\\n\\n\\ndef mcp_sdk_constraint_args() -> list[str]:\\n    \\\"\\\"\\\"Return the ``uvx --with`` pair that pins the MCP SDK, or an empty list when disabled.\\n\\n    The result is meant to be spliced in ahead of the package operand::\\n\\n        [\\\"uvx\\\", *mcp_sdk_constraint_args(), \\\"mcp-proxy\\\", ...]\\n\\n    Operators disable the injection by setting ``LANGFLOW_MCP_SDK_CONSTRAINT`` to an empty\\n    string once upstream supports the 2.x SDK.\\n    \\\"\\\"\\\"\\n    constraint = _configured_constraint()\\n    if not constraint:\\n        return []\\n    return [\\\"--with\\\", constraint]\\n\\n\\ndef _configured_constraint() -> str:\\n    from lfx.services.deps import get_settings_service\\n\\n    try:\\n        value = getattr(get_settings_service().settings, \\\"mcp_sdk_constraint\\\", DEFAULT_MCP_SDK_CONSTRAINT)\\n    except Exception:  # noqa: BLE001 - settings can be unavailable during early imports\\n        return DEFAULT_MCP_SDK_CONSTRAINT\\n    if not isinstance(value, str):\\n        return DEFAULT_MCP_SDK_CONSTRAINT\\n    return value.strip()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/memory/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/memory/memory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9";
